window.ETSDATA=window.ETSDATA||{};window.ETSDATA[20]={"lc":{"p1":[{"n":1,"opts":["The man is reaching above a shelf.","The man is adjusting his glasses.","The man is paying for an item.","The man is trying on gloves."],"vi":["Người đàn ông đang với tay lên phía trên kệ.","Người đàn ông đang chỉnh kính của mình.","Người đàn ông đang trả tiền cho một món hàng.","Người đàn ông đang đeo thử găng tay."],"ans":"D","xp":"Trong ảnh, người đàn ông đứng trước giá treo đầy găng tay và đang xỏ thử một chiếc găng vào tay → (D) đúng (try on = mặc/đeo thử).\n(A) sai: anh ấy không với tay lên kệ. (B) sai: anh ấy đeo kính nhưng không chỉnh kính. (C) sai: không có cảnh trả tiền.","a":"E24-T10-01.mp3","img":"q1.jpg"},{"n":2,"opts":["She's opening an umbrella over a dining area.","She's standing on a patio near a house.","She's taking a tool out of a storage cupboard.","She's picking up some cushions off the ground."],"vi":["Cô ấy đang mở một cây dù phía trên khu vực ăn uống.","Cô ấy đang đứng trên sân hiên gần một ngôi nhà.","Cô ấy đang lấy một dụng cụ ra khỏi tủ chứa đồ.","Cô ấy đang nhặt mấy cái đệm lên khỏi mặt đất."],"ans":"B","xp":"Người phụ nữ đang đứng trên khoảng sân lát xi măng (patio) ngay trước một ngôi nhà gạch → (B) đúng.\n(A) sai: cây dù đã dựng sẵn, cô ấy không mở dù. (C) sai: cô ấy đang cầm cây vợt, không lấy đồ từ tủ. (D) sai: không nhặt đệm.","a":"E24-T10-02.mp3","img":"q2.jpg"},{"n":3,"opts":["They're raking some leaves.","They're shoveling soil into a bag.","They're working in a garden.","They're watering some flowers."],"vi":["Họ đang cào lá.","Họ đang xúc đất cho vào bao.","Họ đang làm việc trong một khu vườn.","Họ đang tưới hoa."],"ans":"C","xp":"Hai người đang cúi xuống chăm sóc cây trong một luống vườn → (C) \"working in a garden\" mô tả chung, đúng.\n(A) sai: không cầm cào. (B) sai: không xúc đất bằng xẻng. (D) sai: không tưới nước.","a":"E24-T10-03.mp3","img":"q3.jpg"},{"n":4,"opts":["Some food has been laid out on platters.","Some chairs are lined up against the wall.","Some floor tiles are being installed.","Some dinner plates have been placed in a sink."],"vi":["Thức ăn đã được bày ra trên đĩa lớn.","Mấy chiếc ghế được xếp thành hàng sát tường.","Gạch lát sàn đang được lắp đặt.","Đĩa ăn tối đã được đặt trong bồn rửa."],"ans":"A","xp":"Trên bàn có khay/đĩa lớn đựng đầy trái cây và bánh → (A) đúng (laid out on platters = bày trên đĩa lớn).\n(B) sai: ghế đặt quanh bàn, không xếp sát tường. (C) sai: không ai đang lát gạch (being installed). (D) sai: trong ảnh không có bồn rửa.","a":"E24-T10-04.mp3","img":"q4.jpg"},{"n":5,"opts":["A worker is changing a lightbulb.","A worker is handing a box to a customer.","A worker is crouching down behind a counter.","A worker is cleaning a window."],"vi":["Một nhân viên đang thay bóng đèn.","Một nhân viên đang đưa một chiếc hộp cho khách hàng.","Một nhân viên đang cúi khom người phía sau quầy.","Một nhân viên đang lau cửa sổ."],"ans":"C","xp":"Góc trái ảnh có một nhân viên đang ngồi khom xuống phía sau quầy → (C) đúng (crouch down = khom người, ngồi xổm).\n(A), (D) sai: không ai thay bóng đèn hay lau cửa sổ. (B) sai: không thấy cảnh nhân viên đưa hộp cho khách.","a":"E24-T10-05.mp3","img":"q5.jpg"},{"n":6,"opts":["Some potted plants are on both sides of an entrance.","An awning is shading a parking area.","Some signs are posted on a brick building.","Some furniture is propping open a door."],"vi":["Có những chậu cây ở hai bên một lối vào.","Một mái hiên đang che bóng cho bãi đậu xe.","Mấy tấm biển được treo trên một tòa nhà bằng gạch.","Một món đồ nội thất đang chặn để giữ cửa mở."],"ans":"A","xp":"Hai bên cửa ra vào của tòa nhà gạch có đặt các chậu cây → (A) đúng.\n(B) sai: có mái hiên nhưng không có bãi đậu xe. (C) sai: không thấy biển hiệu. (D) sai: không có đồ vật nào chặn giữ cửa mở.","a":"E24-T10-06.mp3","img":"q6.jpg"}],"p2":[{"n":7,"q":"When will you deliver the furniture I ordered?","qvi":"Khi nào anh sẽ giao món đồ nội thất tôi đã đặt?","opts":["By Tuesday at the latest.","To several clients.","I bought a trailer."],"vi":["Muộn nhất là thứ Ba.","Cho vài khách hàng.","Tôi đã mua một nhà di động (xe kéo)."],"ans":"A","xp":"Câu hỏi When → cần thời gian. (A) \"muộn nhất là thứ Ba\" trả lời đúng thời điểm giao hàng.\n(B) bẫy liên tưởng 'ordered' → clients. (C) bẫy liên tưởng 'ordered' → bought.","a":"E24-T10-07.mp3"},{"n":8,"q":"Is your flight tomorrow or this afternoon?","qvi":"Chuyến bay của bạn là ngày mai hay chiều nay?","opts":["In-flight snacks.","It's this afternoon.","At baggage claim."],"vi":["Đồ ăn nhẹ trên máy bay.","Là chiều nay.","Ở khu nhận hành lý."],"ans":"B","xp":"Câu hỏi lựa chọn (A hay B) → (B) chọn một trong hai: \"chiều nay\".\n(A) bẫy lặp từ 'flight'. (C) bẫy liên tưởng 'flight' → baggage claim.","a":"E24-T10-08.mp3"},{"n":9,"q":"How often does the research team schedule training sessions?","qvi":"Nhóm nghiên cứu lên lịch các buổi đào tạo bao lâu một lần?","opts":["The team leader, I think.","Some new software.","Every other week."],"vi":["Tôi nghĩ là trưởng nhóm.","Một vài phần mềm mới.","Hai tuần một lần."],"ans":"C","xp":"How often hỏi tần suất → (C) \"every other week\" = cách một tuần, tức 2 tuần/lần.\n(A) bẫy lặp từ 'team' (trả lời câu Who). (B) bẫy liên tưởng 'training' → software.","a":"E24-T10-09.mp3"},{"n":10,"q":"Can I pay my bill with a credit card?","qvi":"Tôi có thể thanh toán hóa đơn bằng thẻ tín dụng không?","opts":["Sure, that's fine.","I don't believe him either.","The gas station on your right."],"vi":["Được chứ, không sao cả.","Tôi cũng không tin anh ta.","Trạm xăng ở bên phải bạn."],"ans":"A","xp":"Câu xin phép (Can I...?) → (A) \"Sure, that's fine\" đồng ý.\n(B) bẫy: nghe 'bill' tưởng tên người Bill → him. (C) không liên quan.","a":"E24-T10-10.mp3"},{"n":11,"q":"The project proposal still needs work.","qvi":"Bản đề xuất dự án vẫn cần chỉnh sửa thêm.","opts":["The other office.","No, it's still not working.","I can help you with it."],"vi":["Văn phòng kia.","Không, nó vẫn không hoạt động.","Tôi có thể giúp bạn làm việc đó."],"ans":"C","xp":"Câu trần thuật nêu vấn đề → (C) đề nghị giúp đỡ, phản hồi tự nhiên.\n(A) bẫy liên tưởng 'work' → office. (B) bẫy từ cùng gốc work/working (working = hoạt động, máy móc).","a":"E24-T10-11.mp3"},{"n":12,"q":"Where do you plan to stay during your visit to the city?","qvi":"Bạn định ở đâu trong chuyến thăm thành phố?","opts":["I thought the building had twelve floors.","Oh, just to present at a conference.","At a friend's house."],"vi":["Tôi tưởng tòa nhà có mười hai tầng.","À, chỉ để thuyết trình tại một hội nghị thôi.","Ở nhà một người bạn."],"ans":"C","xp":"Where hỏi nơi chốn → (C) \"ở nhà một người bạn\".\n(A) bẫy liên tưởng 'city' → building. (B) trả lời cho câu hỏi Why (mục đích chuyến đi), không phải Where.","a":"E24-T10-12.mp3"},{"n":13,"q":"How did you improve the processing speed?","qvi":"Bạn đã cải thiện tốc độ xử lý bằng cách nào?","opts":["That's a question for Silvia.","What's the speed limit?","I don't like to swim."],"vi":["Câu đó bạn nên hỏi Silvia.","Giới hạn tốc độ là bao nhiêu?","Tôi không thích bơi."],"ans":"A","xp":"Câu hỏi How (cách làm) → (A) trả lời gián tiếp: người biết câu trả lời là Silvia (người khác làm việc đó).\n(B) bẫy lặp từ 'speed'. (C) không liên quan.","a":"E24-T10-13.mp3"},{"n":14,"q":"Do you take exercise classes too, or just dance classes?","qvi":"Bạn có học cả lớp thể dục nữa không, hay chỉ học lớp nhảy?","opts":["The instructor teaches in the mornings.","These shoes fit perfectly.","I only take dance."],"vi":["Người hướng dẫn dạy vào buổi sáng.","Đôi giày này vừa khít.","Tôi chỉ học nhảy thôi."],"ans":"C","xp":"Câu hỏi lựa chọn → (C) chọn vế sau: \"chỉ học nhảy\".\n(A) bẫy liên tưởng 'classes' → instructor. (B) bẫy liên tưởng 'exercise' → shoes.","a":"E24-T10-14.mp3"},{"n":15,"q":"When will the new coffee machine be installed in the lobby?","qvi":"Khi nào máy pha cà phê mới sẽ được lắp ở sảnh?","opts":["No, it wasn't expensive.","The front door is unlocked.","Within the next few days."],"vi":["Không, nó không đắt.","Cửa trước không khóa.","Trong vài ngày tới."],"ans":"C","xp":"When hỏi thời gian → (C) \"trong vài ngày tới\".\n(A) sai: câu hỏi Wh- không trả lời bằng Yes/No. (B) bẫy liên tưởng 'lobby' → front door.","a":"E24-T10-15.mp3"},{"n":16,"q":"The new marketing director will be hired soon, won't she?","qvi":"Giám đốc marketing mới sẽ sớm được tuyển, phải không?","opts":["Didn't you check your e-mail?","It's about ten minutes from here.","No, a little lower."],"vi":["Bạn chưa kiểm tra e-mail à?","Cách đây khoảng mười phút.","Không, thấp hơn một chút."],"ans":"A","xp":"Câu hỏi đuôi xác nhận thông tin → (A) hỏi ngược lại một cách gián tiếp: thông tin đã có trong e-mail rồi (xem e-mail sẽ biết).\n(B) bẫy liên tưởng 'soon' → ten minutes. (C) bẫy âm: 'hired' nghe giống 'higher' → lower.","a":"E24-T10-16.mp3"},{"n":17,"q":"I really need some help with the presentation graphics.","qvi":"Tôi thực sự cần người giúp làm phần hình ảnh cho bài thuyết trình.","opts":["Insook can do those for you.","A conference in Chicago.","No, in Research and Development."],"vi":["Insook có thể làm giúp bạn.","Một hội nghị ở Chicago.","Không, ở phòng Nghiên cứu và Phát triển."],"ans":"A","xp":"Câu trần thuật nhờ giúp đỡ → (A) giới thiệu người có thể giúp (Insook).\n(B) bẫy liên tưởng 'presentation' → conference. (C) bẫy liên tưởng 'presentation' → Research.","a":"E24-T10-17.mp3"},{"n":18,"q":"Who can I talk to about scheduling a haircut?","qvi":"Tôi có thể nói chuyện với ai về việc đặt lịch cắt tóc?","opts":["Will you be available tomorrow afternoon?","Not too short on the sides, please.","Thanks, the scheduling software has been helpful!"],"vi":["Chiều mai bạn có rảnh không?","Làm ơn đừng cắt hai bên ngắn quá.","Cảm ơn, phần mềm xếp lịch rất hữu ích!"],"ans":"A","xp":"Câu hỏi Who → (A) trả lời gián tiếp: người nói tự đặt lịch luôn bằng cách hỏi giờ rảnh (tức là \"nói với tôi được\").\n(B) bẫy liên tưởng 'haircut' → short on the sides. (C) bẫy lặp từ 'scheduling'.","a":"E24-T10-18.mp3"},{"n":19,"q":"Did you already prepare the agenda for the department meeting?","qvi":"Bạn đã chuẩn bị chương trình nghị sự cho cuộc họp phòng ban chưa?","opts":["We should close the windows.","It was postponed.","I bought them at the department store."],"vi":["Chúng ta nên đóng cửa sổ lại.","Cuộc họp đã bị hoãn rồi.","Tôi mua chúng ở cửa hàng bách hóa."],"ans":"B","xp":"Câu hỏi Yes/No → (B) trả lời gián tiếp: cuộc họp bị hoãn nên chưa cần chuẩn bị.\n(A) không liên quan. (C) bẫy lặp từ 'department'.","a":"E24-T10-19.mp3"},{"n":20,"q":"Do you take your coffee with or without milk?","qvi":"Bạn uống cà phê có sữa hay không sữa?","opts":["The coffee shop on Bayview Avenue.","I prefer drinking tea.","We'll need to place an order for paper."],"vi":["Quán cà phê trên đại lộ Bayview.","Tôi thích uống trà hơn.","Chúng ta sẽ cần đặt mua giấy."],"ans":"B","xp":"Câu hỏi lựa chọn → (B) không chọn cả hai mà đưa ra phương án thứ ba: thích uống trà hơn.\n(A) bẫy lặp từ 'coffee'. (C) bẫy liên tưởng 'take your coffee' → place an order.","a":"E24-T10-20.mp3"},{"n":21,"q":"Why are you installing new software?","qvi":"Tại sao bạn lại cài phần mềm mới?","opts":["Because our current software is outdated.","We rented a large stall.","I'm going to wear a jacket."],"vi":["Vì phần mềm hiện tại của chúng ta đã lỗi thời.","Chúng tôi đã thuê một gian hàng lớn.","Tôi sẽ mặc áo khoác."],"ans":"A","xp":"Why hỏi lý do → (A) \"Because...\" phần mềm hiện tại đã cũ (outdated).\n(B) bẫy âm: 'installing' – 'stall'. (C) bẫy âm: 'software' – 'wear'.","a":"E24-T10-21.mp3"},{"n":22,"q":"When will next month's cost projections be ready?","qvi":"Khi nào bản dự toán chi phí của tháng sau sẽ xong?","opts":["That portable projector was recently replaced.","An unexpected surplus.","I sent an e-mail a few minutes ago."],"vi":["Cái máy chiếu di động đó mới được thay gần đây.","Một khoản thặng dư bất ngờ.","Tôi đã gửi e-mail vài phút trước rồi."],"ans":"C","xp":"When hỏi thời gian → (C) trả lời gián tiếp: bản dự toán đã xong và đã gửi qua e-mail.\n(A) bẫy từ cùng gốc projections – projector. (B) bẫy liên tưởng 'cost' → surplus.","a":"E24-T10-22.mp3"},{"n":23,"q":"Would you ask Tae-Joon to help set up the product display?","qvi":"Bạn nhờ Tae-Joon giúp sắp xếp khu trưng bày sản phẩm được không?","opts":["Several kinds of headsets.","No, I can do it myself.","I can't see the bottom line of the chart."],"vi":["Vài loại tai nghe.","Không cần, tôi tự làm được.","Tôi không nhìn thấy dòng dưới cùng của biểu đồ."],"ans":"B","xp":"Câu đề nghị/nhờ vả → (B) từ chối và nêu lý do: tự làm được.\n(A) bẫy âm: 'help set' – 'headsets'. (C) không liên quan.","a":"E24-T10-23.mp3"},{"n":24,"q":"Which version of the contract do you have?","qvi":"Bạn đang có phiên bản nào của hợp đồng?","opts":["He's a general contractor.","On the second floor.","The final one."],"vi":["Anh ấy là nhà thầu chính.","Ở tầng hai.","Bản cuối cùng."],"ans":"C","xp":"Which hỏi lựa chọn cụ thể → (C) \"bản cuối cùng\" (the ~ one là kiểu trả lời hay gặp cho Which).\n(A) bẫy từ cùng gốc contract – contractor. (B) trả lời cho Where.","a":"E24-T10-24.mp3"},{"n":25,"q":"Why isn't Ms. Pérez here yet?","qvi":"Tại sao cô Pérez vẫn chưa đến?","opts":["No, I can't hear anything.","Company headquarters.","Because she's meeting with her manager."],"vi":["Không, tôi không nghe thấy gì cả.","Trụ sở công ty.","Vì cô ấy đang họp với quản lý của cô ấy."],"ans":"C","xp":"Why hỏi lý do → (C) \"Because...\" cô ấy đang họp với quản lý.\n(A) bẫy âm: 'here' – 'hear'. (B) không liên quan.","a":"E24-T10-25.mp3"},{"n":26,"q":"I heard that our company might be merging with another one.","qvi":"Tôi nghe nói công ty chúng ta có thể sắp sáp nhập với một công ty khác.","opts":["Oh, I didn't know that.","A good-selling product.","Akira told me to put it there."],"vi":["Ồ, tôi không biết chuyện đó.","Một sản phẩm bán chạy.","Akira bảo tôi đặt nó ở đó."],"ans":"A","xp":"Câu trần thuật đưa tin → (A) phản hồi tự nhiên: \"tôi không biết chuyện đó\".\n(B) bẫy liên tưởng 'company' → product. (C) không liên quan.","a":"E24-T10-26.mp3"},{"n":27,"q":"Could you ask the next patient to come in?","qvi":"Bạn mời bệnh nhân tiếp theo vào được không?","opts":["It's in the cabinet.","The waiting room is empty.","They're both studying nursing."],"vi":["Nó ở trong tủ.","Phòng chờ đang trống.","Cả hai người họ đều đang học ngành điều dưỡng."],"ans":"B","xp":"Câu nhờ vả → (B) trả lời gián tiếp: phòng chờ trống, tức là không còn bệnh nhân nào.\n(A) không liên quan. (C) bẫy liên tưởng 'patient' → nursing.","a":"E24-T10-27.mp3"},{"n":28,"q":"Are the blueberries ready to harvest?","qvi":"Việt quất đã đến lúc thu hoạch chưa?","opts":["I'll try the strawberry flavor.","We have a view of the beach.","It's not summertime yet."],"vi":["Tôi sẽ thử vị dâu tây.","Chúng tôi có thể ngắm cảnh bãi biển.","Vẫn chưa đến mùa hè mà."],"ans":"C","xp":"Câu hỏi Yes/No → (C) trả lời gián tiếp: chưa đến mùa hè nên chưa thu hoạch được.\n(A) bẫy âm: 'blueberries' – 'strawberry'. (B) không liên quan.","a":"E24-T10-28.mp3"},{"n":29,"q":"How long will it take us to get to the theater?","qvi":"Chúng ta đi đến nhà hát mất bao lâu?","opts":["Tickets for the performance are sold-out.","At seven o'clock, I think.","Actually, I don't have a preference."],"vi":["Vé xem buổi diễn đã bán hết rồi.","Tôi nghĩ là lúc bảy giờ.","Thật ra tôi không có ưu tiên gì."],"ans":"A","xp":"How long hỏi thời gian di chuyển → (A) trả lời gián tiếp: vé đã bán hết nên không cần đến nhà hát nữa.\n(B) trả lời cho When (mốc giờ), không phải khoảng thời gian. (C) là câu trả lời cho câu hỏi lựa chọn.","a":"E24-T10-29.mp3"},{"n":30,"q":"Are you going to send a report or give a presentation to our clients?","qvi":"Bạn sẽ gửi báo cáo hay thuyết trình cho khách hàng của chúng ta?","opts":["We enjoyed their talk.","I'll probably do both.","Twenty people attended."],"vi":["Chúng tôi rất thích bài nói của họ.","Có lẽ tôi sẽ làm cả hai.","Hai mươi người đã tham dự."],"ans":"B","xp":"Câu hỏi lựa chọn → (B) chọn cả hai phương án: \"có lẽ làm cả hai\".\n(A) bẫy liên tưởng 'presentation' → talk. (C) bẫy liên tưởng 'clients' → twenty people.","a":"E24-T10-30.mp3"},{"n":31,"q":"When should we hang up the posters for our conference?","qvi":"Khi nào chúng ta nên treo áp phích cho hội nghị?","opts":["Sure, my car will be fixed soon.","Next to the main entrance.","The design still needs to be finalized."],"vi":["Được thôi, xe tôi sẽ sớm được sửa xong.","Cạnh lối vào chính.","Thiết kế vẫn còn cần hoàn thiện."],"ans":"C","xp":"When hỏi thời điểm → (C) trả lời gián tiếp: thiết kế chưa xong nên chưa treo được, cần thêm thời gian.\n(A) sai: 'Sure' là kiểu trả lời Yes, không hợp với câu hỏi When. (B) trả lời cho Where.","a":"E24-T10-31.mp3"}],"p3":[{"ns":[32,34],"script":[["M","Welcome to the Firelamp Bistro. How many for dinner?","Chào mừng quý khách đến với nhà hàng Firelamp Bistro. Quý khách dùng bữa tối mấy người ạ?"],["W","There'll be five of us, but I'm afraid I forgot to make a reservation.","Chúng tôi có năm người, nhưng e là tôi quên đặt bàn trước rồi."],["M","No problem. But I should mention that we'll be closing earlier than usual this evening for a private event. If you'd like to sit outdoors on the patio while you wait, I'll send a server to get you started with drinks and appetizers. We'll get you seated as soon as possible.","Không sao ạ. Nhưng tôi xin báo trước là tối nay chúng tôi sẽ đóng cửa sớm hơn thường lệ vì có một sự kiện riêng. Nếu quý khách muốn ngồi ngoài sân hiên trong lúc chờ, tôi sẽ cho nhân viên phục vụ mang đồ uống và món khai vị ra trước. Chúng tôi sẽ xếp chỗ cho quý khách sớm nhất có thể."],["W","That sounds fine. Thank you. And if possible, we'd like to sit in a quieter part of the restaurant. We have some business to discuss.","Vậy được. Cảm ơn anh. Và nếu được, chúng tôi muốn ngồi ở khu yên tĩnh hơn trong nhà hàng. Chúng tôi có chút việc cần bàn."]],"qs":[{"n":32,"q":"What did the woman forget to do?","qvi":"Người phụ nữ đã quên làm gì?","opts":["Ask about menu choices","Reserve a table","Invite a colleague","Bring a parking permit"],"vi":["Hỏi về các lựa chọn trong thực đơn","Đặt bàn","Mời một đồng nghiệp","Mang theo giấy phép đỗ xe"],"ans":"B","xp":"Người phụ nữ nói: \"I'm afraid I forgot to make a reservation.\" (Tôi quên đặt chỗ trước). make a reservation = Reserve a table → (B)."},{"n":33,"q":"What does the man say about the restaurant?","qvi":"Người đàn ông nói gì về nhà hàng?","opts":["There are more customers than usual.","There is an upstairs area for parties.","The business hours are different today.","The waitstaff is new."],"vi":["Có nhiều khách hơn thường lệ.","Có một khu trên lầu dành cho tiệc.","Giờ mở cửa hôm nay khác mọi ngày.","Đội ngũ phục vụ là người mới."],"ans":"C","xp":"Người đàn ông nói: \"we'll be closing earlier than usual this evening for a private event.\" Đóng cửa sớm hơn thường lệ tối nay = giờ hoạt động hôm nay khác (The business hours are different today) → (C)."},{"n":34,"q":"What does the woman request?","qvi":"Người phụ nữ yêu cầu điều gì?","opts":["A group discount","A special menu item","To be seated in a quiet area","To be seated near a window"],"vi":["Giảm giá cho nhóm","Một món đặc biệt trong thực đơn","Được xếp ngồi ở khu yên tĩnh","Được xếp ngồi gần cửa sổ"],"ans":"C","xp":"Cuối hội thoại, người phụ nữ nói: \"we'd like to sit in a quieter part of the restaurant.\" a quieter part of the restaurant = a quiet area → (C)."}],"a":"E24-T10-32-34.mp3"},{"ns":[35,37],"script":[["W1","Hi, Suresh. Office World Incorporated is thrilled about this collaboration with your company. Your signature line of office products looks great, and we believe they'll sell quite well. We're looking forward to partnering with you.","Chào Suresh. Công ty Office World rất hào hứng về đợt hợp tác này với công ty anh. Dòng sản phẩm văn phòng đặc trưng của anh trông rất tuyệt, và chúng tôi tin rằng chúng sẽ bán khá chạy. Chúng tôi rất mong được hợp tác với anh."],["M","Thanks. I look forward to a good working partnership as well. And I'm proud of the fact that all my products are made with recycled materials. I want to promote environmental responsibility.","Cảm ơn chị. Tôi cũng mong chúng ta sẽ hợp tác tốt đẹp. Và tôi tự hào vì tất cả sản phẩm của tôi đều được làm từ vật liệu tái chế. Tôi muốn khuyến khích tinh thần có trách nhiệm với môi trường."],["W1","I'm impressed! Ah, and here is Vedika with her camera equipment.","Thật ấn tượng! À, Vedika đến rồi kìa, cô ấy mang theo thiết bị chụp ảnh."],["W2","Hello—I'm here to take some promotional photos. I'd like to get some shots of you with your products, Suresh. We want to post them online.","Xin chào. Tôi đến để chụp vài tấm ảnh quảng bá. Tôi muốn chụp vài tấm anh đứng cùng sản phẩm của mình, Suresh. Chúng tôi muốn đăng chúng lên mạng."]],"qs":[{"n":35,"q":"What is the conversation mainly about?","qvi":"Cuộc hội thoại chủ yếu nói về điều gì?","opts":["A company training initiative","A factory relocation plan","A business collaboration","An upcoming press conference"],"vi":["Một chương trình đào tạo của công ty","Kế hoạch di dời nhà máy","Một sự hợp tác kinh doanh","Một cuộc họp báo sắp tới"],"ans":"C","xp":"Ngay đầu bài: \"Office World Incorporated is thrilled about this collaboration with your company.\" và người đàn ông đáp \"I look forward to a good working partnership\" → chủ đề là hợp tác kinh doanh → (C)."},{"n":36,"q":"What does the man emphasize about some products?","qvi":"Người đàn ông nhấn mạnh điều gì về các sản phẩm?","opts":["They have a low price point.","They can easily be customized.","They are designed to be durable.","They are made of recycled materials."],"vi":["Chúng có mức giá thấp.","Chúng có thể dễ dàng được làm theo yêu cầu riêng.","Chúng được thiết kế để bền.","Chúng được làm từ vật liệu tái chế."],"ans":"D","xp":"Người đàn ông nói: \"I'm proud of the fact that all my products are made with recycled materials.\" → (D)."},{"n":37,"q":"Why has Vedika joined the meeting?","qvi":"Tại sao Vedika tham gia buổi gặp?","opts":["To discuss sales results","To take some photographs","To conduct an interview","To go over customer feedback"],"vi":["Để thảo luận kết quả bán hàng","Để chụp một số bức ảnh","Để thực hiện một cuộc phỏng vấn","Để xem xét phản hồi của khách hàng"],"ans":"B","xp":"Vedika nói: \"I'm here to take some promotional photos.\" take some promotional photos = take some photographs → (B)."}],"a":"E24-T10-35-37.mp3"},{"ns":[38,40],"script":[["M","Hi, Lirong. Thanks for meeting with me. I'd like to consider advertising strategies for our bicycle shop during the annual charity bicycle race.","Chào Lirong. Cảm ơn chị đã gặp tôi. Tôi muốn bàn về các chiến lược quảng cáo cho cửa hàng xe đạp của chúng ta trong cuộc đua xe đạp từ thiện thường niên."],["W","Well, like last year, as one of the sponsors of the event, we'll have our company name printed on the banner.","À, giống năm ngoái, với tư cách là một trong các nhà tài trợ của sự kiện, tên công ty mình sẽ được in trên băng rôn."],["M","Great, but this year, I'd also like us to donate our top-of-the-line bicycle to the winner of the race to show how much we care about our community.","Tốt, nhưng năm nay tôi cũng muốn chúng ta tặng chiếc xe đạp cao cấp nhất của cửa hàng cho người thắng cuộc đua để thể hiện chúng ta quan tâm đến cộng đồng như thế nào."],["W","That's a nice idea, but sponsoring the race is already going to be costly. I'm worried about the added expense of donating a bicycle as well.","Ý hay đấy, nhưng việc tài trợ cuộc đua đã tốn kém lắm rồi. Tôi lo về khoản chi phí phát sinh nếu tặng thêm một chiếc xe đạp nữa."]],"qs":[{"n":38,"q":"What event are the speakers discussing?","qvi":"Những người nói đang thảo luận về sự kiện gì?","opts":["An annual sales promotion","A company picnic","An office health fair","A charity bike race"],"vi":["Một đợt khuyến mãi thường niên","Một buổi dã ngoại của công ty","Một hội chợ sức khỏe tại văn phòng","Một cuộc đua xe đạp từ thiện"],"ans":"D","xp":"Người đàn ông nói: \"advertising strategies for our bicycle shop during the annual charity bicycle race.\" charity bicycle race = charity bike race → (D)."},{"n":39,"q":"What does the man suggest doing this year?","qvi":"Người đàn ông đề xuất làm gì trong năm nay?","opts":["Hiring a caterer","Donating a prize","Changing a location","Updating a logo"],"vi":["Thuê dịch vụ ăn uống","Tặng một giải thưởng","Thay đổi địa điểm","Cập nhật logo"],"ans":"B","xp":"Người đàn ông nói: \"this year, I'd also like us to donate our top-of-the-line bicycle to the winner of the race.\" Tặng xe đạp cho người thắng cuộc = tặng một giải thưởng (Donating a prize) → (B)."},{"n":40,"q":"What concern does the woman express?","qvi":"Người phụ nữ bày tỏ mối lo ngại gì?","opts":["A proposal may be too costly.","An employee needs further training.","A guest speaker is not available.","A shipment has been delayed."],"vi":["Một đề xuất có thể quá tốn kém.","Một nhân viên cần được đào tạo thêm.","Một diễn giả khách mời không đến được.","Một lô hàng bị giao trễ."],"ans":"A","xp":"Người phụ nữ nói: \"sponsoring the race is already going to be costly. I'm worried about the added expense of donating a bicycle as well.\" → lo ngại đề xuất tặng xe quá tốn kém → (A)."}],"a":"E24-T10-38-40.mp3"},{"ns":[41,43],"script":[["M","Welcome, Farida, and here's your identification badge. My name's Malik Aljohani. I'm a senior engineer, and during your first 60 days at Tilmer Tech, I'll be mentoring you throughout the new-employee onboarding process.","Chào mừng Farida, đây là thẻ nhân viên của bạn. Tôi là Malik Aljohani. Tôi là kỹ sư cấp cao, và trong 60 ngày đầu tiên của bạn tại Tilmer Tech, tôi sẽ hướng dẫn bạn trong suốt quá trình hội nhập dành cho nhân viên mới."],["W","I'm glad to be here—your company's one of the top manufacturers of robotic vacuum cleaners in the country. Since I just graduated from university, it's exciting to be applying all that theory directly to this engineering job.","Tôi rất vui được đến đây. Công ty anh là một trong những nhà sản xuất máy hút bụi robot hàng đầu cả nước. Vì tôi vừa tốt nghiệp đại học, thật thú vị khi được áp dụng tất cả lý thuyết đó trực tiếp vào công việc kỹ sư này."],["M","Absolutely! And right now we're headed to your first activity for today. Like all new engineers here, you'll be tasked with taking apart and reassembling our top-selling product. It's a first step in helping you become knowledgeable about how our product functions.","Đúng vậy! Và bây giờ chúng ta sẽ đến hoạt động đầu tiên của bạn hôm nay. Giống như mọi kỹ sư mới ở đây, bạn sẽ được giao nhiệm vụ tháo rời rồi lắp ráp lại sản phẩm bán chạy nhất của chúng tôi. Đó là bước đầu tiên giúp bạn hiểu rõ sản phẩm của chúng tôi hoạt động ra sao."]],"qs":[{"n":41,"q":"Who is the man?","qvi":"Người đàn ông là ai?","opts":["A security guard","A photographer","An engineer","A safety inspector"],"vi":["Nhân viên bảo vệ","Nhiếp ảnh gia","Kỹ sư","Thanh tra an toàn"],"ans":"C","xp":"Người đàn ông tự giới thiệu: \"I'm a senior engineer.\" → (C)."},{"n":42,"q":"What product does the company manufacture?","qvi":"Công ty sản xuất sản phẩm gì?","opts":["Drones","Sound systems","Car engines","Vacuum cleaners"],"vi":["Máy bay không người lái","Hệ thống âm thanh","Động cơ ô tô","Máy hút bụi"],"ans":"D","xp":"Người phụ nữ nói: \"your company's one of the top manufacturers of robotic vacuum cleaners in the country.\" → (D)."},{"n":43,"q":"What will the woman most likely do next?","qvi":"Người phụ nữ nhiều khả năng sẽ làm gì tiếp theo?","opts":["Report a lost badge","Tour a facility","Work on an assigned task","Fill out some paperwork"],"vi":["Báo mất thẻ","Tham quan cơ sở","Thực hiện một nhiệm vụ được giao","Điền một số giấy tờ"],"ans":"C","xp":"Người đàn ông nói: \"right now we're headed to your first activity for today... you'll be tasked with taking apart and reassembling our top-selling product.\" → cô ấy sắp làm nhiệm vụ được giao (tháo rời và lắp lại sản phẩm) → (C)."}],"a":"E24-T10-41-43.mp3"},{"ns":[44,46],"script":[["M","Hey, Jyoti. I can't believe it. You know how I told you that I won some tickets to my favorite basketball team's championship for this weekend? Well, now I can't go.","Này Jyoti. Không thể tin được. Chị nhớ tôi đã kể là tôi trúng mấy vé xem trận chung kết của đội bóng rổ tôi yêu thích vào cuối tuần này không? Giờ thì tôi không đi được rồi."],["W","Why? What happened? You look really disappointed.","Sao vậy? Có chuyện gì thế? Trông anh thất vọng lắm."],["M","One of my clients has requested a rush on their order. I'll need to do a quality check on all the products so we can ship by Monday morning.","Một khách hàng của tôi yêu cầu làm gấp đơn hàng của họ. Tôi sẽ phải kiểm tra chất lượng toàn bộ sản phẩm để kịp giao hàng trước sáng thứ Hai."],["W","Well, I'm free this weekend. Why don't I take over for you? Just let your supervisor know that I can do the quality check. You can help me out next weekend.","À, cuối tuần này tôi rảnh. Hay để tôi làm thay anh nhé? Anh chỉ cần báo với quản lý là tôi có thể kiểm tra chất lượng. Cuối tuần sau anh giúp lại tôi là được."]],"qs":[{"n":44,"q":"What was the man hoping to do this weekend?","qvi":"Người đàn ông đã mong được làm gì vào cuối tuần này?","opts":["Go on a camping trip","Perform in a local band","Attend a sports competition","Volunteer at a community center"],"vi":["Đi cắm trại","Biểu diễn trong một ban nhạc địa phương","Đi xem một trận thi đấu thể thao","Làm tình nguyện ở trung tâm cộng đồng"],"ans":"C","xp":"Người đàn ông nói: \"I won some tickets to my favorite basketball team's championship for this weekend.\" Trận chung kết bóng rổ = a sports competition → (C)."},{"n":45,"q":"Why does the man need to cancel his plans?","qvi":"Tại sao người đàn ông phải hủy kế hoạch?","opts":["A client has made a request.","An event has been postponed.","A coworker is unavailable.","A flight was canceled."],"vi":["Một khách hàng đã đưa ra yêu cầu.","Một sự kiện bị hoãn.","Một đồng nghiệp không có mặt được.","Một chuyến bay bị hủy."],"ans":"A","xp":"Người đàn ông giải thích: \"One of my clients has requested a rush on their order.\" (khách hàng yêu cầu làm gấp đơn hàng) → requested = made a request → (A)."},{"n":46,"q":"What does the woman offer to do?","qvi":"Người phụ nữ đề nghị làm gì?","opts":["Change a reservation","Check some products","Speak to the man's supervisor","Give the man a ride"],"vi":["Thay đổi đặt chỗ","Kiểm tra một số sản phẩm","Nói chuyện với quản lý của người đàn ông","Cho người đàn ông đi nhờ xe"],"ans":"B","xp":"Anh ấy cần \"do a quality check on all the products\"; cô ấy nói: \"Why don't I take over for you?\" → cô ấy đề nghị làm thay việc kiểm tra sản phẩm → (B).\n(C) sai: cô ấy bảo chính anh ấy báo cho quản lý (\"Just let your supervisor know\")."}],"a":"E24-T10-44-46.mp3"},{"ns":[47,49],"script":[["W","I understand that you've found a good candidate to deliver the keynote speech at our conference.","Tôi nghe nói anh đã tìm được một ứng viên tốt để phát biểu chính tại hội nghị của chúng ta."],["M","I have. Dr. Murad Jebreen. He's a specialist in sports medicine, and he's developed new surgical techniques for athletes with knee injuries. His new book on the topic will be published later this month, actually.","Đúng vậy. Đó là bác sĩ Murad Jebreen. Ông ấy là chuyên gia về y học thể thao, và đã phát triển các kỹ thuật phẫu thuật mới cho vận động viên bị chấn thương đầu gối. Thật ra cuốn sách mới của ông ấy về chủ đề này sẽ được xuất bản vào cuối tháng này."],["W","Oh, yes. I've heard of him. I wonder if we have enough money to give copies to everyone who comes to the conference.","À vâng, tôi có nghe nói về ông ấy. Không biết chúng ta có đủ tiền để tặng sách cho tất cả mọi người đến dự hội nghị không nhỉ."],["M","I can check our budget.","Tôi có thể kiểm tra ngân sách."]],"qs":[{"n":47,"q":"What was the man asked to do in preparation for a conference?","qvi":"Người đàn ông được yêu cầu làm gì để chuẩn bị cho hội nghị?","opts":["Choose a caterer","Book the conference rooms","Find a keynote speaker","Make travel arrangements"],"vi":["Chọn đơn vị cung cấp đồ ăn","Đặt phòng hội nghị","Tìm diễn giả phát biểu chính","Sắp xếp việc đi lại"],"ans":"C","xp":"Người phụ nữ nói: \"you've found a good candidate to deliver the keynote speech at our conference.\" → anh ấy được giao tìm người phát biểu chính (keynote speaker) → (C)."},{"n":48,"q":"Who is the conference intended for?","qvi":"Hội nghị dành cho đối tượng nào?","opts":["Baseball coaches","Medical doctors","Accountants","Publishers"],"vi":["Huấn luyện viên bóng chày","Bác sĩ","Kế toán viên","Nhà xuất bản"],"ans":"B","xp":"Diễn giả chính là \"a specialist in sports medicine\" và đã phát triển \"new surgical techniques\" (kỹ thuật phẫu thuật) → hội nghị dành cho giới y khoa, tức các bác sĩ → (B)."},{"n":49,"q":"What does the woman want to hand out to conference attendees?","qvi":"Người phụ nữ muốn phát gì cho người tham dự hội nghị?","opts":["Books","Tote bags","Tickets to a sports event","Copies of a speech"],"vi":["Sách","Túi vải","Vé xem sự kiện thể thao","Bản sao bài phát biểu"],"ans":"A","xp":"Người đàn ông nói \"His new book on the topic will be published later this month\", và người phụ nữ nói: \"I wonder if we have enough money to give copies to everyone who comes to the conference.\" → 'copies' ở đây là các bản của cuốn sách → (A)."}],"a":"E24-T10-47-49.mp3"},{"ns":[50,52],"script":[["W","Hi. I'm calling about your advertisement. I currently rent a space downtown where I build and repair furniture, but the owners just sold the building, and I have to be out by the end of the month.","Xin chào. Tôi gọi về mẩu quảng cáo của anh. Hiện tôi đang thuê một chỗ ở trung tâm thành phố để đóng và sửa đồ nội thất, nhưng chủ nhà vừa bán tòa nhà, và tôi phải dọn đi trước cuối tháng."],["M","Well, my space is quite large—enough to fit two cars or a work truck. It also has a dock in the back to load large containers, if that would be useful to you.","À, chỗ của tôi khá rộng, đủ để hai chiếc ô tô hoặc một xe tải làm việc. Phía sau còn có một bến bốc hàng để chất các thùng hàng lớn, nếu chị thấy hữu ích."],["W","Ideally, yes. I build large items, and a loading dock would make pickup and delivery easier.","Như vậy thì lý tưởng quá. Tôi làm đồ cỡ lớn, nên có bến bốc hàng thì việc lấy hàng và giao hàng sẽ dễ hơn."],["M","Would you like to see it this afternoon? Currently, there's no electricity, but I could call and have it turned on today.","Chị có muốn đến xem chiều nay không? Hiện giờ ở đó chưa có điện, nhưng tôi có thể gọi điện để cho người mở điện ngay hôm nay."]],"qs":[{"n":50,"q":"Who is the woman?","qvi":"Người phụ nữ là ai?","opts":["A truck driver","A plumber","A furniture maker","A mechanic"],"vi":["Tài xế xe tải","Thợ sửa ống nước","Thợ làm đồ nội thất","Thợ máy"],"ans":"C","xp":"Người phụ nữ nói: \"I currently rent a space downtown where I build and repair furniture.\" → cô ấy là thợ đóng đồ nội thất → (C)."},{"n":51,"q":"What does the man highlight about a work space?","qvi":"Người đàn ông nhấn mạnh điều gì về chỗ làm việc?","opts":["It has a loading dock.","It is close to the city center.","It has an assigned parking space.","It has fast Internet service."],"vi":["Nó có bến bốc dỡ hàng.","Nó gần trung tâm thành phố.","Nó có chỗ đỗ xe riêng.","Nó có Internet tốc độ cao."],"ans":"A","xp":"Người đàn ông nói: \"It also has a dock in the back to load large containers.\" a dock to load = a loading dock → (A)."},{"n":52,"q":"What does the man offer to do for the woman?","qvi":"Người đàn ông đề nghị làm gì cho người phụ nữ?","opts":["Print out a contract","Activate a utility","Replace some lights","Apply a discount"],"vi":["In hợp đồng","Kích hoạt một dịch vụ tiện ích (điện, nước...)","Thay một số bóng đèn","Áp dụng giảm giá"],"ans":"B","xp":"Người đàn ông nói: \"Currently, there's no electricity, but I could call and have it turned on today.\" electricity (điện) là một utility; have it turned on = activate → (B)."}],"a":"E24-T10-50-52.mp3"},{"ns":[53,55],"script":[["W","Waseem, I know this is last-minute, but is there any chance we can add another section to the workbook for tomorrow's seminar?","Waseem, tôi biết là sát giờ rồi, nhưng liệu chúng ta có thể thêm một phần nữa vào sách bài tập cho buổi hội thảo ngày mai không?"],["M","Oh. The workbook's already been printed.","Ồ. Sách bài tập đã được in rồi."],["W","I see. I just learned that the company added a new policy about working with clients that we need to include.","Tôi hiểu rồi. Tôi vừa biết là công ty đã thêm một chính sách mới về làm việc với khách hàng, và chúng ta cần đưa nội dung đó vào."],["M","Well, why don't we just add an insert to each copy of the workbook before we pass them out? Then everyone will be informed of the change.","Vậy sao mình không kẹp thêm một tờ rời vào mỗi cuốn sách bài tập trước khi phát ra? Như vậy mọi người đều sẽ được biết về thay đổi này."]],"qs":[{"n":53,"q":"What are the speakers preparing for?","qvi":"Những người nói đang chuẩn bị cho việc gì?","opts":["A seminar","A trade show","A client meeting","A book launch"],"vi":["Một buổi hội thảo","Một triển lãm thương mại","Một cuộc họp với khách hàng","Một buổi ra mắt sách"],"ans":"A","xp":"Người phụ nữ hỏi: \"is there any chance we can add another section to the workbook for tomorrow's seminar?\" → họ đang chuẩn bị cho hội thảo ngày mai → (A)."},{"n":54,"q":"What does the man imply when he says, \"The workbook's already been printed\"?","qvi":"Người đàn ông ngụ ý gì khi nói \"Sách bài tập đã được in rồi\"?","opts":["He is not sure enough copies were ordered.","He is expecting a delivery.","A change cannot be made.","A task was completed on schedule."],"vi":["Anh ấy không chắc đã đặt đủ số bản.","Anh ấy đang chờ một chuyến giao hàng.","Không thể thay đổi được nữa.","Một công việc đã hoàn thành đúng tiến độ."],"ans":"C","xp":"Người phụ nữ muốn thêm một phần vào sách bài tập; anh ấy đáp sách đã in xong → ý là không thể sửa/thêm vào cuốn sách nữa → (C)."},{"n":55,"q":"What does the man suggest?","qvi":"Người đàn ông đề xuất điều gì?","opts":["Contacting a presenter","Using a catering service","Adding a page to a book","Revising an invitation"],"vi":["Liên hệ với người thuyết trình","Dùng dịch vụ ăn uống","Thêm một trang vào cuốn sách","Sửa lại thư mời"],"ans":"C","xp":"Người đàn ông đề xuất: \"why don't we just add an insert to each copy of the workbook?\" an insert (tờ rời kẹp thêm) vào workbook = Adding a page to a book → (C)."}],"a":"E24-T10-53-55.mp3"},{"ns":[56,58],"script":[["M","Hi, Astrid. Thank you for meeting with me.","Chào Astrid. Cảm ơn chị đã gặp tôi."],["W","Of course. I have an open-door policy for all my employees here at the factory.","Không có gì. Tôi luôn sẵn sàng tiếp tất cả nhân viên của mình ở nhà máy này."],["M","So, I'd like to talk about changing my work schedule to the day shift.","Tôi muốn nói về việc chuyển lịch làm việc của tôi sang ca ngày."],["W","Well, we've had a lot of requests for that lately.","À, dạo gần đây chúng tôi nhận được rất nhiều yêu cầu như vậy."],["M","I see. But remember, I've been working the night shift for over ten years.","Tôi hiểu. Nhưng chị nhớ cho là tôi đã làm ca đêm hơn mười năm rồi."],["W","That's true. Let me look into it. I'll check the schedule and see what I can do. No promises though.","Đúng vậy. Để tôi xem xét. Tôi sẽ kiểm tra lịch làm việc và xem có thể làm gì. Nhưng tôi không hứa trước được."]],"qs":[{"n":56,"q":"Who most likely is the woman?","qvi":"Người phụ nữ nhiều khả năng là ai?","opts":["A career counselor","A sales representative","A factory supervisor","A computer programmer"],"vi":["Chuyên viên tư vấn nghề nghiệp","Nhân viên kinh doanh","Quản lý nhà máy","Lập trình viên máy tính"],"ans":"C","xp":"Người phụ nữ nói: \"I have an open-door policy for all my employees here at the factory.\" → cô ấy quản lý nhân viên ở nhà máy → (C)."},{"n":57,"q":"Why does the woman say, \"we've had a lot of requests for that lately\"?","qvi":"Tại sao người phụ nữ nói \"dạo gần đây chúng tôi nhận được rất nhiều yêu cầu như vậy\"?","opts":["To express doubt about a possibility","To request assistance with a task","To explain a delay","To compliment a colleague"],"vi":["Để bày tỏ sự nghi ngờ về một khả năng","Để nhờ giúp đỡ một việc","Để giải thích một sự chậm trễ","Để khen một đồng nghiệp"],"ans":"A","xp":"Người đàn ông muốn chuyển sang ca ngày; cô ấy nói có rất nhiều người cũng xin như vậy → ngụ ý khó đáp ứng, nghi ngờ khả năng được chuyển ca (cuối bài cô ấy còn nói \"No promises though\") → (A)."},{"n":58,"q":"What does the woman say she will do?","qvi":"Người phụ nữ nói cô ấy sẽ làm gì?","opts":["Attend a meeting","Check a schedule","Take inventory","Hire more employees"],"vi":["Tham dự một cuộc họp","Kiểm tra lịch làm việc","Kiểm kê hàng tồn kho","Tuyển thêm nhân viên"],"ans":"B","xp":"Người phụ nữ nói: \"I'll check the schedule and see what I can do.\" → (B)."}],"a":"E24-T10-56-58.mp3"},{"ns":[59,61],"script":[["W","I have bad news. Ife just sent me a text message. Her car won't start. The battery seems to be dead. She won't be here in time to lead her tour group.","Tôi có tin không vui. Ife vừa nhắn tin cho tôi. Xe của cô ấy không nổ máy được. Hình như hết bình rồi. Cô ấy sẽ không đến kịp để dẫn đoàn khách tham quan của mình."],["M1","Oh no. Well, I'm leading a tour of the seaport this morning.","Ôi không. À, sáng nay tôi lại phải dẫn một tour tham quan cảng biển."],["W","Rajeev, you're available. I know you're technically still in training, but I think you can handle it.","Rajeev, anh đang rảnh. Tôi biết về lý thuyết thì anh vẫn đang trong thời gian đào tạo, nhưng tôi nghĩ anh làm được."],["M2","Hmm. The historic warehouse district, right? I'm a little nervous about that.","Hừm. Khu nhà kho cổ phải không? Tôi hơi lo về chuyện đó."],["M1","You did a great job when you shadowed me on that tour last week. You even answered questions from the group.","Tuần trước anh làm rất tốt khi đi theo tôi học việc trong tour đó mà. Anh còn trả lời câu hỏi của đoàn khách nữa."]],"qs":[{"n":59,"q":"What news does the woman share?","qvi":"Người phụ nữ chia sẻ tin gì?","opts":["A colleague will be late to work.","An item cannot be found.","A form has a mistake in it.","An order has been canceled."],"vi":["Một đồng nghiệp sẽ đi làm muộn.","Không tìm thấy một món đồ.","Một biểu mẫu có lỗi.","Một đơn hàng đã bị hủy."],"ans":"A","xp":"Người phụ nữ nói: \"I have bad news... Her car won't start... She won't be here in time to lead her tour group.\" → đồng nghiệp Ife sẽ đến muộn → (A)."},{"n":60,"q":"Who are the men?","qvi":"Hai người đàn ông là ai?","opts":["Auto mechanics","Factory workers","Boat captains","Tour guides"],"vi":["Thợ sửa ô tô","Công nhân nhà máy","Thuyền trưởng","Hướng dẫn viên du lịch"],"ans":"D","xp":"Người đàn ông thứ nhất nói: \"I'm leading a tour of the seaport this morning.\"; người phụ nữ nhờ Rajeev dẫn đoàn thay Ife → cả hai đều là hướng dẫn viên → (D)."},{"n":61,"q":"Why is Rajeev nervous?","qvi":"Tại sao Rajeev lo lắng?","opts":["He made a mistake on his paperwork.","He recently asked for a salary increase.","He cannot reach someone by mobile phone.","He has not completed his training yet."],"vi":["Anh ấy làm sai giấy tờ.","Anh ấy vừa xin tăng lương.","Anh ấy không liên lạc được với ai đó qua điện thoại di động.","Anh ấy chưa hoàn thành khóa đào tạo."],"ans":"D","xp":"Người phụ nữ nói: \"I know you're technically still in training\", rồi Rajeev nói: \"I'm a little nervous about that.\" → anh ấy lo vì vẫn đang trong thời gian đào tạo, chưa xong → (D)."}],"a":"E24-T10-59-61.mp3"},{"ns":[62,64],"script":[["M","We need to check with the project manager about today's construction schedule.","Chúng ta cần hỏi lại quản lý dự án về lịch thi công hôm nay."],["W","I already did—I just came from his office. He said we're going to close off multiple lanes to create a safe work zone.","Tôi hỏi rồi. Tôi vừa từ văn phòng anh ấy ra. Anh ấy nói chúng ta sẽ đóng nhiều làn đường để tạo khu vực thi công an toàn."],["M","Got it. Which ones are we closing?","Hiểu rồi. Mình sẽ đóng những làn nào?"],["W","All of them except for the passing lane.","Tất cả, trừ làn vượt."],["M","Wow, this closure is really going to affect the morning commute.","Chà, việc đóng đường này chắc chắn sẽ ảnh hưởng nhiều đến giờ đi làm buổi sáng."],["W","You're right. I'm going to ask for extra personnel to help manage the traffic volume.","Anh nói đúng. Tôi sẽ đề nghị bổ sung thêm nhân sự để giúp điều tiết lưu lượng giao thông."]],"qs":[{"n":62,"q":"Where has the woman just come from?","qvi":"Người phụ nữ vừa từ đâu đến?","opts":["A manager's office","A police station","A rental facility","An equipment storage area"],"vi":["Văn phòng của quản lý","Đồn cảnh sát","Cơ sở cho thuê","Khu vực kho thiết bị"],"ans":"A","xp":"Người đàn ông nhắc \"the project manager\", người phụ nữ đáp: \"I just came from his office.\" → cô ấy vừa từ văn phòng quản lý dự án đến → (A)."},{"n":63,"q":"Look at the graphic. Which lane will stay open today?","qvi":"Nhìn vào hình. Làn đường nào sẽ vẫn mở hôm nay?","opts":["Lane 1","Lane 2","Lane 3","Lane 4"],"vi":["Làn 1","Làn 2","Làn 3","Làn 4"],"ans":"B","xp":"Khi được hỏi đóng làn nào, người phụ nữ nói: \"All of them except for the passing lane.\" → chỉ làn vượt (Passing Lane) còn mở. Theo hình, Passing Lane là Lane 2 → (B)."},{"n":64,"q":"What does the woman say she will ask for?","qvi":"Người phụ nữ nói cô ấy sẽ yêu cầu điều gì?","opts":["A pay raise","Extra supplies","More personnel","A safety barricade"],"vi":["Tăng lương","Thêm vật tư","Thêm nhân sự","Một rào chắn an toàn"],"ans":"C","xp":"Người phụ nữ nói: \"I'm going to ask for extra personnel to help manage the traffic volume.\" extra personnel = More personnel → (C)."}],"a":"E24-T10-62-64.mp3","img":"g62.png"},{"ns":[65,67],"script":[["M","Let's start planning the annual employee retreat.","Chúng ta bắt đầu lên kế hoạch cho chuyến dã ngoại thường niên của nhân viên nhé."],["W","Yes. I think we should hold it outside. We're at our desks all day, so it would be really great to spend some time in the sun.","Vâng. Tôi nghĩ mình nên tổ chức ở ngoài trời. Cả ngày chúng ta ngồi bàn làm việc rồi, nên được ra nắng một chút thì tuyệt lắm."],["M","I agree. There's a place, Oliver's Orchard, that lets you pick your own fruit. We could have the event there.","Tôi đồng ý. Có một nơi tên là Oliver's Orchard, ở đó khách được tự hái trái cây. Mình có thể tổ chức sự kiện ở đó."],["W","Great idea. The retreat's in June. Is it open then?","Ý hay đấy. Chuyến dã ngoại vào tháng Sáu. Lúc đó họ có mở cửa không?"],["M","According to the Web site, they are.","Theo trang web thì có."],["W","Perfect. I'll call the orchard to make a reservation for our group.","Tuyệt. Tôi sẽ gọi cho vườn cây để đặt chỗ cho nhóm mình."]],"qs":[{"n":65,"q":"What does the woman suggest about an event location?","qvi":"Người phụ nữ gợi ý gì về địa điểm tổ chức sự kiện?","opts":["It should be outdoors.","It should be inexpensive.","It should be local.","It should offer lunch."],"vi":["Nên ở ngoài trời.","Nên rẻ.","Nên ở gần địa phương.","Nên có phục vụ bữa trưa."],"ans":"A","xp":"Người phụ nữ nói: \"I think we should hold it outside.\" outside = outdoors → (A)."},{"n":66,"q":"Look at the graphic. Which fruit will be picked during the event?","qvi":"Nhìn vào bảng. Loại trái cây nào sẽ được hái trong sự kiện?","opts":["Strawberries","Black cherries","Blueberries","Green apples"],"vi":["Dâu tây","Anh đào đen","Việt quất","Táo xanh"],"ans":"B","xp":"Người phụ nữ nói: \"The retreat's in June.\" Theo bảng, tháng Sáu (June) là mùa hái Black Cherries (June, July) → (B)."},{"n":67,"q":"What does the woman say she will do?","qvi":"Người phụ nữ nói cô ấy sẽ làm gì?","opts":["Contact a business","Draft an invitation","Recruit some volunteers","Prepare a budget"],"vi":["Liên hệ với một doanh nghiệp","Soạn thư mời","Tuyển tình nguyện viên","Chuẩn bị ngân sách"],"ans":"A","xp":"Người phụ nữ nói: \"I'll call the orchard to make a reservation for our group.\" call the orchard (gọi cho vườn cây) = Contact a business → (A)."}],"a":"E24-T10-65-67.mp3","img":"g65.png"},{"ns":[68,70],"script":[["M","Hi. I'm looking for an apartment, and I saw your advertisement. Do you have any two-bedroom apartments available in May?","Xin chào. Tôi đang tìm căn hộ và thấy quảng cáo của chị. Chị có căn hộ hai phòng ngủ nào trống vào tháng Năm không?"],["W","Yes. In fact, we've just finished construction on a new complex.","Có. Thật ra chúng tôi vừa xây xong một khu căn hộ mới."],["M","Does the complex have a lot of outdoor space? I'd like to have an area to entertain guests outside.","Khu đó có nhiều không gian ngoài trời không? Tôi muốn có một chỗ để tiếp khách ở ngoài trời."],["W","Yes, there's plenty of green space. The building in the back corner, farthest from the office, has the most space and a lot of shade.","Có, ở đó có nhiều mảng xanh. Tòa nhà ở góc phía sau, xa văn phòng nhất, có nhiều không gian nhất và nhiều bóng mát."],["M","I'd be interested in that.","Tôi thấy căn đó hay đấy."],["W","And for an extra 80 dollars per month, you can get a reserved parking space right in front of your unit.","Và nếu trả thêm 80 đô la mỗi tháng, anh sẽ có một chỗ đậu xe riêng ngay trước căn hộ của mình."]],"qs":[{"n":68,"q":"Who most likely is the woman?","qvi":"Người phụ nữ nhiều khả năng là ai?","opts":["A landscape worker","A taxi driver","An apartment manager","An interior decorator"],"vi":["Công nhân làm cảnh quan","Tài xế taxi","Quản lý khu căn hộ","Nhà trang trí nội thất"],"ans":"C","xp":"Người đàn ông hỏi thuê căn hộ (\"Do you have any two-bedroom apartments available in May?\"), cô ấy đáp: \"Yes. In fact, we've just finished construction on a new complex.\" → cô ấy là người quản lý/cho thuê căn hộ → (C)."},{"n":69,"q":"Look at the graphic. Which location is the woman referring to?","qvi":"Nhìn vào hình. Người phụ nữ đang nói đến vị trí nào?","opts":["101","102","103","104"],"vi":["101","102","103","104"],"ans":"D","xp":"Người phụ nữ nói: \"The building in the back corner, farthest from the office, has the most space and a lot of shade.\" Trên sơ đồ, tòa ở góc xa văn phòng (Office) nhất, có nhiều cây xung quanh là 104 → (D)."},{"n":70,"q":"What might the man pay extra for?","qvi":"Người đàn ông có thể trả thêm tiền cho cái gì?","opts":["A pool membership","A reserved parking space","Monthly maintenance","Laundry facilities"],"vi":["Thẻ thành viên hồ bơi","Một chỗ đậu xe riêng","Phí bảo trì hằng tháng","Khu giặt ủi"],"ans":"B","xp":"Người phụ nữ nói: \"for an extra 80 dollars per month, you can get a reserved parking space right in front of your unit.\" → (B)."}],"a":"E24-T10-68-70.mp3","img":"g68.png"}],"p4":[{"ns":[71,73],"script":[["","Some of you have been accidentally skipping some of your closing duties, so I've called this meeting to clarify what is expected. After you've sanitized all the food preparation areas in the kitchen, make sure the pantry and walk-in refrigerator doors are shut and locked. There are a few other tasks to complete before you leave. I know the current checklist isn't up-to-date, so I'll make the necessary revisions to it.","Một số bạn đã vô tình bỏ sót vài công việc lúc đóng cửa, nên tôi triệu tập cuộc họp này để nói rõ những việc cần làm. Sau khi đã vệ sinh khử trùng tất cả các khu vực sơ chế thức ăn trong bếp, hãy nhớ đóng và khóa cửa kho thực phẩm và cửa phòng lạnh. Còn một vài việc khác cần hoàn thành trước khi các bạn ra về. Tôi biết danh sách kiểm tra hiện tại chưa được cập nhật, nên tôi sẽ chỉnh sửa lại cho phù hợp."]],"qs":[{"n":71,"q":"What is the purpose of a meeting?","qvi":"Mục đích của cuộc họp là gì?","opts":["To prepare staff for a special event","To review some closing procedures","To introduce some staff members","To resolve an issue with inventory"],"vi":["Để chuẩn bị cho nhân viên trước một sự kiện đặc biệt","Để xem lại một số quy trình đóng cửa","Để giới thiệu một số nhân viên","Để giải quyết vấn đề về hàng tồn kho"],"ans":"B","xp":"Người nói: \"Some of you have been accidentally skipping some of your closing duties, so I've called this meeting to clarify what is expected.\" → họp để nói rõ lại các công việc khi đóng cửa (closing duties = closing procedures) → (B)."},{"n":72,"q":"What type of business do the listeners most likely work for?","qvi":"Người nghe nhiều khả năng làm việc cho loại hình kinh doanh nào?","opts":["A restaurant","A library","An appliance store","A manufacturing facility"],"vi":["Nhà hàng","Thư viện","Cửa hàng đồ gia dụng","Cơ sở sản xuất"],"ans":"A","xp":"Người nói nhắc đến \"food preparation areas in the kitchen\", \"pantry\" và \"walk-in refrigerator\" (khu sơ chế thức ăn, kho thực phẩm, phòng lạnh) → người nghe làm ở nhà hàng → (A)."},{"n":73,"q":"What does the speaker say he will do?","qvi":"Người nói cho biết anh ấy sẽ làm gì?","opts":["Sign a contract","Mail an invoice","Edit a document","Change a schedule"],"vi":["Ký hợp đồng","Gửi hóa đơn qua bưu điện","Chỉnh sửa một tài liệu","Thay đổi lịch trình"],"ans":"C","xp":"Người nói: \"I know the current checklist isn't up-to-date, so I'll make the necessary revisions to it.\" make revisions (chỉnh sửa) = Edit; the checklist = a document → (C)."}],"a":"E24-T10-71-73.mp3"},{"ns":[74,76],"script":[["","Hi, Melissa. It's Hiroki from Ecology Now Magazine. I just read your article about protecting old-growth forests in Europe and how important these conservation efforts are to the local communities. First of all, I loved your descriptions of the mushroom-hunting social groups. Readers will feel like they're there! However, your article mainly presents the views of people who use the forests for recreation. We need to hear from the lawmakers responsible for the new regulations impacting land use. And be sure to include some photos. Aside from that, great job. Call me back if you want more guidance.","Chào Melissa. Tôi là Hiroki từ tạp chí Ecology Now. Tôi vừa đọc bài viết của chị về việc bảo vệ các khu rừng nguyên sinh ở châu Âu và tầm quan trọng của những nỗ lực bảo tồn này đối với cộng đồng địa phương. Trước hết, tôi rất thích những đoạn chị miêu tả các nhóm hội đi hái nấm. Độc giả sẽ có cảm giác như đang ở đó vậy! Tuy nhiên, bài viết chủ yếu trình bày quan điểm của những người dùng rừng để vui chơi giải trí. Chúng ta cần nghe ý kiến của các nhà làm luật chịu trách nhiệm về những quy định mới ảnh hưởng đến việc sử dụng đất. Và nhớ đưa thêm vài tấm ảnh nhé. Ngoài những điều đó ra thì bài viết rất tốt. Hãy gọi lại cho tôi nếu chị cần thêm hướng dẫn."]],"qs":[{"n":74,"q":"What topic did the listener write an article about?","qvi":"Người nghe đã viết bài về chủ đề gì?","opts":["Forest conservation","Travel recommendations","Bird-watching","Social media usage"],"vi":["Bảo tồn rừng","Gợi ý du lịch","Ngắm chim","Việc sử dụng mạng xã hội"],"ans":"A","xp":"Người nói: \"I just read your article about protecting old-growth forests in Europe and how important these conservation efforts are...\" protecting forests = Forest conservation → (A)."},{"n":75,"q":"What does the speaker like about the article?","qvi":"Người nói thích điều gì ở bài viết?","opts":["The descriptions","The photographs","The organization","The use of statistics"],"vi":["Các đoạn miêu tả","Các bức ảnh","Cách sắp xếp bố cục","Việc dùng số liệu thống kê"],"ans":"A","xp":"Người nói: \"I loved your descriptions of the mushroom-hunting social groups.\" → (A).\n(B) sai: bài viết chưa có ảnh, người nói còn dặn \"be sure to include some photos\"."},{"n":76,"q":"Who does the speaker want the listener to interview?","qvi":"Người nói muốn người nghe phỏng vấn ai?","opts":["Restaurant chefs","Park rangers","Biologists","Government officials"],"vi":["Đầu bếp nhà hàng","Kiểm lâm viên","Nhà sinh vật học","Quan chức chính phủ"],"ans":"D","xp":"Người nói: \"We need to hear from the lawmakers responsible for the new regulations impacting land use.\" lawmakers (nhà làm luật) = Government officials → (D)."}],"a":"E24-T10-74-76.mp3"},{"ns":[77,79],"script":[["","Welcome, everyone, to this workshop on artificial intelligence technologies. Though I know everyone's been enjoying the coffee and conversation, we have a lot of speakers on the schedule. To start things off, we're delighted to invite Dr. Haruka Adachi to the stage. She'll demonstrate some ways computer systems can simulate human intelligence. Even if you're not a computer programmer, I'm sure you'll find this demonstration easy to follow. Please feel free to raise your hand to ask questions at any time. We want these sessions to be interactive.","Chào mừng mọi người đến với hội thảo về công nghệ trí tuệ nhân tạo. Tôi biết mọi người đang thưởng thức cà phê và trò chuyện vui vẻ, nhưng chúng ta có rất nhiều diễn giả trong lịch trình. Để mở đầu, chúng tôi rất vui được mời Tiến sĩ Haruka Adachi lên sân khấu. Bà sẽ trình diễn một số cách mà hệ thống máy tính có thể mô phỏng trí thông minh của con người. Kể cả khi bạn không phải là lập trình viên, tôi tin bạn vẫn sẽ thấy phần trình diễn này dễ theo dõi. Xin cứ thoải mái giơ tay đặt câu hỏi bất cứ lúc nào. Chúng tôi muốn các phiên này có sự tương tác."]],"qs":[{"n":77,"q":"What does the speaker imply when she says, \"we have a lot of speakers on the schedule\"?","qvi":"Người nói ngụ ý gì khi nói \"chúng ta có rất nhiều diễn giả trong lịch trình\"?","opts":["The listeners should check the schedule.","An advertisement was popular.","An event will begin right away.","More refreshments will be needed."],"vi":["Người nghe nên xem lại lịch trình.","Một quảng cáo đã được ưa chuộng.","Sự kiện sẽ bắt đầu ngay.","Sẽ cần thêm đồ ăn nhẹ."],"ans":"C","xp":"Trước đó người nói nói: \"Though I know everyone's been enjoying the coffee and conversation\", ngay sau đó là \"To start things off, we're delighted to invite Dr. Haruka Adachi to the stage.\" → ý là có nhiều diễn giả nên phải bắt đầu ngay, dừng trò chuyện → (C)."},{"n":78,"q":"What industry does Dr. Adachi most likely work in?","qvi":"Tiến sĩ Adachi nhiều khả năng làm trong ngành nào?","opts":["Filmmaking","Interior design","Construction","Computer science"],"vi":["Làm phim","Thiết kế nội thất","Xây dựng","Khoa học máy tính"],"ans":"D","xp":"Người nói: \"She'll demonstrate some ways computer systems can simulate human intelligence.\" (hội thảo về trí tuệ nhân tạo) → bà làm trong ngành khoa học máy tính → (D)."},{"n":79,"q":"What does the speaker encourage the listeners to do?","qvi":"Người nói khuyến khích người nghe làm gì?","opts":["Complete a survey","Ask questions","Introduce themselves","Work in small groups"],"vi":["Hoàn thành một bản khảo sát","Đặt câu hỏi","Tự giới thiệu bản thân","Làm việc theo nhóm nhỏ"],"ans":"B","xp":"Người nói: \"Please feel free to raise your hand to ask questions at any time.\" → (B)."}],"a":"E24-T10-77-79.mp3"},{"ns":[80,82],"script":[["","Attention, everyone: the home bathroom showcase will begin in an hour in Hall D. The showcase will feature the latest designs for showers and bathtubs, as well as a variety of materials for home customization. Exhibitors, please be at your designated booth at least 30 minutes before the showcase opens to the public. If you need assistance, any staff member can direct you to your booth. Attendees, don't forget to bring your tickets to the showcase. We will be running a raffle with a chance to win a new bathtub. You'll need your ticket to participate.","Xin mọi người chú ý: buổi trưng bày thiết bị phòng tắm gia đình sẽ bắt đầu sau một giờ nữa tại Sảnh D. Buổi trưng bày sẽ giới thiệu các mẫu thiết kế vòi sen và bồn tắm mới nhất, cùng với nhiều loại vật liệu để tùy biến nhà ở. Các đơn vị triển lãm vui lòng có mặt tại gian hàng được chỉ định ít nhất 30 phút trước khi buổi trưng bày mở cửa cho công chúng. Nếu cần hỗ trợ, bất kỳ nhân viên nào cũng có thể chỉ đường cho quý vị đến gian hàng. Quý khách tham dự đừng quên mang theo vé vào buổi trưng bày. Chúng tôi sẽ tổ chức bốc thăm trúng thưởng với cơ hội nhận một chiếc bồn tắm mới. Quý vị cần có vé để tham gia."]],"qs":[{"n":80,"q":"What type of event is most likely taking place?","qvi":"Sự kiện nào nhiều khả năng đang diễn ra?","opts":["A trade show","A museum exhibit","A food festival","A gardening workshop"],"vi":["Một triển lãm thương mại","Một cuộc triển lãm ở bảo tàng","Một lễ hội ẩm thực","Một buổi hội thảo làm vườn"],"ans":"A","xp":"Người nói nhắc đến \"the home bathroom showcase\" giới thiệu \"the latest designs for showers and bathtubs\", có \"Exhibitors\" và \"booth\" (đơn vị triển lãm, gian hàng) → đây là triển lãm thương mại → (A)."},{"n":81,"q":"What are exhibitors asked to do?","qvi":"Các đơn vị triển lãm được yêu cầu làm gì?","opts":["Wear identification badges","Distribute samples","Obtain parking passes","Arrive at a location early"],"vi":["Đeo thẻ nhận dạng","Phát hàng mẫu","Lấy thẻ đỗ xe","Đến một địa điểm sớm"],"ans":"D","xp":"Người nói: \"Exhibitors, please be at your designated booth at least 30 minutes before the showcase opens to the public.\" → có mặt ở gian hàng sớm 30 phút = Arrive at a location early → (D)."},{"n":82,"q":"What does the speaker say attendees can do with their tickets?","qvi":"Người nói cho biết người tham dự có thể dùng vé để làm gì?","opts":["Receive a discount","Enter a contest","Access a special area","Purchase refreshments"],"vi":["Được giảm giá","Tham gia một cuộc thi/bốc thăm","Vào một khu vực đặc biệt","Mua đồ ăn nhẹ"],"ans":"B","xp":"Người nói: \"We will be running a raffle with a chance to win a new bathtub. You'll need your ticket to participate.\" raffle (bốc thăm trúng thưởng) ≈ a contest; participate = enter → (B)."}],"a":"E24-T10-80-82.mp3"},{"ns":[83,85],"script":[["","Hi, Andrew. I'm calling about the Dearborn Hotel account—the clients that we're producing the television commercial for. I just heard from them, and they said they've been very satisfied with how you're addressing their needs for the project. It's always great to get such positive feedback from our clients, and this is your first account. They also mentioned that they'd like to make some adjustments to the project timeline. Could you e-mail me the most recent copy of it? Thanks!","Chào Andrew. Tôi gọi về khách hàng khách sạn Dearborn, khách hàng mà chúng ta đang sản xuất quảng cáo truyền hình cho họ. Tôi vừa nói chuyện với họ, và họ nói rất hài lòng với cách anh đáp ứng các yêu cầu của họ cho dự án. Nhận được phản hồi tích cực như vậy từ khách hàng lúc nào cũng tuyệt, mà đây lại là khách hàng đầu tiên của anh. Họ cũng nói muốn điều chỉnh một chút tiến độ dự án. Anh gửi e-mail cho tôi bản tiến độ mới nhất được không? Cảm ơn anh!"]],"qs":[{"n":83,"q":"What industry does the speaker most likely work in?","qvi":"Người nói nhiều khả năng làm trong ngành nào?","opts":["Hospitality","Finance","Advertising","Technology"],"vi":["Khách sạn – nhà hàng","Tài chính","Quảng cáo","Công nghệ"],"ans":"C","xp":"Người nói: \"the clients that we're producing the television commercial for\" → công ty sản xuất quảng cáo truyền hình cho khách → ngành quảng cáo → (C).\n(A) sai: khách sạn Dearborn chỉ là khách hàng."},{"n":84,"q":"What does the speaker mean when she says, \"this is your first account\"?","qvi":"Người nói có ý gì khi nói \"đây là khách hàng đầu tiên của anh\"?","opts":["She is impressed by some work.","She is available to answer questions.","A mistake is understandable.","A process will take a long time."],"vi":["Cô ấy ấn tượng với công việc của anh ấy.","Cô ấy sẵn sàng trả lời câu hỏi.","Một lỗi sai là có thể thông cảm được.","Một quy trình sẽ mất nhiều thời gian."],"ans":"A","xp":"Ngay trước đó: \"It's always great to get such positive feedback from our clients\" → mới làm khách hàng đầu tiên mà đã được khen → cô ấy rất ấn tượng với kết quả của Andrew → (A)."},{"n":85,"q":"What does the speaker ask the listener to send?","qvi":"Người nói yêu cầu người nghe gửi gì?","opts":["A timeline","An address","Some sales figures","Some meeting notes"],"vi":["Bảng tiến độ","Một địa chỉ","Số liệu bán hàng","Biên bản cuộc họp"],"ans":"A","xp":"Người nói: \"they'd like to make some adjustments to the project timeline. Could you e-mail me the most recent copy of it?\" 'it' = the project timeline → (A)."}],"a":"E24-T10-83-85.mp3"},{"ns":[86,88],"script":[["","Hi, everyone. As farm employees, we have all come across various issues with our equipment. Today I'm going to talk about what to do when you find liquid leaking from any of our farm equipment. Our mowers and tractors mainly use fluids like water, or oil to control steering. When you find fluid leaking from a broken tube or valve, don't try to fix it yourself. Please let me know, and I'll contact the manufacturer for a replacement part. Otherwise, the warranty will be voided.","Chào mọi người. Là nhân viên nông trại, ai trong chúng ta cũng từng gặp nhiều vấn đề với máy móc thiết bị. Hôm nay tôi sẽ nói về việc cần làm khi phát hiện chất lỏng rò rỉ từ bất kỳ thiết bị nào của nông trại. Máy cắt cỏ và máy kéo của chúng ta chủ yếu dùng các chất lỏng như nước hoặc dầu để điều khiển bộ lái. Khi thấy chất lỏng rò rỉ từ một ống hoặc van bị hỏng, đừng tự sửa. Hãy báo cho tôi, tôi sẽ liên hệ nhà sản xuất để lấy linh kiện thay thế. Nếu không, chế độ bảo hành sẽ bị mất hiệu lực."]],"qs":[{"n":86,"q":"Where do the listeners most likely work?","qvi":"Người nghe nhiều khả năng làm việc ở đâu?","opts":["At a public park","At a landscaping company","At a farm","At a supermarket"],"vi":["Ở công viên công cộng","Ở công ty làm cảnh quan","Ở nông trại","Ở siêu thị"],"ans":"C","xp":"Người nói: \"As farm employees, we have all come across various issues with our equipment.\" → người nghe là nhân viên nông trại → (C)."},{"n":87,"q":"What is the speaker mainly discussing?","qvi":"Người nói chủ yếu bàn về điều gì?","opts":["Purchasing some tools","Training cleaning staff","Repairing some equipment","Arranging transportation"],"vi":["Mua một số dụng cụ","Đào tạo nhân viên vệ sinh","Sửa chữa một số thiết bị","Sắp xếp phương tiện đi lại"],"ans":"C","xp":"Người nói: \"Today I'm going to talk about what to do when you find liquid leaking from any of our farm equipment.\" → nội dung là cách xử lý khi thiết bị bị rò rỉ, hỏng hóc (sửa chữa thiết bị) → (C)."},{"n":88,"q":"What solution does the speaker suggest?","qvi":"Người nói đề xuất giải pháp gì?","opts":["Contacting a manufacturer","Decreasing a budget","Renting some tents","Extending hours of operation"],"vi":["Liên hệ nhà sản xuất","Cắt giảm ngân sách","Thuê lều","Kéo dài giờ hoạt động"],"ans":"A","xp":"Người nói: \"Please let me know, and I'll contact the manufacturer for a replacement part.\" → (A)."}],"a":"E24-T10-86-88.mp3"},{"ns":[89,91],"script":[["","Good afternoon, and thanks for visiting Eastgate Art Museum. This month, we're delighted to offer a special exhibit of Johann Weber's paintings. In just a few minutes, our museum director will be giving a talk in the museum theater about the artist's life and work. While you're here, please consider becoming a member of the museum. To sign up, stop by the information desk. Members will receive advance notice about educational events, like the one today.","Xin chào và cảm ơn quý vị đã đến thăm Bảo tàng Nghệ thuật Eastgate. Tháng này, chúng tôi rất vui được giới thiệu cuộc triển lãm đặc biệt các bức tranh của Johann Weber. Chỉ ít phút nữa, giám đốc bảo tàng sẽ có buổi nói chuyện tại nhà hát của bảo tàng về cuộc đời và sự nghiệp của họa sĩ. Nhân dịp quý vị ở đây, xin hãy cân nhắc trở thành hội viên của bảo tàng. Để đăng ký, xin ghé quầy thông tin. Hội viên sẽ được thông báo trước về các sự kiện giáo dục, như sự kiện hôm nay."]],"qs":[{"n":89,"q":"Who is Johann Weber?","qvi":"Johann Weber là ai?","opts":["A musician","A librarian","A painter","A journalist"],"vi":["Nhạc sĩ","Thủ thư","Họa sĩ","Nhà báo"],"ans":"C","xp":"Người nói: \"a special exhibit of Johann Weber's paintings\" (triển lãm tranh của Johann Weber) → ông ấy là họa sĩ → (C)."},{"n":90,"q":"What will take place momentarily?","qvi":"Điều gì sẽ diễn ra trong chốc lát nữa?","opts":["A director will give a talk.","A facility tour will begin.","A group photo will be taken.","A meal will be served."],"vi":["Một giám đốc sẽ có bài nói chuyện.","Một chuyến tham quan cơ sở sẽ bắt đầu.","Một bức ảnh tập thể sẽ được chụp.","Một bữa ăn sẽ được phục vụ."],"ans":"A","xp":"Người nói: \"In just a few minutes, our museum director will be giving a talk in the museum theater.\" in just a few minutes = momentarily → (A)."},{"n":91,"q":"According to the speaker, what can the listeners do at the information desk?","qvi":"Theo người nói, người nghe có thể làm gì ở quầy thông tin?","opts":["Pick up a newsletter","Sign up for a membership","Enter a contest","Register for a workshop"],"vi":["Lấy bản tin","Đăng ký làm hội viên","Tham gia một cuộc thi","Đăng ký một buổi hội thảo"],"ans":"B","xp":"Người nói: \"please consider becoming a member of the museum. To sign up, stop by the information desk.\" → (B)."}],"a":"E24-T10-89-91.mp3"},{"ns":[92,94],"script":[["","This chart shows the clinic's average monthly expenses. Our wages for dental hygienists, assistants, and other staff members are about 25 percent of the budget, which is right on target. Even though our rent has gradually increased over the years, it still doesn't take up a large part of our budget. However, look at the costs of our supplies. You know, we haven't looked at other suppliers recently. Any savings we might find could be used for marketing to help bring in more business. So, where could we focus our marketing efforts?","Biểu đồ này cho thấy chi phí trung bình hằng tháng của phòng khám. Tiền lương cho các chuyên viên vệ sinh răng miệng, phụ tá và các nhân viên khác chiếm khoảng 25% ngân sách, đúng như dự kiến. Mặc dù tiền thuê mặt bằng tăng dần qua các năm, nó vẫn không chiếm phần lớn ngân sách. Tuy nhiên, hãy xem chi phí vật tư của chúng ta. Các bạn biết đấy, gần đây chúng ta chưa xem xét các nhà cung cấp khác. Khoản tiết kiệm nào tìm được cũng có thể dùng cho marketing để thu hút thêm khách hàng. Vậy chúng ta nên tập trung nỗ lực marketing vào đâu?"]],"qs":[{"n":92,"q":"Where does the speaker most likely work?","qvi":"Người nói nhiều khả năng làm việc ở đâu?","opts":["At a dental office","At a commercial bank","At an equipment rental company","At an employment agency"],"vi":["Ở phòng khám nha khoa","Ở ngân hàng thương mại","Ở công ty cho thuê thiết bị","Ở trung tâm giới thiệu việc làm"],"ans":"A","xp":"Người nói nhắc đến \"the clinic's average monthly expenses\" và \"wages for dental hygienists\" (chuyên viên vệ sinh răng miệng) → phòng khám nha khoa → (A)."},{"n":93,"q":"What does the speaker imply when she says, \"we haven't looked at other suppliers recently\"?","qvi":"Người nói ngụ ý gì khi nói \"gần đây chúng ta chưa xem xét các nhà cung cấp khác\"?","opts":["She is unfamiliar with a task.","She is asking for volunteers.","More affordable options may be available.","Some information needs to be corrected."],"vi":["Cô ấy không quen với một công việc.","Cô ấy đang tìm người tình nguyện.","Có thể có những lựa chọn rẻ hơn.","Một số thông tin cần được sửa lại."],"ans":"C","xp":"Ngay trước đó: \"However, look at the costs of our supplies.\" và ngay sau: \"Any savings we might find...\" → ý là nếu tìm nhà cung cấp khác thì có thể có giá rẻ hơn, tiết kiệm được tiền → (C)."},{"n":94,"q":"What will most likely be discussed next?","qvi":"Điều gì nhiều khả năng sẽ được thảo luận tiếp theo?","opts":["A relocation plan","A staff-recruitment drive","Some changes to a work policy","Some marketing ideas"],"vi":["Kế hoạch di dời","Đợt tuyển dụng nhân viên","Một số thay đổi trong chính sách làm việc","Một số ý tưởng marketing"],"ans":"D","xp":"Câu cuối: \"So, where could we focus our marketing efforts?\" → tiếp theo họ sẽ bàn ý tưởng marketing → (D)."}],"a":"E24-T10-92-94.mp3"},{"ns":[95,97],"script":[["","Hi. I'm calling to purchase some backpacks for my company. We recently started selling textbooks, and our employees will be traveling regionally to sell them. I'd like to provide the backpacks to our customers as promotional gifts, but I'd like them to be sturdy—so I'd like something with padded straps to make them comfortable. And there should be easy access to a water bottle as well. If you have what we need, we plan to order 50 of these. So, can you tell me if there is a bulk discount? Please call me back at 555-0198.","Xin chào. Tôi gọi để mua một số ba lô cho công ty. Gần đây chúng tôi bắt đầu bán sách giáo khoa, và nhân viên của chúng tôi sẽ đi khắp khu vực để bán. Tôi muốn tặng ba lô cho khách hàng làm quà khuyến mãi, nhưng tôi muốn ba lô phải chắc chắn, nên tôi muốn loại có quai đệm để đeo thoải mái. Và cũng phải lấy chai nước ra vào dễ dàng nữa. Nếu bên bạn có loại chúng tôi cần, chúng tôi dự định đặt 50 chiếc. Vậy bạn cho tôi biết có giảm giá khi mua số lượng lớn không? Vui lòng gọi lại cho tôi theo số 555-0198."]],"qs":[{"n":95,"q":"Why does the speaker want to purchase backpacks?","qvi":"Tại sao người nói muốn mua ba lô?","opts":["To make a donation to a local school","To give to clients as gifts","To help employees carry materials at conferences","To advertise a company logo"],"vi":["Để quyên góp cho một trường học địa phương","Để tặng khách hàng làm quà","Để giúp nhân viên mang tài liệu khi đi hội nghị","Để quảng cáo logo công ty"],"ans":"B","xp":"Người nói: \"I'd like to provide the backpacks to our customers as promotional gifts.\" customers = clients → (B)."},{"n":96,"q":"Look at the graphic. Which backpack fits the speaker's needs?","qvi":"Nhìn vào bảng. Chiếc ba lô nào phù hợp với nhu cầu của người nói?","opts":["The Outsider","Modern Traveler","Road Bound","Elite Pro"],"vi":["The Outsider","Modern Traveler","Road Bound","Elite Pro"],"ans":"A","xp":"Người nói cần \"something with padded straps\" và \"easy access to a water bottle\". Theo bảng, chỉ The Outsider có cả Water Bottle Pocket và Padded Straps → (A)."},{"n":97,"q":"What does the speaker ask about?","qvi":"Người nói hỏi về điều gì?","opts":["Photographs","Expedited shipping","A return policy","A discount"],"vi":["Hình ảnh","Giao hàng nhanh","Chính sách đổi trả","Giảm giá"],"ans":"D","xp":"Người nói: \"can you tell me if there is a bulk discount?\" (giảm giá khi mua số lượng lớn) → (D)."}],"a":"E24-T10-95-97.mp3","img":"g95.png"},{"ns":[98,100],"script":[["","Hi, everyone. As most of you know, I opened this grocery store five years ago. I'm happy that we are the main supplier of fruits and vegetables in the neighborhood, and the demand for our products has increased. To meet this need, we've received a loan that will allow us to expand our operations! These additional funds will allow us to make an important change: effective immediately, we'll be open seven days a week! That means we'll have extra shifts available—if you'd like to work one of these extra shifts, please let me know.","Chào mọi người. Như hầu hết các bạn đã biết, tôi mở cửa hàng tạp hóa này cách đây năm năm. Tôi rất vui vì chúng ta là nơi cung cấp rau củ quả chính trong khu phố, và nhu cầu đối với sản phẩm của chúng ta ngày càng tăng. Để đáp ứng nhu cầu đó, chúng ta đã nhận được một khoản vay cho phép mở rộng hoạt động kinh doanh! Khoản vốn bổ sung này sẽ giúp chúng ta thực hiện một thay đổi quan trọng: kể từ bây giờ, cửa hàng sẽ mở cửa bảy ngày một tuần! Điều đó có nghĩa là sẽ có thêm ca làm việc. Nếu bạn muốn làm thêm một trong những ca này, hãy báo cho tôi."]],"qs":[{"n":98,"q":"What type of business does the speaker run?","qvi":"Người nói điều hành loại hình kinh doanh nào?","opts":["A hair salon","A bookstore","A grocery store","An appliance store"],"vi":["Tiệm làm tóc","Hiệu sách","Cửa hàng tạp hóa","Cửa hàng đồ gia dụng"],"ans":"C","xp":"Người nói: \"I opened this grocery store five years ago.\" → (C)."},{"n":99,"q":"According to the speaker, what did the business receive?","qvi":"Theo người nói, cửa hàng đã nhận được gì?","opts":["A loan","An award","Some sample products","Good customer reviews"],"vi":["Một khoản vay","Một giải thưởng","Một số sản phẩm mẫu","Đánh giá tốt từ khách hàng"],"ans":"A","xp":"Người nói: \"we've received a loan that will allow us to expand our operations!\" → (A)."},{"n":100,"q":"Look at the graphic. Which day will the business hours change?","qvi":"Nhìn vào bảng. Giờ mở cửa của ngày nào sẽ thay đổi?","opts":["Thursday","Friday","Saturday","Sunday"],"vi":["Thứ Năm","Thứ Sáu","Thứ Bảy","Chủ Nhật"],"ans":"D","xp":"Người nói: \"effective immediately, we'll be open seven days a week!\" Theo bảng, hiện tại chỉ có Chủ Nhật đóng cửa (Sunday: Closed) → mở cửa 7 ngày/tuần nghĩa là giờ của Chủ Nhật sẽ thay đổi → (D)."}],"a":"E24-T10-98-100.mp3","img":"g98.png"}]},"rc":{"p5":[{"n":101,"q":"According to the department head, ------- are ready to begin work on the Arborney Bridge project.","opts":["us","we","our","ours"],"ans":"B","xp":"Đại từ nhân xưng: chỗ trống đứng trước động từ 'are' và làm chủ ngữ của câu → cần đại từ chủ ngữ 'we'. (A) us là tân ngữ, (C) our là tính từ sở hữu (phải đi kèm danh từ), (D) ours là đại từ sở hữu (= cái của chúng tôi) – không hợp nghĩa.\nDịch: Theo lời trưởng phòng, chúng tôi đã sẵn sàng bắt đầu công việc cho dự án cầu Arborney."},{"n":102,"q":"The policy prohibiting visitor access to the laboratory must be ------- followed.","opts":["strictly","bitterly","sizably","colorfully"],"ans":"A","xp":"Từ vựng (trạng từ): cụm cố định 'be strictly followed' = được tuân thủ nghiêm ngặt. (A) strictly = nghiêm ngặt → chọn. (B) bitterly = cay đắng, (C) sizably = đáng kể (về kích thước), (D) colorfully = sặc sỡ – không hợp nghĩa.\nDịch: Quy định cấm khách ra vào phòng thí nghiệm phải được tuân thủ nghiêm ngặt."},{"n":103,"q":"Yoon-Hee Kim is the ------- graduate of Serrica University to lead a Fortune 500 company.","opts":["most","for","first","nearly"],"ans":"C","xp":"Từ vựng/cấu trúc: 'the first + danh từ + to V' = người đầu tiên làm gì. Chỗ trống đứng giữa 'the' và danh từ 'graduate' → cần tính từ; 'first' (đầu tiên) hợp nghĩa với 'to lead'. (A) most (nhất/hầu hết) cần đi với tính từ, (B) for là giới từ, (D) nearly là trạng từ 'gần như'.\nDịch: Yoon-Hee Kim là cựu sinh viên đầu tiên của Đại học Serrica lãnh đạo một công ty thuộc Fortune 500."},{"n":104,"q":"Contact Frank Marilli in the IT department ------- you have any problems with the new database software.","opts":["and","then","but","if"],"ans":"D","xp":"Liên từ: chỗ trống nối hai mệnh đề 'Contact Frank Marilli...' và 'you have any problems...'; nghĩa là 'liên hệ ... NẾU bạn gặp vấn đề' → 'if' (nếu). (A) and = và, (C) but = nhưng – không hợp nghĩa; (B) then = sau đó là trạng từ, không nối mệnh đề.\nDịch: Hãy liên hệ Frank Marilli ở phòng IT nếu bạn gặp bất kỳ vấn đề nào với phần mềm cơ sở dữ liệu mới."},{"n":105,"q":"A ------- efficiency expert will be visiting our work site in early November.","opts":["led","leader","leading","leads"],"ans":"C","xp":"Từ loại: chỗ trống đứng giữa mạo từ 'A' và cụm danh từ 'efficiency expert' → cần tính từ. 'leading' = hàng đầu, chủ chốt → 'a leading expert' = một chuyên gia hàng đầu. (A) led là quá khứ phân từ (mang nghĩa bị động 'được dẫn dắt' – không hợp), (B) leader là danh từ, (D) leads là động từ.\nDịch: Một chuyên gia hàng đầu về hiệu suất sẽ đến thăm công trường của chúng ta vào đầu tháng Mười Một."},{"n":106,"q":"At Gallant's Pet Store, customer ------- are accepted between 9:00 A.M. and 6:00 P.M.","opts":["behaviors","relations","orders","types"],"ans":"C","xp":"Từ vựng: 'customer orders are accepted' = đơn đặt hàng của khách được tiếp nhận (trong khung giờ). (C) orders = đơn hàng → chọn. (A) behaviors = hành vi, (B) relations = quan hệ, (D) types = loại – không thể 'được tiếp nhận trong giờ làm việc'.\nDịch: Tại Cửa hàng Thú cưng Gallant's, đơn đặt hàng của khách được tiếp nhận từ 9 giờ sáng đến 6 giờ chiều."},{"n":107,"q":"The management at Carette Industries ------- values the work of the research team.","opts":["high","highly","highest","higher"],"ans":"B","xp":"Từ loại: chỗ trống đứng trước động từ 'values' → cần trạng từ bổ nghĩa cho động từ. 'highly value' = đánh giá rất cao. (A) high là tính từ/trạng từ chỉ độ cao vật lý, (C) highest và (D) higher là dạng so sánh của tính từ.\nDịch: Ban lãnh đạo Carette Industries đánh giá rất cao công việc của nhóm nghiên cứu."},{"n":108,"q":"Pentrexa Pharmacy is able to ------- most prescriptions within one business day.","opts":["care","earn","fill","lift"],"ans":"C","xp":"Từ vựng: cụm 'fill a prescription' = bán/cấp thuốc theo đơn. (C) fill → chọn. (A) care = quan tâm (care for), (B) earn = kiếm được, (D) lift = nâng lên – không đi với 'prescriptions'.\nDịch: Nhà thuốc Pentrexa có thể cấp thuốc cho hầu hết các đơn thuốc trong vòng một ngày làm việc."},{"n":109,"q":"The ------- of a parking structure for Huron General Hospital will begin on June 1.","opts":["construct","constructed","construction","constructs"],"ans":"C","xp":"Từ loại: chỗ trống đứng sau 'The' và trước 'of' → cần danh từ làm chủ ngữ. (C) construction = việc xây dựng → chọn. (A) construct và (D) constructs là động từ, (B) constructed là quá khứ/phân từ.\nDịch: Việc xây dựng một bãi đỗ xe nhiều tầng cho Bệnh viện Đa khoa Huron sẽ bắt đầu vào ngày 1 tháng 6."},{"n":110,"q":"Some of the flower beds surrounding Dale Valley Lodge had to be replanted ------- the recent rainstorm.","opts":["after","among","opposite","beside"],"ans":"A","xp":"Giới từ: phải trồng lại luống hoa SAU trận mưa bão → 'after' (sau). (B) among = giữa (nhiều thứ), (C) opposite = đối diện, (D) beside = bên cạnh – là giới từ chỉ vị trí, không hợp với 'the recent rainstorm'.\nDịch: Một số luống hoa xung quanh nhà nghỉ Dale Valley đã phải trồng lại sau trận mưa bão gần đây."},{"n":111,"q":"Several water stations ------- along the route of next week's marathon.","opts":["being installed","will be installed","to install","installed"],"ans":"B","xp":"Thì + thể bị động: câu chưa có động từ chính; 'next week's marathon' → tương lai; trạm nước được lắp đặt (bị động) → 'will be installed'. (A) being installed và (C) to install không phải động từ chính; (D) installed nếu là quá khứ chủ động thì sai nghĩa (trạm nước không tự lắp) và sai thì.\nDịch: Một số trạm nước sẽ được lắp đặt dọc theo lộ trình cuộc chạy marathon tuần tới."},{"n":112,"q":"The Crown Lagoon Hotel has 150 rooms, each with a ------- view of the city.","opts":["valid","recent","modern","scenic"],"ans":"D","xp":"Từ vựng (tính từ): 'a scenic view' = khung cảnh đẹp. (D) scenic → chọn. (A) valid = có hiệu lực, (B) recent = gần đây, (C) modern = hiện đại – không đi tự nhiên với 'view'.\nDịch: Khách sạn Crown Lagoon có 150 phòng, mỗi phòng đều có tầm nhìn đẹp ra thành phố."},{"n":113,"q":"Overall, charitable donations rose last year, ------- specific dollar amounts are not yet available.","opts":["although","neither","whenever","so"],"ans":"A","xp":"Liên từ: hai mệnh đề mang ý tương phản (quyên góp tăng – nhưng chưa có số liệu cụ thể) → 'although' (mặc dù). (B) neither = cũng không (neither...nor), (C) whenever = bất cứ khi nào, (D) so = vì vậy (chỉ kết quả) – không hợp nghĩa.\nDịch: Nhìn chung, tiền quyên góp từ thiện đã tăng vào năm ngoái, mặc dù số tiền cụ thể vẫn chưa có."},{"n":114,"q":"We strongly advise you to back up the data stored on your electronic device ------- turning it in for repairs.","opts":["once","both","then","before"],"ans":"D","xp":"Giới từ: sau chỗ trống là V-ing 'turning' → cần giới từ; nghĩa: sao lưu dữ liệu TRƯỚC KHI mang máy đi sửa → 'before'. (A) once = một khi (liên từ, không hợp nghĩa), (B) both = cả hai, (C) then = sau đó (trạng từ).\nDịch: Chúng tôi đặc biệt khuyên bạn sao lưu dữ liệu lưu trên thiết bị điện tử trước khi mang thiết bị đi sửa."},{"n":115,"q":"Because Ms. Garcia enjoys creating charts and graphs, her supervisor ------- asks her to make materials for presentations.","opts":["frequent","frequents","frequenting","frequently"],"ans":"D","xp":"Từ loại: chỗ trống đứng giữa chủ ngữ 'her supervisor' và động từ 'asks' → cần trạng từ. (D) frequently = thường xuyên → chọn. (A) frequent là tính từ, (B) frequents và (C) frequenting là dạng động từ.\nDịch: Vì cô Garcia thích tạo biểu đồ và đồ thị, người giám sát thường xuyên nhờ cô làm tài liệu cho các bài thuyết trình."},{"n":116,"q":"Manufacturers of high-end products are dealing with excess ------- because consumers are buying fewer luxury items.","opts":["confidence","inventory","capacity","energy"],"ans":"B","xp":"Từ vựng: người tiêu dùng mua ít hàng xa xỉ hơn → nhà sản xuất bị dư hàng tồn kho → 'excess inventory' = hàng tồn kho dư thừa. (A) confidence = sự tự tin, (C) capacity = công suất/sức chứa, (D) energy = năng lượng – không hợp lý do.\nDịch: Các nhà sản xuất sản phẩm cao cấp đang phải xử lý lượng hàng tồn kho dư thừa vì người tiêu dùng mua ít mặt hàng xa xỉ hơn."},{"n":117,"q":"The Hayle Group, ------- consists of business consultants and lawyers, advocates for tax policy reforms.","opts":["themselves","someone","whoever","which"],"ans":"D","xp":"Đại từ quan hệ: chỗ trống mở đầu mệnh đề quan hệ bổ sung cho 'The Hayle Group' (một tổ chức, sau dấu phẩy) và làm chủ ngữ cho 'consists' → 'which'. (A) themselves là đại từ phản thân, (B) someone = ai đó, (C) whoever = bất cứ ai – không dùng làm đại từ quan hệ sau dấu phẩy.\nDịch: Tập đoàn Hayle, gồm các nhà tư vấn kinh doanh và luật sư, ủng hộ việc cải cách chính sách thuế."},{"n":118,"q":"Daishi Asayama is one of three applicants being ------- to oversee the Kingston franchises.","opts":["decided","corrected","considered","practiced"],"ans":"C","xp":"Từ vựng: 'be considered to + V' / 'applicants being considered' = các ứng viên đang được xem xét. (C) considered → chọn. (A) decided = được quyết định, (B) corrected = được sửa, (D) practiced = được luyện tập – không dùng cho người ứng tuyển.\nDịch: Daishi Asayama là một trong ba ứng viên đang được xem xét để quản lý các cửa hàng nhượng quyền ở Kingston."},{"n":119,"q":"The reviewer of Ms. Chen's book noted that her research was -------.","opts":["impressed","impressive","impress","impression"],"ans":"B","xp":"Từ loại: sau động từ 'was' cần tính từ làm bổ ngữ. 'impressive' = ấn tượng (gây ấn tượng) – dùng cho vật 'her research'. (A) impressed = cảm thấy ấn tượng (dùng cho người), (C) impress là động từ, (D) impression là danh từ.\nDịch: Người nhận xét cuốn sách của cô Chen ghi nhận rằng công trình nghiên cứu của cô rất ấn tượng."},{"n":120,"q":"Mr. Pereira has worked in our legal department ------- his transfer to the Atlanta office ten years ago.","opts":["since","between","without","like"],"ans":"A","xp":"Giới từ + thì: câu dùng hiện tại hoàn thành 'has worked' và mốc thời gian 'his transfer ... ten years ago' → 'since' (kể từ). (B) between = giữa hai thứ, (C) without = không có, (D) like = giống như.\nDịch: Ông Pereira đã làm việc ở phòng pháp chế của chúng tôi kể từ khi được chuyển đến văn phòng Atlanta mười năm trước."},{"n":121,"q":"Pennypack Markets soon plans to break ground on its largest ------- center in the area.","opts":["distributive","distribute","distributable","distribution"],"ans":"D","xp":"Từ loại/danh từ ghép: 'distribution center' = trung tâm phân phối (danh từ ghép cố định). (D) distribution → chọn. (A) distributive (mang tính phân phối) và (C) distributable (có thể phân phối) là tính từ nhưng không tạo thành cụm đúng nghĩa; (B) distribute là động từ.\nDịch: Pennypack Markets dự định sắp khởi công trung tâm phân phối lớn nhất của mình trong khu vực."},{"n":122,"q":"Ms. Miller ------- welcomed the speakers who will be leading the workshops.","opts":["accessibly","abundantly","briefly","momentarily"],"ans":"C","xp":"Từ vựng (trạng từ): 'briefly welcomed' = chào mừng ngắn gọn. (C) briefly → chọn. (A) accessibly = dễ tiếp cận, (B) abundantly = dồi dào, (D) momentarily = trong chốc lát/ngay lập tức – không hợp nghĩa với 'welcomed'.\nDịch: Cô Miller đã phát biểu chào mừng ngắn gọn các diễn giả sẽ dẫn dắt các buổi hội thảo."},{"n":123,"q":"Mr. Nayar ------- the need for enhanced safety protocols long before the government issued a report on the topic.","opts":["stresses","stressing","will stress","had stressed"],"ans":"D","xp":"Thì: 'long before the government issued a report' (quá khứ) → hành động của ông Nayar xảy ra TRƯỚC một hành động khác trong quá khứ → quá khứ hoàn thành 'had stressed'. (A) hiện tại đơn, (C) tương lai – sai thì; (B) stressing không phải động từ chính.\nDịch: Ông Nayar đã nhấn mạnh sự cần thiết của các quy trình an toàn được tăng cường từ lâu trước khi chính phủ công bố báo cáo về chủ đề này."},{"n":124,"q":"Angelia Financial recently announced ------- changes to its benefits package that were greeted enthusiastically by its staff.","opts":["judgmental","substantial","magnetic","chaotic"],"ans":"B","xp":"Từ vựng (tính từ): 'substantial changes' = những thay đổi đáng kể. (B) substantial → chọn; nhân viên đón nhận nhiệt tình nên thay đổi phải mang tính tích cực, lớn. (A) judgmental = hay phán xét, (C) magnetic = có từ tính/lôi cuốn, (D) chaotic = hỗn loạn.\nDịch: Angelia Financial gần đây đã công bố những thay đổi đáng kể trong gói phúc lợi và được nhân viên đón nhận nhiệt tình."},{"n":125,"q":"------- poems written by Mike Hanover are included in the new edition of Merwyn's Anthology.","opts":["Whichever","Several","Something","None"],"ans":"B","xp":"Từ hạn định: chỗ trống đứng trước danh từ số nhiều 'poems' và động từ 'are' → 'Several' (một vài). (A) Whichever = bất cứ cái nào (mở đầu mệnh đề), (C) Something là đại từ, không đứng trước danh từ; (D) None phải dùng 'None of the poems'.\nDịch: Một vài bài thơ do Mike Hanover sáng tác được đưa vào ấn bản mới của tuyển tập Merwyn's Anthology."},{"n":126,"q":"For a list of local farms that supply food to restaurants, please ------- to the Hueland Farm Association Web site.","opts":["elect","adapt","present","refer"],"ans":"D","xp":"Từ vựng: 'refer to + nơi' = tham khảo, xem (trang web). (D) refer → chọn. (A) elect = bầu chọn, (B) adapt = thích nghi (adapt to sth), (C) present = trình bày – không hợp nghĩa.\nDịch: Để có danh sách các trang trại địa phương cung cấp thực phẩm cho nhà hàng, vui lòng tham khảo trang web của Hiệp hội Nông trại Hueland."},{"n":127,"q":"Samidu Communications is soliciting suggestions from its staff about ways of improving employee -------.","opts":["produced","productive","productivity","productively"],"ans":"C","xp":"Từ loại: 'improving' cần tân ngữ là danh từ; 'employee productivity' = năng suất của nhân viên (danh từ ghép). (C) productivity → chọn. (A) produced là động từ/phân từ, (B) productive là tính từ, (D) productively là trạng từ.\nDịch: Samidu Communications đang thu thập đề xuất từ nhân viên về các cách nâng cao năng suất làm việc của nhân viên."},{"n":128,"q":"Mr. Ben-Moshe always reserves the banquet room at Saitomi's Kitchen ------- the sales team has a holiday event.","opts":["whenever","regarding","whether","besides"],"ans":"A","xp":"Liên từ: chỗ trống nối hai mệnh đề; 'always reserves ... whenever ...' = luôn đặt phòng mỗi khi... → 'whenever' (bất cứ khi nào). (B) regarding = về việc và (D) besides = ngoài ra là giới từ, không nối mệnh đề; (C) whether = liệu – không hợp nghĩa.\nDịch: Ông Ben-Moshe luôn đặt phòng tiệc tại nhà hàng Saitomi's Kitchen mỗi khi đội bán hàng có sự kiện dịp lễ."},{"n":129,"q":"Annika Dulin ------- the marketing department at Tollason Industries' planning meeting tomorrow.","opts":["will represent","had represented","to represent","be representing"],"ans":"A","xp":"Thì: dấu hiệu 'tomorrow' → tương lai đơn 'will represent'. (B) quá khứ hoàn thành – sai thì; (C) to represent và (D) be representing không thể làm động từ chính.\nDịch: Annika Dulin sẽ đại diện cho phòng marketing tại cuộc họp lập kế hoạch của Tollason Industries vào ngày mai."},{"n":130,"q":"Do not post any statements about the company on social media without prior -------.","opts":["authorization","supplement","consequence","responsibility"],"ans":"A","xp":"Từ vựng: 'without prior authorization' = khi chưa được cho phép trước. (A) authorization = sự cho phép → chọn. (B) supplement = phần bổ sung, (C) consequence = hậu quả, (D) responsibility = trách nhiệm – không hợp nghĩa.\nDịch: Không đăng bất kỳ phát ngôn nào về công ty lên mạng xã hội khi chưa được cho phép trước."}],"p6":[{"ns":[131,134],"head":"Questions 131-134 refer to the following article.","passage":"<h3>Kray Villa Museum To Celebrate Grand Opening</h3><p>DEERFIELD (May 2)—The official opening of the Kray Villa Museum will take place on May 29 at 10 A.M. To mark the occasion, various festivities will be held throughout the day. <span class=\"blank\" data-n=\"131\">-------</span>. Visit www.krayvillamuseum.org for details.</p><p>The museum is housed in the imposing structure <span class=\"blank\" data-n=\"132\">-------</span> was home to the once-influential Kray family beginning in the late 1800s. Having laid abandoned for the last 30 years, the property was purchased 2 years ago by the Deerfield Historical Society. Subsequently, the gardens were restored to appear as they did when the first generation of Krays moved into the villa. <span class=\"blank\" data-n=\"133\">-------</span>, furnishings of the kind most likely used by the family are on display.</p><p>During the museum's opening festivities, a live band <span class=\"blank\" data-n=\"134\">-------</span> music that was popular in the late nineteenth century.</p>","vi":"Bảo tàng Biệt thự Kray sẽ tổ chức lễ khai trương\n\nDEERFIELD (ngày 2 tháng 5) – Lễ khai trương chính thức của Bảo tàng Biệt thự Kray sẽ diễn ra vào lúc 10 giờ sáng ngày 29 tháng 5. Để đánh dấu dịp này, nhiều hoạt động lễ hội sẽ được tổ chức suốt cả ngày. Vào cửa miễn phí, nhưng khuyến khích quyên góp. Hãy truy cập www.krayvillamuseum.org để biết thêm chi tiết.\n\nBảo tàng nằm trong tòa nhà đồ sộ từng là nơi ở của gia tộc Kray – một gia đình từng có tầm ảnh hưởng – bắt đầu từ cuối những năm 1800. Sau khi bị bỏ hoang suốt 30 năm qua, khu đất này đã được Hội Lịch sử Deerfield mua lại cách đây 2 năm. Sau đó, các khu vườn đã được phục hồi để trông giống như lúc thế hệ đầu tiên của gia đình Kray dọn vào biệt thự. Ngoài ra, đồ nội thất thuộc loại mà gia đình này nhiều khả năng đã sử dụng cũng đang được trưng bày.\n\nTrong các hoạt động lễ hội khai trương bảo tàng, một ban nhạc sẽ biểu diễn trực tiếp những bản nhạc từng thịnh hành vào cuối thế kỷ mười chín.","qs":[{"n":131,"opts":["This year's celebrations are part of a weeklong national campaign.","Results of the survey will be presented at 6:00 P.M.","Programs will be distributed at the next meeting.","Admission is free, but a donation is suggested."],"ans":"D","xp":"Điền câu: câu trước nói về lễ khai trương và các hoạt động suốt cả ngày; câu sau là 'Visit www.krayvillamuseum.org for details.' → câu cần điền phải là thông tin thực tế dành cho khách tham dự sự kiện. (D) 'Vào cửa miễn phí, nhưng khuyến khích quyên góp' hợp lý nhất. (A) chiến dịch quốc gia kéo dài một tuần – không liên quan đến lễ khai trương một ngày; (B) kết quả khảo sát và (C) chương trình phát ở cuộc họp tới – không được nhắc đến trong bài.\nDịch: Vào cửa miễn phí, nhưng khuyến khích quyên góp.\n(A) Lễ kỷ niệm năm nay là một phần của chiến dịch quốc gia kéo dài một tuần.\n(B) Kết quả khảo sát sẽ được trình bày lúc 6 giờ chiều.\n(C) Chương trình sẽ được phát tại cuộc họp tới.\n(D) Vào cửa miễn phí, nhưng khuyến khích quyên góp."},{"n":132,"opts":["such","that","what","all"],"ans":"B","xp":"Đại từ quan hệ: chỗ trống đứng sau danh từ 'the imposing structure' và đứng trước động từ 'was' → cần đại từ quan hệ làm chủ ngữ thay cho vật: 'that' (= which). (C) what không đi sau danh từ (what = the thing which), (A) such và (D) all không mở đầu mệnh đề quan hệ.\nDịch: Bảo tàng nằm trong tòa nhà đồ sộ từng là nơi ở của gia tộc Kray từ cuối những năm 1800."},{"n":133,"opts":["Conversely","Additionally","In the meantime","To this end"],"ans":"B","xp":"Trạng từ liên kết: câu trước nói các khu vườn đã được phục hồi như xưa; câu này nói thêm đồ nội thất kiểu cũ cũng được trưng bày → bổ sung thông tin cùng chiều → 'Additionally' (ngoài ra). (A) Conversely = ngược lại, (C) In the meantime = trong khi đó, (D) To this end = nhằm mục đích này – không hợp mạch.\nDịch: Ngoài ra, đồ nội thất thuộc loại mà gia đình này nhiều khả năng đã sử dụng cũng đang được trưng bày."},{"n":134,"opts":["will perform","had to perform","was performing","could have performed"],"ans":"A","xp":"Thì: lễ khai trương diễn ra vào ngày 29/5, còn bài báo viết ngày 2/5 → sự kiện trong tương lai → 'will perform'. (B) had to perform, (C) was performing là quá khứ; (D) could have performed = lẽ ra đã có thể biểu diễn – đều sai thời gian.\nDịch: Trong các hoạt động lễ hội khai trương bảo tàng, một ban nhạc sẽ biểu diễn trực tiếp những bản nhạc thịnh hành vào cuối thế kỷ 19."}]},{"ns":[135,138],"head":"Questions 135-138 refer to the following e-mail.","passage":"<div class=\"hdr\"><p><b>To:</b> All employees</p><p><b>From:</b> Cecil Radu, Information Technology Manager</p><p><b>Date:</b> April 8</p><p><b>Re:</b> Network alert</p></div><p>We are experiencing some problems with our local network. Some of the affected services include the <span class=\"blank\" data-n=\"135\">-------</span> company Web site and the payroll database. We have also received information <span class=\"blank\" data-n=\"136\">-------</span> network data becoming corrupted and files not saving properly. Therefore, to ensure that you do not lose any work, please avoid using the network this morning while my team addresses these <span class=\"blank\" data-n=\"137\">-------</span>. We anticipate that the systems will be fully functional by this afternoon. <span class=\"blank\" data-n=\"138\">-------</span>.</p>","vi":"Gửi: Toàn thể nhân viên\nTừ: Cecil Radu, Trưởng phòng Công nghệ Thông tin\nNgày: 8 tháng 4\nV/v: Cảnh báo về mạng\n\nChúng ta đang gặp một số sự cố với mạng nội bộ. Một số dịch vụ bị ảnh hưởng bao gồm trang web nội bộ của công ty và cơ sở dữ liệu bảng lương. Chúng tôi cũng nhận được thông tin về việc dữ liệu mạng bị hỏng và các tập tin không lưu được đúng cách. Vì vậy, để đảm bảo các bạn không bị mất công việc, vui lòng tránh sử dụng mạng trong sáng nay trong khi nhóm của tôi xử lý các sự cố này. Chúng tôi dự kiến hệ thống sẽ hoạt động bình thường hoàn toàn vào chiều nay. Cảm ơn các bạn đã kiên nhẫn.","qs":[{"n":135,"opts":["internalizing","internalize","internally","internal"],"ans":"D","xp":"Từ loại: chỗ trống đứng giữa 'the' và cụm danh từ 'company Web site' → cần tính từ. (D) internal = nội bộ → 'the internal company Web site' = trang web nội bộ của công ty. (A) internalizing và (B) internalize là động từ (tiếp thu/nội hóa), (C) internally là trạng từ.\nDịch: Một số dịch vụ bị ảnh hưởng bao gồm trang web nội bộ của công ty và cơ sở dữ liệu bảng lương."},{"n":136,"opts":["as","in","about","with"],"ans":"C","xp":"Giới từ: 'information about sth' = thông tin về điều gì. (C) about → chọn. (A) as = như là, (B) in = trong, (D) with = với – không đi với 'information' theo nghĩa này.\nDịch: Chúng tôi cũng nhận được thông tin về việc dữ liệu mạng bị hỏng và các tập tin không lưu được đúng cách."},{"n":137,"opts":["issues","clients","articles","proposals"],"ans":"A","xp":"Từ vựng: 'these ------' chỉ lại những vấn đề vừa nêu (mạng gặp sự cố, dữ liệu bị hỏng) → 'issues' (vấn đề, sự cố); 'address issues' = xử lý vấn đề. (B) clients = khách hàng, (C) articles = bài báo, (D) proposals = đề xuất – không hợp mạch.\nDịch: ...vui lòng tránh sử dụng mạng trong sáng nay trong khi nhóm của tôi xử lý các sự cố này."},{"n":138,"opts":["The network server will be expensive.","Your computer may be corrupted.","Thank you for your patience.","Contact the IT help desk."],"ans":"C","xp":"Điền câu: đây là câu kết của e-mail; trước đó người viết yêu cầu nhân viên tạm ngừng dùng mạng và hẹn hệ thống sẽ hoạt động lại vào chiều nay → lời cảm ơn vì sự kiên nhẫn là câu kết tự nhiên. (A) máy chủ sẽ đắt – không liên quan; (B) máy tính của bạn có thể bị hỏng – gây hoang mang, trái với lời trấn an; (D) liên hệ bộ phận hỗ trợ IT – mâu thuẫn vì chính phòng IT đang gửi thư và đang xử lý.\nDịch: Cảm ơn các bạn đã kiên nhẫn.\n(A) Máy chủ mạng sẽ tốn kém.\n(B) Máy tính của bạn có thể bị hỏng.\n(C) Cảm ơn sự kiên nhẫn của bạn.\n(D) Hãy liên hệ bộ phận hỗ trợ IT."}]},{"ns":[139,142],"head":"Questions 139-142 refer to the following notice.","passage":"<p>April 2</p><p>Dear TP&amp;G Customer,</p><p>Takoradi Power &amp; Gas (TP&amp;G) is committed to providing every customer with dependable electricity service. To this end, we need to make some improvements to our <span class=\"blank\" data-n=\"139\">-------</span>. A maintenance crew will be upgrading transformers in your neighbourhood on or about 22 April, beginning at 10 A.M. <span class=\"blank\" data-n=\"140\">-------</span>, we will need to shut off the electricity to residences in your area from approximately 10 A.M. to 1 P.M. on that day. <span class=\"blank\" data-n=\"141\">-------</span>. We hope that by <span class=\"blank\" data-n=\"142\">-------</span> this notice, any disruptions caused by the planned outage will be minimized.</p>","vi":"Ngày 2 tháng 4\n\nKính gửi Quý khách hàng của TP&G,\n\nCông ty Điện và Khí đốt Takoradi (TP&G) cam kết cung cấp dịch vụ điện ổn định, đáng tin cậy cho mọi khách hàng. Để đạt được điều này, chúng tôi cần thực hiện một số cải tiến đối với hệ thống của mình. Một đội bảo trì sẽ nâng cấp các máy biến áp trong khu phố của quý khách vào khoảng ngày 22 tháng 4, bắt đầu lúc 10 giờ sáng. Rất tiếc, chúng tôi sẽ phải cắt điện các hộ dân trong khu vực của quý khách từ khoảng 10 giờ sáng đến 1 giờ chiều ngày hôm đó. Chúng tôi xin lỗi vì sự bất tiện tạm thời này. Chúng tôi hy vọng rằng bằng việc gửi thông báo này, mọi gián đoạn do đợt cắt điện theo kế hoạch gây ra sẽ được giảm thiểu.","qs":[{"n":139,"opts":["office","system","vehicles","records"],"ans":"B","xp":"Từ vựng: để cung cấp dịch vụ điện ổn định, công ty cần cải tiến 'hệ thống' của mình; câu sau nói về nâng cấp máy biến áp (một phần của hệ thống điện) → (B) system. (A) office = văn phòng, (C) vehicles = xe cộ, (D) records = hồ sơ – không liên quan đến việc nâng cấp máy biến áp.\nDịch: Để đạt được điều này, chúng tôi cần thực hiện một số cải tiến đối với hệ thống của mình."},{"n":140,"opts":["If not","Nonetheless","Unfortunately","On the other hand"],"ans":"C","xp":"Trạng từ liên kết: câu này báo tin không vui (phải cắt điện) → 'Unfortunately' (thật không may/rất tiếc). (A) If not = nếu không, (B) Nonetheless = tuy nhiên/dù vậy, (D) On the other hand = mặt khác – đều chỉ sự tương phản, không hợp vì câu trước và câu này không đối lập nhau.\nDịch: Rất tiếc, chúng tôi sẽ phải cắt điện các hộ dân trong khu vực của quý khách từ khoảng 10 giờ sáng đến 1 giờ chiều ngày hôm đó."},{"n":141,"opts":["We apologize for the temporary inconvenience.","We respond to most service requests within 24 hours.","Other companies specialize in lighting installations.","Here are some tips for reducing your energy bill."],"ans":"A","xp":"Điền câu: câu trước thông báo sẽ cắt điện từ 10 giờ sáng đến 1 giờ chiều → lời xin lỗi vì sự bất tiện tạm thời là hợp lý nhất. (B) phản hồi yêu cầu dịch vụ trong 24 giờ, (C) công ty khác chuyên lắp đèn, (D) mẹo giảm hóa đơn điện – đều không liên quan đến việc cắt điện.\nDịch: Chúng tôi xin lỗi vì sự bất tiện tạm thời này.\n(A) Chúng tôi xin lỗi vì sự bất tiện tạm thời.\n(B) Chúng tôi phản hồi hầu hết các yêu cầu dịch vụ trong vòng 24 giờ.\n(C) Các công ty khác chuyên về lắp đặt hệ thống chiếu sáng.\n(D) Sau đây là một số mẹo giúp giảm hóa đơn tiền điện."},{"n":142,"opts":["sent","to send","will send","sending"],"ans":"D","xp":"Dạng động từ: sau giới từ 'by' phải dùng V-ing → 'by sending this notice' = bằng việc gửi thông báo này. (A) sent là quá khứ/phân từ, (B) to send là to-V, (C) will send là động từ chia thì – không đứng sau giới từ.\nDịch: Chúng tôi hy vọng rằng bằng việc gửi thông báo này, mọi gián đoạn do đợt cắt điện theo kế hoạch gây ra sẽ được giảm thiểu."}]},{"ns":[143,146],"head":"Questions 143-146 refer to the following e-mail.","passage":"<div class=\"hdr\"><p><b>To:</b> hanna.kalita@netmail.co.uk</p><p><b>From:</b> patientoutreach@ebmp.co.uk</p><p><b>Date:</b> 12 June</p><p><b>Subject:</b> Invitation to patient portal</p></div><p>Dear Ms. Kalita,</p><p>East Burberry Medical Practice has recently rolled out its patient portal, Burmed Connect. This service <span class=\"blank\" data-n=\"143\">-------</span> to help you manage your healthcare at your convenience. You are invited to create an account to access the portal. Once enrolled, you will be able to book appointments with our doctors as well as view your medical records and request prescriptions. <span class=\"blank\" data-n=\"144\">-------</span>, you can use Burmed Connect to send messages to your doctor. Only you and your doctor will be able to see any messages exchanged between the two of you. <span class=\"blank\" data-n=\"145\">-------</span>.</p><p>To create an account, start by going to www.eastburberrymedicalpractice/patient-portal.co.uk. If you experience any difficulties with the <span class=\"blank\" data-n=\"146\">-------</span> process, please call 20 5550 0169.</p><p>Sincerely,</p><p>Emma Richardson, Patient Outreach Coordinator</p>","vi":"Gửi: hanna.kalita@netmail.co.uk\nTừ: patientoutreach@ebmp.co.uk\nNgày: 12 tháng 6\nTiêu đề: Lời mời sử dụng cổng thông tin bệnh nhân\n\nKính gửi cô Kalita,\n\nPhòng khám East Burberry vừa ra mắt cổng thông tin dành cho bệnh nhân mang tên Burmed Connect. Dịch vụ này nhằm giúp cô quản lý việc chăm sóc sức khỏe của mình một cách thuận tiện. Chúng tôi mời cô tạo tài khoản để truy cập cổng thông tin. Sau khi đăng ký, cô có thể đặt lịch hẹn với các bác sĩ của chúng tôi, cũng như xem hồ sơ bệnh án và yêu cầu kê đơn thuốc. Hơn nữa, cô có thể dùng Burmed Connect để gửi tin nhắn cho bác sĩ của mình. Chỉ cô và bác sĩ mới có thể xem các tin nhắn trao đổi giữa hai người. Bảo vệ quyền riêng tư của cô là trách nhiệm mà chúng tôi rất coi trọng.\n\nĐể tạo tài khoản, hãy bắt đầu bằng cách truy cập www.eastburberrymedicalpractice/patient-portal.co.uk. Nếu gặp bất kỳ khó khăn nào trong quá trình đăng ký, vui lòng gọi số 20 5550 0169.\n\nTrân trọng,\n\nEmma Richardson, Điều phối viên Tiếp cận Bệnh nhân","qs":[{"n":143,"opts":["has been intended","will be intended","was intended","is intended"],"ans":"D","xp":"Thì: câu nói về mục đích hiện tại của dịch vụ (vừa ra mắt và đang hoạt động) → hiện tại đơn bị động 'is intended to V' = nhằm để. Các câu xung quanh cũng dùng hiện tại ('You are invited'). (A) hiện tại hoàn thành, (B) tương lai, (C) quá khứ – không phù hợp để nêu mục đích chung, hiện tại của dịch vụ.\nDịch: Dịch vụ này nhằm giúp cô quản lý việc chăm sóc sức khỏe của mình một cách thuận tiện."},{"n":144,"opts":["Furthermore","Instead","However","Otherwise"],"ans":"A","xp":"Trạng từ liên kết: câu trước liệt kê các tính năng (đặt lịch, xem hồ sơ, yêu cầu kê đơn); câu này nêu thêm một tính năng nữa (gửi tin nhắn cho bác sĩ) → bổ sung → 'Furthermore' (hơn nữa). (B) Instead = thay vào đó, (C) However = tuy nhiên, (D) Otherwise = nếu không thì – không hợp mạch.\nDịch: Hơn nữa, cô có thể dùng Burmed Connect để gửi tin nhắn cho bác sĩ của mình."},{"n":145,"opts":["Our previous portal will no longer be updated.","The health app can be downloaded from our Web site.","Protecting your privacy is a responsibility we take seriously.","You will be locked out of your account after a third failed attempt."],"ans":"C","xp":"Điền câu: câu trước nói 'Only you and your doctor will be able to see any messages exchanged between the two of you' (chỉ bệnh nhân và bác sĩ xem được tin nhắn) → nội dung về bảo mật; câu (C) 'Bảo vệ quyền riêng tư của bạn là trách nhiệm chúng tôi rất coi trọng' nối tiếp tự nhiên. (A) cổng thông tin cũ không còn cập nhật – bài không nhắc đến cổng cũ; (B) ứng dụng tải về – bài nói về cổng thông tin trên web; (D) bị khóa tài khoản sau 3 lần sai – chưa hề nói đến việc đăng nhập.\nDịch: Bảo vệ quyền riêng tư của cô là trách nhiệm mà chúng tôi rất coi trọng.\n(A) Cổng thông tin trước đây của chúng tôi sẽ không còn được cập nhật.\n(B) Ứng dụng sức khỏe có thể được tải xuống từ trang web của chúng tôi.\n(C) Bảo vệ quyền riêng tư của bạn là trách nhiệm chúng tôi rất coi trọng.\n(D) Bạn sẽ bị khóa tài khoản sau lần thử thất bại thứ ba."},{"n":146,"opts":["selection","registration","invention","deletion"],"ans":"B","xp":"Từ vựng: câu trước hướng dẫn cách tạo tài khoản ('To create an account...') → khó khăn gặp phải là trong 'quá trình đăng ký' → 'the registration process'. (A) selection = sự lựa chọn, (C) invention = phát minh, (D) deletion = sự xóa – không hợp mạch.\nDịch: Nếu gặp bất kỳ khó khăn nào trong quá trình đăng ký, vui lòng gọi số 20 5550 0169."}]}],"p7":[{"ns":[147,148],"head":"Questions 147-148 refer to the following sign.","passages":["<h3>Galloway Office Park</h3><p><u>Building 1</u><br>Harris Toddman, MD<br>Lansin Diagnostic Labs<br>Smiley Dental Offices</p><p><u>Building 2</u><br>Freel Primary Care Physicians<br>Rally Star Physical Therapy Associates</p><p><u>Building 3</u><br>Lee and Associates, Internists<br>Kare Medical Services</p><p><u>Building 4</u><br>Lurie Pharmaceuticals</p><p>No Truck Access<br>No Soliciting<br>No Trespassing</p>"],"vi":"Khu văn phòng Galloway\n\nTòa nhà 1\nBác sĩ Harris Toddman\nPhòng xét nghiệm chẩn đoán Lansin\nPhòng khám nha khoa Smiley\n\nTòa nhà 2\nCác bác sĩ chăm sóc ban đầu Freel\nHiệp hội vật lý trị liệu Rally Star\n\nTòa nhà 3\nLee và Cộng sự, Bác sĩ nội khoa\nDịch vụ y tế Kare\n\nTòa nhà 4\nDược phẩm Lurie\n\nCấm xe tải vào\nCấm chào hàng\nCấm xâm nhập trái phép","qs":[{"n":147,"q":"Where would the sign most likely be found?","qvi":"Tấm biển này có khả năng được đặt ở đâu nhất?","opts":["On an office desk","In a hospital waiting room","In the lobby of a real estate agency","Near the entrance of an office complex"],"ans":"D","xp":"Câu hỏi suy luận (địa điểm). Tấm biển có tên \"Galloway Office Park\" (khu văn phòng), liệt kê các đơn vị trong 4 tòa nhà (\"Building 1\" … \"Building 4\") và các quy định \"No Truck Access / No Soliciting / No Trespassing\" — đây là kiểu biển đặt ở lối vào của một khu phức hợp văn phòng → chọn (D). 'office park' ≈ 'office complex'.\n(A) Trên bàn làm việc trong văn phòng\n(B) Trong phòng chờ của bệnh viện\n(C) Trong sảnh của một công ty bất động sản\n(D) Gần lối vào của một khu phức hợp văn phòng"},{"n":148,"q":"What type of businesses are listed on the sign?","qvi":"Những loại hình doanh nghiệp nào được liệt kê trên tấm biển?","opts":["Health care","Legal services","Manufacturing","Finance"],"ans":"A","xp":"Câu hỏi chi tiết. Các đơn vị trên biển đều thuộc ngành y tế: \"Harris Toddman, MD\" (bác sĩ), \"Diagnostic Labs\" (phòng xét nghiệm), \"Dental Offices\" (nha khoa), \"Primary Care Physicians\", \"Physical Therapy\", \"Internists\", \"Medical Services\", \"Pharmaceuticals\" → chăm sóc sức khỏe → chọn (A).\n(A) Chăm sóc sức khỏe\n(B) Dịch vụ pháp lý\n(C) Sản xuất\n(D) Tài chính"}]},{"ns":[149,150],"head":"Questions 149-150 refer to the following text-message chain.","passages":["<div class=\"msg\"><p><b>Darion Gaines (11:16 A.M.)</b></p><p>Sonia, the sink in the third-floor break room is clogged.</p></div><div class=\"msg\"><p><b>Sonia Pinkerton (11:20 A.M.)</b></p><p>Again? That's the second time this month.</p></div><div class=\"msg\"><p><b>Darion Gaines (11:22 A.M.)</b></p><p>One of our sales associates got it unclogged last time, but maybe we should call a professional this time. Should I contact Mr. Green and let him know?</p></div><div class=\"msg\"><p><b>Sonia Pinkerton (11:23 A.M.)</b></p><p>The office manager? I think it might be best to call the head of maintenance, Tammy Toska. She can probably get someone out to fix it pretty quickly.</p></div><div class=\"msg\"><p><b>Darion Gaines (11:24 A.M.)</b></p><p>OK. I could reach out to her.</p></div><div class=\"msg\"><p><b>Sonia Pinkerton (11:25 A.M.)</b></p><p>Go ahead. In the meantime, I'll put up a notice to let everyone know they should not use that sink.</p></div>"],"vi":"Darion Gaines (11:16 sáng): Sonia ơi, bồn rửa ở phòng nghỉ tầng ba bị tắc rồi.\n\nSonia Pinkerton (11:20 sáng): Lại nữa à? Đó là lần thứ hai trong tháng này rồi.\n\nDarion Gaines (11:22 sáng): Lần trước một nhân viên bán hàng của chúng ta đã thông được, nhưng có lẽ lần này chúng ta nên gọi thợ chuyên nghiệp. Tôi có nên liên hệ với ông Green để báo cho ông ấy biết không?\n\nSonia Pinkerton (11:23 sáng): Ông quản lý văn phòng ấy à? Tôi nghĩ tốt nhất là gọi cho trưởng bộ phận bảo trì, Tammy Toska. Cô ấy có thể cử người đến sửa khá nhanh.\n\nDarion Gaines (11:24 sáng): Được. Tôi có thể liên hệ với cô ấy.\n\nSonia Pinkerton (11:25 sáng): Cứ làm đi. Trong lúc đó, tôi sẽ dán một thông báo để mọi người biết là không nên dùng bồn rửa đó.","qs":[{"n":149,"q":"Who most likely is Mr. Green?","qvi":"Ông Green có khả năng là ai nhất?","opts":["A custodian","A plumber","A manager","A sales associate"],"ans":"C","xp":"Câu hỏi suy luận (nhân vật). Darion hỏi \"Should I contact Mr. Green and let him know?\", Sonia đáp lại \"The office manager?\" (Ông quản lý văn phòng ấy à?) → Mr. Green là quản lý → chọn (C). Người phụ trách bảo trì là Tammy Toska, còn nhân viên bán hàng là người đã thông bồn rửa lần trước.\n(A) Nhân viên vệ sinh/tạp vụ\n(B) Thợ sửa ống nước\n(C) Người quản lý\n(D) Nhân viên bán hàng"},{"n":150,"q":"At 11:25 A.M., what does Ms. Pinkerton most likely mean when she writes, \"Go ahead\"?","qvi":"Lúc 11:25 sáng, khi bà Pinkerton viết \"Go ahead\" (Cứ làm đi), bà ấy có ý gì?","opts":["Mr. Gaines may enter the break room.","Mr. Gaines should contact Ms. Toska.","Mr. Gaines should post a notice.","Mr. Gaines can try to repair the sink."],"ans":"B","xp":"Câu hỏi hàm ý. Ngay trước đó Darion viết \"OK. I could reach out to her.\" (Tôi có thể liên hệ với cô ấy — tức Tammy Toska, trưởng bộ phận bảo trì). Sonia trả lời \"Go ahead\" = đồng ý để Darion liên hệ với cô Toska → chọn (B). Việc dán thông báo là do chính Sonia làm (\"I'll put up a notice\") nên (C) sai.\n(A) Ông Gaines có thể vào phòng nghỉ.\n(B) Ông Gaines nên liên hệ với cô Toska.\n(C) Ông Gaines nên dán một thông báo.\n(D) Ông Gaines có thể thử sửa bồn rửa."}]},{"ns":[151,152],"head":"Questions 151-152 refer to the following e-mail.","passages":["<div class=\"hdr\"><p><b>To:</b> Ramdeo Khemradj &lt;rkhemradj@topofthehill.jm&gt;</p><p><b>From:</b> Kerensa Mayne &lt;kmayne@topofthehill.jm&gt;</p><p><b>Date:</b> 17 August</p><p><b>Subject:</b> Information</p><p><b>Attachment:</b> Latest draft</p></div><p>Hi, Ramdeo.</p><p>Please take a look at the latest draft and let me know what you think. I changed the layout—desserts are now on the inside back cover—and provided descriptions of the additional dinner dishes that you and your kitchen staff will be introducing next month.</p><p>I haven't updated the prices yet though, as I haven't decided whether we will need to increase some of them.</p><p>I'm sure you agree with me that the design firm did a great job upgrading the kitchen and making the dining room brighter and more inviting.</p><p>Kerensa</p>"],"vi":"Người nhận: Ramdeo Khemradj <rkhemradj@topofthehill.jm>\nNgười gửi: Kerensa Mayne <kmayne@topofthehill.jm>\nNgày: 17 tháng 8\nTiêu đề: Thông tin\nTệp đính kèm: Bản nháp mới nhất\n\nChào Ramdeo,\n\nAnh hãy xem bản nháp mới nhất và cho tôi biết ý kiến nhé. Tôi đã thay đổi bố cục — các món tráng miệng giờ nằm ở mặt trong bìa sau — và bổ sung phần mô tả các món ăn tối mới mà anh và đội ngũ nhà bếp sẽ giới thiệu vào tháng tới.\n\nTuy nhiên tôi vẫn chưa cập nhật giá, vì tôi chưa quyết định liệu chúng ta có cần tăng giá một số món hay không.\n\nTôi chắc anh cũng đồng ý với tôi rằng công ty thiết kế đã làm rất tốt việc nâng cấp nhà bếp và làm cho phòng ăn sáng sủa, hấp dẫn hơn.\n\nKerensa","qs":[{"n":151,"q":"Who most likely is Mr. Khemradj?","qvi":"Ông Khemradj có khả năng là ai nhất?","opts":["An interior decorator","A restaurant owner","An architect","A head chef"],"ans":"D","xp":"Câu hỏi suy luận (nhân vật). Email gửi cho Ramdeo Khemradj viết: \"the additional dinner dishes that you and your kitchen staff will be introducing next month\" (các món ăn tối mà anh và nhân viên bếp của anh sẽ giới thiệu) → ông ấy quản lý nhân viên bếp và tạo món mới → bếp trưởng → chọn (D). Việc nâng cấp nhà bếp do \"the design firm\" làm, nên (A), (C) sai.\n(A) Nhà trang trí nội thất\n(B) Chủ nhà hàng\n(C) Kiến trúc sư\n(D) Bếp trưởng"},{"n":152,"q":"What most likely is attached to the e-mail?","qvi":"Thứ gì có khả năng được đính kèm theo email nhất?","opts":["A price list","A revised menu","A photograph of food","A lighting plan for a dining room"],"ans":"B","xp":"Câu hỏi suy luận. Tệp đính kèm là \"Latest draft\"; trong đó \"I changed the layout—desserts are now on the inside back cover—and provided descriptions of the additional dinner dishes\" → tài liệu có bìa, có mục tráng miệng, mô tả món ăn → đó là thực đơn đã chỉnh sửa → chọn (B). Giá chưa được cập nhật (\"I haven't updated the prices yet\") nên (A) không phù hợp.\n(A) Một bảng giá\n(B) Một thực đơn đã chỉnh sửa\n(C) Một bức ảnh món ăn\n(D) Một kế hoạch chiếu sáng cho phòng ăn"}]},{"ns":[153,154],"head":"Questions 153-154 refer to the following application form.","passages":["<h3>Page Turner Booksellers</h3><h4>Employment Application Form</h4><p>Date of Application: 1 September</p><h4>PERSONAL DATA</h4><table><tr><td>Name: Arturo Rami</td><td>Address: 10 Beamish Street, Werribee, VIC 3030</td></tr><tr><td>E-mail: arturo.rami@amail.com.au</td><td>Telephone: 03 9555 3744</td></tr></table><h4>EMPLOYMENT DESIRED</h4><table><tr><td>Desired position</td><td colspan=\"3\">Assistant Store Manager</td></tr><tr><td>Available start date</td><td colspan=\"3\">20 September</td></tr><tr><td>Preferred location</td><td>☐ Seaholme</td><td>☒ Werribee</td><td>☐ Port Melbourne</td></tr><tr><td>Preferred status</td><td>☒ Full-time</td><td>☐ Part-time</td><td>☐ Temporary</td></tr></table><h4>EDUCATION</h4><table><tr><th>Educational Institution</th><th>Diploma/Certificate/Degree Earned</th></tr><tr><td>South Bank High School</td><td>High school diploma</td></tr><tr><td>Dymocks University</td><td>Bachelor's degree</td></tr></table><h4>EMPLOYMENT HISTORY</h4><table><tr><th>Employer</th><th>Position</th><th>Duration</th></tr><tr><td>The Garment Barn</td><td>Sales associate</td><td>2 years</td></tr><tr><td>Altona Marketing</td><td>Assistant manager</td><td>3 years</td></tr></table><h4>EXPLANATION OF INTEREST IN THE POSITION</h4><p>I flourish in a fast-paced and demanding work environment, which my most recent employers are known for. I expect the same is true of Page Turner Booksellers, which tends to be quite busy. Moreover, with my bachelor's degree in retail management, I believe I am well suited for the position.</p>"],"vi":"Nhà sách Page Turner\nMẫu đơn xin việc\n\nNgày nộp đơn: 1 tháng 9\n\nTHÔNG TIN CÁ NHÂN\nHọ tên: Arturo Rami — Địa chỉ: 10 Beamish Street, Werribee, VIC 3030\nEmail: arturo.rami@amail.com.au — Điện thoại: 03 9555 3744\n\nCÔNG VIỆC MONG MUỐN\nVị trí mong muốn: Trợ lý quản lý cửa hàng\nNgày có thể bắt đầu: 20 tháng 9\nĐịa điểm mong muốn: ☐ Seaholme ☒ Werribee ☐ Port Melbourne\nHình thức mong muốn: ☒ Toàn thời gian ☐ Bán thời gian ☐ Tạm thời\n\nHỌC VẤN\nTrường Trung học South Bank — Bằng tốt nghiệp trung học\nĐại học Dymocks — Bằng cử nhân\n\nQUÁ TRÌNH LÀM VIỆC\nThe Garment Barn — Nhân viên bán hàng — 2 năm\nAltona Marketing — Trợ lý quản lý — 3 năm\n\nLÝ DO QUAN TÂM ĐẾN VỊ TRÍ\nTôi làm việc tốt nhất trong môi trường nhịp độ nhanh và đòi hỏi cao, điều mà những nơi tôi làm việc gần đây nhất đều nổi tiếng. Tôi nghĩ Nhà sách Page Turner, nơi thường khá đông khách, cũng như vậy. Hơn nữa, với bằng cử nhân quản lý bán lẻ, tôi tin mình rất phù hợp với vị trí này.","qs":[{"n":153,"q":"What is suggested about Page Turner Booksellers?","qvi":"Điều gì được ngụ ý về Nhà sách Page Turner?","opts":["It has multiple locations.","It is near South Bank High School.","It will open a new store on September 20.","It currently has only full-time positions available."],"ans":"A","xp":"Câu hỏi suy luận. Trong mục \"Preferred location\" có ba lựa chọn: \"Seaholme\", \"Werribee\", \"Port Melbourne\" → nhà sách có nhiều chi nhánh → chọn (A). Ngày 20/9 chỉ là ngày ứng viên có thể bắt đầu làm (\"Available start date\"), còn mẫu đơn có cả lựa chọn Part-time/Temporary nên (C), (D) sai.\n(A) Nhà sách có nhiều chi nhánh.\n(B) Nhà sách ở gần Trường Trung học South Bank.\n(C) Nhà sách sẽ mở cửa hàng mới vào ngày 20 tháng 9.\n(D) Hiện nhà sách chỉ tuyển vị trí toàn thời gian."},{"n":154,"q":"What is NOT indicated about Mr. Rami?","qvi":"Điều gì KHÔNG được nêu về anh Rami?","opts":["He studied retail management.","He recently moved to Werribee.","He has experience working in sales.","He prefers working in a busy setting."],"ans":"B","xp":"Câu hỏi NOT. (A) có: \"my bachelor's degree in retail management\". (C) có: từng làm \"Sales associate\" ở The Garment Barn 2 năm. (D) có: \"I flourish in a fast-paced and demanding work environment\" và nhà sách \"tends to be quite busy\". Đơn chỉ cho biết anh sống ở Werribee, không nói anh mới chuyển đến đó → chọn (B).\n(A) Anh ấy đã học ngành quản lý bán lẻ.\n(B) Anh ấy mới chuyển đến Werribee.\n(C) Anh ấy có kinh nghiệm làm bán hàng.\n(D) Anh ấy thích làm việc ở môi trường bận rộn."}]},{"ns":[155,157],"head":"Questions 155-157 refer to the following advertisement.","passages":["<h3>Donovan Auto Lube</h3><p>Donavan Auto Lube (DAL) is the first choice for residents of Knebworth who want to keep their cars running smoothly. We provide oil changes, tyre rotations, and routine inspections. Our team of certified auto technicians can service all vehicle makes and models. Customers may schedule an appointment or simply drive up to any DAL location during our business hours of 8:00 A.M. to 8:00 P.M., Monday to Saturday, and 11:00 A.M. to 5:00 P.M. on Sunday.</p><p>This summer, DAL offers a special promotion: a 5-quart oil change, oil filter replacement, and comprehensive maintenance check for just £15. This offer is available at all DAL locations throughout Herfordshire but may not be combined with any other promotional offer. The quoted price does not include value-added tax and does not cover any additional maintenance, repairs, and parts that a vehicle inspection may call for.</p><p>Visit DAL for all your automotive needs.</p>"],"vi":"Donovan Auto Lube\n\nDonavan Auto Lube (DAL) là lựa chọn hàng đầu của cư dân Knebworth muốn giữ cho xe của mình vận hành trơn tru. Chúng tôi cung cấp dịch vụ thay dầu, đảo lốp và kiểm tra định kỳ. Đội ngũ kỹ thuật viên ô tô có chứng chỉ của chúng tôi có thể bảo dưỡng mọi hãng xe và mẫu xe. Khách hàng có thể đặt lịch hẹn hoặc chỉ cần lái xe đến bất kỳ cơ sở DAL nào trong giờ làm việc từ 8:00 sáng đến 8:00 tối, thứ Hai đến thứ Bảy, và từ 11:00 sáng đến 5:00 chiều vào Chủ nhật.\n\nMùa hè này, DAL có chương trình khuyến mãi đặc biệt: thay 5 lít (quart) dầu, thay lọc dầu và kiểm tra bảo dưỡng toàn diện chỉ với 15 bảng Anh. Ưu đãi áp dụng tại tất cả các cơ sở DAL trên khắp Herfordshire nhưng không được kết hợp với bất kỳ ưu đãi khuyến mãi nào khác. Mức giá trên chưa bao gồm thuế giá trị gia tăng và không bao gồm bất kỳ khoản bảo dưỡng, sửa chữa và phụ tùng bổ sung nào mà quá trình kiểm tra xe có thể yêu cầu.\n\nHãy đến DAL cho mọi nhu cầu về ô tô của bạn.","qs":[{"n":155,"q":"The word \"running\" in paragraph 1, line 2, is closest in meaning to","qvi":"Từ \"running\" ở đoạn 1, dòng 2 gần nghĩa nhất với","opts":["flowing","speeding","controlling","functioning"],"ans":"D","xp":"Câu hỏi đồng nghĩa. \"keep their cars running smoothly\" = giữ cho xe vận hành/hoạt động trơn tru. 'running' ở đây nghĩa là 'hoạt động, vận hành' ≈ 'functioning' → chọn (D). 'flowing' (chảy) dùng cho chất lỏng, 'speeding' (chạy quá tốc độ) không hợp nghĩa.\n(A) chảy\n(B) chạy quá tốc độ\n(C) điều khiển\n(D) hoạt động, vận hành"},{"n":156,"q":"When can a customer NOT be served at Donovan Auto Lube?","qvi":"Khi nào khách hàng KHÔNG thể được phục vụ tại Donovan Auto Lube?","opts":["On Monday at 8:00 A.M.","On Wednesday at 6:00 P.M.","On Saturday at 4:00 P.M.","On Sunday at 6:00 P.M."],"ans":"D","xp":"Câu hỏi NOT (chi tiết). Giờ làm việc: \"8:00 A.M. to 8:00 P.M., Monday to Saturday, and 11:00 A.M. to 5:00 P.M. on Sunday\". (A) thứ Hai 8 giờ sáng, (B) thứ Tư 6 giờ tối, (C) thứ Bảy 4 giờ chiều đều nằm trong giờ mở cửa. Chủ nhật chỉ mở đến 5 giờ chiều nên 6 giờ tối Chủ nhật không được phục vụ → chọn (D).\n(A) Thứ Hai lúc 8:00 sáng\n(B) Thứ Tư lúc 6:00 tối\n(C) Thứ Bảy lúc 4:00 chiều\n(D) Chủ nhật lúc 6:00 tối"},{"n":157,"q":"What is true about the promotional offer?","qvi":"Điều gì đúng về chương trình khuyến mãi?","opts":["It is not valid outside of Knebworth.","It includes replacement of a filter.","It does not apply to a maintenance check.","It includes all taxes."],"ans":"B","xp":"Câu hỏi chi tiết (thông tin đúng). Khuyến mãi gồm \"a 5-quart oil change, oil filter replacement, and comprehensive maintenance check\" → có thay lọc dầu → chọn (B). (A) sai vì áp dụng \"at all DAL locations throughout Herfordshire\"; (C) sai vì có \"comprehensive maintenance check\"; (D) sai vì \"does not include value-added tax\".\n(A) Không áp dụng ngoài Knebworth.\n(B) Bao gồm việc thay một bộ lọc.\n(C) Không áp dụng cho việc kiểm tra bảo dưỡng.\n(D) Đã bao gồm tất cả các loại thuế."}]},{"ns":[158,160],"head":"Questions 158-160 refer to the following biography.","passages":["<p>Kasem Ngam is a renowned speaker and author from Nonthaburi province in Thailand. <span class=\"pos\">[1]</span>. Immediately upon graduating from Sangsuwan University in Bangkok, he joined Chanthara Gas &amp; Electric (CG&amp;E). Over a period of 25 years, he made a name for himself as one of CG&amp;E's most dedicated and respected employees, even gaining national and international recognition. <span class=\"pos\">[2]</span>.</p><p>Mr. Ngam currently runs a consulting firm that he started four years ago to help businesses develop innovative new technologies to power the modern world. <span class=\"pos\">[3]</span>. He is the author of numerous articles on a variety of topics, including solar panels and hydrogen-powered vehicles. <span class=\"pos\">[4]</span>. His honors include a Pax Innovation Award for <i>The Future's Fuel</i>, his book on biofuels, which has been translated into several languages. His forthcoming book, <i>Pricing Our Power: Funding the New Green Energy</i>, will be published in May.</p>"],"vi":"Kasem Ngam là một diễn giả và tác giả nổi tiếng đến từ tỉnh Nonthaburi, Thái Lan. Ngay sau khi tốt nghiệp Đại học Sangsuwan ở Bangkok, ông gia nhập công ty Chanthara Gas & Electric (CG&E). Trong suốt 25 năm, ông đã tạo dựng tên tuổi như một trong những nhân viên tận tụy và được kính trọng nhất của CG&E, thậm chí còn được công nhận ở tầm quốc gia và quốc tế.\n\nHiện ông Ngam điều hành một công ty tư vấn do ông thành lập cách đây bốn năm nhằm giúp các doanh nghiệp phát triển những công nghệ mới mang tính đổi mới để cung cấp năng lượng cho thế giới hiện đại. Ông là tác giả của nhiều bài viết về nhiều chủ đề, bao gồm tấm pin mặt trời và phương tiện chạy bằng hydro. Các giải thưởng của ông bao gồm Giải thưởng Đổi mới Pax cho cuốn The Future's Fuel, cuốn sách của ông về nhiên liệu sinh học, đã được dịch ra nhiều thứ tiếng. Cuốn sách sắp ra mắt của ông, Pricing Our Power: Funding the New Green Energy, sẽ được xuất bản vào tháng Năm.","qs":[{"n":158,"q":"What industry does Mr. Ngam most likely work in?","qvi":"Ông Ngam có khả năng làm việc trong ngành nào nhất?","opts":["Energy","Travel","Finance","Journalism"],"ans":"A","xp":"Câu hỏi suy luận. Ông làm 25 năm ở \"Chanthara Gas & Electric\" (công ty khí đốt và điện), hiện điều hành công ty tư vấn giúp phát triển công nghệ \"to power the modern world\", viết về \"solar panels and hydrogen-powered vehicles\", sách về \"biofuels\" và \"New Green Energy\" → ngành năng lượng → chọn (A).\n(A) Năng lượng\n(B) Du lịch\n(C) Tài chính\n(D) Báo chí"},{"n":159,"q":"What is indicated about Mr. Ngam?","qvi":"Điều gì được nêu về ông Ngam?","opts":["He is writing his first book.","He knows several languages.","He operates his own business.","He is a recent university graduate."],"ans":"C","xp":"Câu hỏi chi tiết. \"Mr. Ngam currently runs a consulting firm that he started four years ago\" (hiện điều hành công ty tư vấn do ông lập ra) → 'runs a firm he started' ≈ 'operates his own business' → chọn (C). (A) sai: ông đã có sách The Future's Fuel; (B) sai: sách của ông được dịch ra nhiều thứ tiếng, không phải ông biết nhiều thứ tiếng; (D) sai: ông đã làm việc 25 năm.\n(A) Ông đang viết cuốn sách đầu tiên.\n(B) Ông biết nhiều ngôn ngữ.\n(C) Ông điều hành doanh nghiệp riêng.\n(D) Ông mới tốt nghiệp đại học."},{"n":160,"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n\"The last position he held at the company was director of research and development.\"","qvi":"Câu sau phù hợp nhất với vị trí nào trong các vị trí [1], [2], [3], [4]?\n\"Vị trí cuối cùng ông đảm nhận tại công ty là giám đốc nghiên cứu và phát triển.\"","opts":["[1]","[2]","[3]","[4]"],"ans":"B","xp":"Câu hỏi điền câu. Câu cần điền nói về \"the company\" và chức vụ cuối cùng ông giữ ở đó → phải đứng sau đoạn kể về quá trình làm việc tại CG&E. Vị trí [2] nằm ngay sau \"Over a period of 25 years, he made a name for himself as one of CG&E's most dedicated and respected employees…\" → 'the company' chính là CG&E, và câu này khép lại phần sự nghiệp ở CG&E trước khi đoạn 2 chuyển sang công việc hiện tại → chọn (B).\n(A) [1]\n(B) [2]\n(C) [3]\n(D) [4]"}]},{"ns":[161,163],"head":"Questions 161-163 refer to the following article.","passages":["<h3><i>Jobs Coming to Willettville</i></h3><p>WILLETTVILLE (March 8)—Tanney's Discount Mart (TDM) announced today that it will hold a job fair in Willettville later this month. The company, headquartered in nearby Lyter City, is looking to fill 300 positions at its new distribution center, set to open here next month. In addition to seeking technicians and supervisors, the company wants to fill positions in the processing, stock inspection, and maintenance departments.</p><p>\"TDM's distribution centers use modern automated systems, which creates a big need for qualified technical staff in particular,\" Kent Siler, TDM's president, said in a press release announcing the job fair.</p><p>The event will be held from 9:30 A.M. to 6:30 P.M. on Thursday, March 20, in the ballroom of the Twin Ridges Hotel. Details can be found by visiting tdm.com/careers.</p><p>\"This recruiting event will help us find the staff we need to meet the anticipated growth in demand for our products,\" said Mr. Siler. \"TDM continues to expand its position in discount retail. So far this year, we have opened three stores, and we have five more slated to open by the end of next year.\" Mr. Siler noted, moreover, that TDM offers competitive wages for full-time and part-time employment.</p>"],"vi":"Việc làm sắp đến với Willettville\n\nWILLETTVILLE (8 tháng 3) — Tanney's Discount Mart (TDM) hôm nay thông báo sẽ tổ chức một hội chợ việc làm tại Willettville vào cuối tháng này. Công ty, có trụ sở chính tại thành phố Lyter gần đó, đang tìm cách tuyển 300 vị trí cho trung tâm phân phối mới, dự kiến khai trương tại đây vào tháng tới. Ngoài việc tìm kiếm kỹ thuật viên và giám sát viên, công ty còn muốn tuyển người cho các bộ phận chế biến/xử lý hàng, kiểm tra hàng tồn kho và bảo trì.\n\n\"Các trung tâm phân phối của TDM sử dụng hệ thống tự động hóa hiện đại, điều này tạo ra nhu cầu lớn đặc biệt về nhân viên kỹ thuật có trình độ,\" ông Kent Siler, chủ tịch TDM, cho biết trong thông cáo báo chí công bố hội chợ việc làm.\n\nSự kiện sẽ được tổ chức từ 9:30 sáng đến 6:30 tối thứ Năm, ngày 20 tháng 3, tại phòng khiêu vũ của khách sạn Twin Ridges. Thông tin chi tiết có thể xem tại tdm.com/careers.\n\n\"Sự kiện tuyển dụng này sẽ giúp chúng tôi tìm được đội ngũ nhân viên cần thiết để đáp ứng sự tăng trưởng dự kiến về nhu cầu đối với sản phẩm của chúng tôi,\" ông Siler nói. \"TDM tiếp tục mở rộng vị thế trong lĩnh vực bán lẻ giá rẻ. Từ đầu năm đến nay, chúng tôi đã mở ba cửa hàng, và có thêm năm cửa hàng nữa dự kiến khai trương trước cuối năm sau.\" Ngoài ra, ông Siler cho biết TDM trả mức lương cạnh tranh cho cả công việc toàn thời gian và bán thời gian.","qs":[{"n":161,"q":"What is stated about TDM's new distribution center?","qvi":"Điều gì được nêu về trung tâm phân phối mới của TDM?","opts":["It is the company's first distribution center to use automated systems.","It is the largest facility the company has built.","It is scheduled to open in April.","It was designed by an architectural firm in Willettville."],"ans":"C","xp":"Câu hỏi chi tiết. Bài báo đề ngày \"March 8\" và viết trung tâm phân phối mới \"set to open here next month\" (dự kiến mở vào tháng sau) → tháng sau tháng 3 là tháng 4 → chọn (C). (A) sai vì bài nói các trung tâm phân phối của TDM (số nhiều) đều dùng hệ thống tự động; (B), (D) không được nhắc đến.\n(A) Đây là trung tâm phân phối đầu tiên của công ty dùng hệ thống tự động.\n(B) Đây là cơ sở lớn nhất công ty từng xây.\n(C) Trung tâm dự kiến khai trương vào tháng 4.\n(D) Trung tâm được một công ty kiến trúc ở Willettville thiết kế."},{"n":162,"q":"What is NOT mentioned about the job fair?","qvi":"Điều gì KHÔNG được đề cập về hội chợ việc làm?","opts":["The kinds of jobs offered","The day and date it will be held","The types of refreshments served","The source for detailed information"],"ans":"C","xp":"Câu hỏi NOT. (A) có: \"technicians and supervisors… processing, stock inspection, and maintenance departments\". (B) có: \"on Thursday, March 20\". (D) có: \"Details can be found by visiting tdm.com/careers\". Bài không hề nói về đồ ăn nhẹ/đồ uống → chọn (C).\n(A) Các loại công việc được tuyển\n(B) Thứ và ngày tổ chức\n(C) Các loại đồ ăn nhẹ được phục vụ\n(D) Nguồn để xem thông tin chi tiết"},{"n":163,"q":"What does Mr. Siler indicate about TDM?","qvi":"Ông Siler cho biết điều gì về TDM?","opts":["It is a growing business.","It sponsors an annual job fair.","It is staffed mostly by part-time workers.","It relies heavily on online sales."],"ans":"A","xp":"Câu hỏi chi tiết. Ông Siler nói: \"TDM continues to expand its position in discount retail. So far this year, we have opened three stores, and we have five more slated to open\" và nhắc đến \"the anticipated growth in demand\" → TDM là doanh nghiệp đang phát triển → chọn (A). 'expand', 'opened three stores' ≈ 'growing business'. (C) sai vì chỉ nói lương cạnh tranh cho cả toàn thời gian và bán thời gian.\n(A) Đây là một doanh nghiệp đang phát triển.\n(B) Công ty tài trợ một hội chợ việc làm hằng năm.\n(C) Nhân viên của công ty chủ yếu làm bán thời gian.\n(D) Công ty phụ thuộc nhiều vào bán hàng trực tuyến."}]},{"ns":[164,167],"head":"Questions 164-167 refer to the following online chat discussion.","passages":["<div class=\"msg\"><p><b>Rashaan Little (5:40 P.M.)</b></p><p>Hi, Amanda and Desmond. Earlier today I learned that the town has hired our company to demolish the lighthouse.</p></div><div class=\"msg\"><p><b>Amanda Richards (5:43 P.M.)</b></p><p>So did I. I have mixed feelings about taking down that structure, though.</p></div><div class=\"msg\"><p><b>Desmond Williams (5:43 P.M.)</b></p><p>This is the first time that I'm learning about that. I was out of the office all day today.</p></div><div class=\"msg\"><p><b>Rashaan Little (5:44 P.M.)</b></p><p>How so, Amanda?</p></div><div class=\"msg\"><p><b>Amanda Richards (5:46 P.M.)</b></p><p>Well, given that business has been quite slow lately, our company needs the work. Then again, the lighthouse has historic value: it has been a major landmark of Burlingate for 100 years.</p></div><div class=\"msg\"><p><b>Rashaan Little (5:48 P.M.)</b></p><p>I realize that. But the company can't afford to pass up this opportunity for the reason you mentioned. Besides, lighthouses have largely become outdated.</p></div><div class=\"msg\"><p><b>Desmond Williams (5:49 P.M.)</b></p><p>Not really. There's always a need for ships to get warnings about dangerous locations. Lighthouses have served that function for years.</p></div><div class=\"msg\"><p><b>Rashaan Little (5:51 P.M.)</b></p><p>True, but modern technological equipment exists now that simplifies navigation and increasingly makes lighthouses a thing of the past. Anyway, let's meet tomorrow at 10:00 A.M. to discuss how we'll carry out this job.</p></div>"],"vi":"Rashaan Little (5:40 chiều): Chào Amanda và Desmond. Sáng nay tôi được biết thị trấn đã thuê công ty chúng ta phá dỡ ngọn hải đăng.\n\nAmanda Richards (5:43 chiều): Tôi cũng nghe vậy. Nhưng tôi có cảm xúc lẫn lộn về việc phá bỏ công trình đó.\n\nDesmond Williams (5:43 chiều): Đây là lần đầu tôi nghe chuyện này. Hôm nay tôi ra ngoài văn phòng cả ngày.\n\nRashaan Little (5:44 chiều): Sao vậy, Amanda?\n\nAmanda Richards (5:46 chiều): À, vì dạo gần đây công việc kinh doanh khá ế ẩm nên công ty chúng ta cần hợp đồng này. Nhưng mặt khác, ngọn hải đăng có giá trị lịch sử: nó đã là một địa danh quan trọng của Burlingate suốt 100 năm.\n\nRashaan Little (5:48 chiều): Tôi hiểu điều đó. Nhưng công ty không thể bỏ lỡ cơ hội này vì lý do chị vừa nêu. Hơn nữa, hải đăng phần lớn đã lỗi thời rồi.\n\nDesmond Williams (5:49 chiều): Không hẳn. Tàu thuyền luôn cần được cảnh báo về những khu vực nguy hiểm. Hải đăng đã đảm nhận chức năng đó trong nhiều năm.\n\nRashaan Little (5:51 chiều): Đúng, nhưng giờ đã có thiết bị công nghệ hiện đại giúp việc định hướng dễ dàng hơn và ngày càng khiến hải đăng trở thành dĩ vãng. Dù sao thì, chúng ta hãy họp lúc 10 giờ sáng mai để bàn cách thực hiện công việc này.","qs":[{"n":164,"q":"In what type of business do the writers most likely work?","qvi":"Những người viết có khả năng làm việc trong loại hình kinh doanh nào nhất?","opts":["Building demolition","Shipping technology","Corporate accounting","Historical preservation"],"ans":"A","xp":"Câu hỏi suy luận. Rashaan viết: \"the town has hired our company to demolish the lighthouse\" (thị trấn đã thuê công ty chúng ta phá dỡ ngọn hải đăng) và cuối cùng hẹn họp \"to discuss how we'll carry out this job\" → công ty làm dịch vụ phá dỡ công trình → chọn (A).\n(A) Phá dỡ công trình\n(B) Công nghệ hàng hải\n(C) Kế toán doanh nghiệp\n(D) Bảo tồn di tích lịch sử"},{"n":165,"q":"What is indicated about the company the writers work for?","qvi":"Điều gì được nêu về công ty mà những người viết đang làm việc?","opts":["It recently purchased ultramodern equipment.","It has experienced a decline in business.","It is regularly hired by the town council.","It has been in business for 100 years."],"ans":"B","xp":"Câu hỏi chi tiết. Amanda viết: \"given that business has been quite slow lately, our company needs the work\" (dạo này kinh doanh khá chậm) → công ty đang gặp sụt giảm kinh doanh → chọn (B). 'business has been slow' ≈ 'a decline in business'. (D) sai: 100 năm là tuổi của ngọn hải đăng; (A): thiết bị hiện đại là thiết bị định hướng hàng hải, không phải công ty mua.\n(A) Công ty vừa mua thiết bị cực kỳ hiện đại.\n(B) Công ty đã bị sụt giảm kinh doanh.\n(C) Công ty thường xuyên được hội đồng thị trấn thuê.\n(D) Công ty đã hoạt động được 100 năm."},{"n":166,"q":"At 5:48 P.M., what does Mr. Little most likely mean when he writes, \"I realize that\"?","qvi":"Lúc 5:48 chiều, khi ông Little viết \"I realize that\" (Tôi hiểu điều đó), ông ấy có ý gì?","opts":["He knows why Mr. Williams had been absent.","He recognizes the significance of the lighthouse for the town.","He understands how important the company is for the town.","He is aware that Ms. Richards knows much about the town's history."],"ans":"B","xp":"Câu hỏi hàm ý. Ngay trước đó Amanda viết: \"the lighthouse has historic value: it has been a major landmark of Burlingate for 100 years\". Ông Little đáp \"I realize that. But the company can't afford to pass up this opportunity…\" → ông thừa nhận ngọn hải đăng có ý nghĩa quan trọng với thị trấn, nhưng vẫn muốn nhận việc → chọn (B).\n(A) Ông biết lý do ông Williams vắng mặt.\n(B) Ông nhận ra tầm quan trọng của ngọn hải đăng đối với thị trấn.\n(C) Ông hiểu công ty quan trọng thế nào đối với thị trấn.\n(D) Ông biết rằng bà Richards hiểu rõ lịch sử thị trấn."},{"n":167,"q":"What will the writers most likely do tomorrow morning?","qvi":"Những người viết có khả năng sẽ làm gì vào sáng mai?","opts":["Advertise new job openings","Attend a town council meeting","Go on a tour of the lighthouse","Start planning for an upcoming project"],"ans":"D","xp":"Câu hỏi suy luận (việc sắp làm). Tin nhắn cuối: \"let's meet tomorrow at 10:00 A.M. to discuss how we'll carry out this job\" (họp lúc 10 giờ sáng mai để bàn cách thực hiện công việc này) → bắt đầu lên kế hoạch cho dự án sắp tới → chọn (D). 'discuss how we'll carry out this job' ≈ 'start planning for an upcoming project'.\n(A) Đăng tin tuyển dụng mới\n(B) Tham dự cuộc họp hội đồng thị trấn\n(C) Đi tham quan ngọn hải đăng\n(D) Bắt đầu lên kế hoạch cho một dự án sắp tới"}]},{"ns":[168,171],"head":"Questions 168-171 refer to the following brochure.","passages":["<h3>Contempo Spaces<br>Window Treatment Package</h3><p>If you are considering redecorating the windows of your living room, dining room, or bedroom, Contempo Spaces has the perfect treatment design package for you. <span class=\"pos\">[1]</span>. We will help you put together the right combination of shades, panels, drapes, and valances—all perfectly tailored to fit your windows.</p><p>Here's how it works:</p><ul><li>First, one of our style representatives will come to your home and measure and photograph the windows in each room.</li><li>During that visit, our representative will show you samples of the many styles of fabrics and hardware available in our product line. <span class=\"pos\">[2]</span>. Or, you can opt to visit our showroom after the home visit and make your selections there.</li><li>One or two days after you've made your window treatment decisions, we will send you an invoice, listing the cost for materials, installation, and labor. The quoted price is valid for thirty days. Upon receipt of payment, materials will be ordered. It usually takes from seven to fourteen days for them to reach our store. <span class=\"pos\">[3]</span>.</li><li>Finally, we will contact you to schedule the date and time of installation. <span class=\"pos\">[4]</span>. Depending on the size of the project, installation can take two to eight hours.</li></ul>"],"vi":"Contempo Spaces\nGói trang trí cửa sổ\n\nNếu bạn đang cân nhắc trang trí lại cửa sổ phòng khách, phòng ăn hoặc phòng ngủ, Contempo Spaces có gói thiết kế trang trí hoàn hảo dành cho bạn. Chúng tôi sẽ giúp bạn phối hợp đúng các loại mành, tấm rèm, rèm buông và diềm rèm — tất cả đều được may đo hoàn hảo cho vừa cửa sổ của bạn.\n\nQuy trình như sau:\n\n• Đầu tiên, một chuyên viên tư vấn phong cách của chúng tôi sẽ đến nhà bạn để đo đạc và chụp ảnh cửa sổ ở từng phòng.\n\n• Trong buổi đến nhà đó, chuyên viên sẽ cho bạn xem mẫu của rất nhiều kiểu vải và phụ kiện có trong dòng sản phẩm của chúng tôi. Hoặc bạn có thể chọn đến phòng trưng bày của chúng tôi sau buổi đến nhà và lựa chọn tại đó.\n\n• Một hoặc hai ngày sau khi bạn quyết định phương án trang trí cửa sổ, chúng tôi sẽ gửi cho bạn hóa đơn liệt kê chi phí vật liệu, lắp đặt và nhân công. Mức giá báo có hiệu lực trong ba mươi ngày. Khi nhận được thanh toán, chúng tôi sẽ đặt mua vật liệu. Thông thường mất từ bảy đến mười bốn ngày để vật liệu về đến cửa hàng.\n\n• Cuối cùng, chúng tôi sẽ liên hệ với bạn để hẹn ngày giờ lắp đặt. Tùy theo quy mô công trình, việc lắp đặt có thể mất từ hai đến tám tiếng.","qs":[{"n":168,"q":"What is the purpose of the brochure?","qvi":"Mục đích của tờ quảng cáo là gì?","opts":["To explain a new policy","To describe a popular product","To advertise a special discount","To present a standard process"],"ans":"D","xp":"Câu hỏi mục đích. Sau phần giới thiệu, tờ quảng cáo viết \"Here's how it works:\" rồi liệt kê từng bước \"First… During that visit… One or two days after… Finally…\" → trình bày quy trình chuẩn khi sử dụng gói dịch vụ → chọn (D). Không có chính sách mới hay giảm giá nào được nêu.\n(A) Giải thích một chính sách mới\n(B) Mô tả một sản phẩm được ưa chuộng\n(C) Quảng cáo một chương trình giảm giá đặc biệt\n(D) Trình bày một quy trình chuẩn"},{"n":169,"q":"After how many days might the total cost listed in an invoice change?","qvi":"Sau bao nhiêu ngày thì tổng chi phí ghi trên hóa đơn có thể thay đổi?","opts":["Two","Seven","Fourteen","Thirty"],"ans":"D","xp":"Câu hỏi suy luận (chi tiết). Về hóa đơn: \"The quoted price is valid for thirty days.\" (giá báo có hiệu lực 30 ngày) → sau 30 ngày giá có thể thay đổi → chọn (D). 'Two' là số ngày gửi hóa đơn sau khi quyết định; 'seven to fourteen' là thời gian vật liệu về cửa hàng.\n(A) Hai\n(B) Bảy\n(C) Mười bốn\n(D) Ba mươi"},{"n":170,"q":"What is indicated in the brochure about installation?","qvi":"Tờ quảng cáo cho biết điều gì về việc lắp đặt?","opts":["It is not available for all window treatments.","It is the responsibility of the customer.","It takes no more than eight hours to complete.","It is subcontracted to an outside vendor."],"ans":"C","xp":"Câu hỏi chi tiết. \"Depending on the size of the project, installation can take two to eight hours.\" → lắp đặt mất tối đa tám tiếng → chọn (C). 'two to eight hours' ≈ 'no more than eight hours'. (B), (D) sai vì chính công ty liên hệ hẹn lịch lắp đặt và chi phí lắp đặt có trong hóa đơn.\n(A) Không áp dụng cho mọi loại trang trí cửa sổ.\n(B) Đó là trách nhiệm của khách hàng.\n(C) Mất không quá tám tiếng để hoàn thành.\n(D) Được giao thầu lại cho một nhà cung cấp bên ngoài."},{"n":171,"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n\"Our entire style collection can be viewed on our Web site.\"","qvi":"Câu sau phù hợp nhất với vị trí nào trong các vị trí [1], [2], [3], [4]?\n\"Toàn bộ bộ sưu tập kiểu dáng của chúng tôi có thể được xem trên trang web.\"","opts":["[1]","[2]","[3]","[4]"],"ans":"B","xp":"Câu hỏi điền câu. Câu cần điền nói về một cách khác để xem các kiểu dáng (trên trang web). Vị trí [2] nằm ngay sau \"our representative will show you samples of the many styles of fabrics and hardware available in our product line\" và ngay trước \"Or, you can opt to visit our showroom…\" → các cách xem mẫu được liệt kê liền mạch: xem mẫu do chuyên viên mang đến → xem trên web → hoặc đến phòng trưng bày → chọn (B).\n(A) [1]\n(B) [2]\n(C) [3]\n(D) [4]"}]},{"ns":[172,175],"head":"Questions 172-175 refer to the following e-mail.","passages":["<div class=\"hdr\"><p><b>To:</b> Morgan Tebele &lt;mtebele@newsom.com.na&gt;</p><p><b>From:</b> Esme Mukaya &lt;emukaya@skyleopard.com.na&gt;</p><p><b>Date:</b> 21 August</p><p><b>Subject:</b> Offer</p></div><p>Dear Mr. Tebele,</p><p>Whether you are refinancing a loan, training personnel, or marketing your financial services online, having fast, reliable Internet access is essential for bank managers like you. Sky Leopard Communications delivers just that, thanks to its highly advanced network and dedicated workforce.</p><p>In fact, a recent survey conducted by the Namibian Association of Small-Business Owners (NASO) revealed that 75 percent of its members prefer our services over those of our competitors.</p><p>The reason: in addition to our state-of-the-art Internet infrastructure and our outstanding pool of technicians, we offer premium Internet connectivity through our High-Velocity Internet Access (HIVIA) service plan. HIVIA provides download and upload speeds that are three times faster than those of our closest competitor.</p><p>Sky Leopard Communications offers new customers and those using one of our other service plans the opportunity to try HIVIA for free for 30 days. To subscribe, visit us at www.skyleopard.com.na or call us at 061-987-555. If at any time during the one-month trial period you are not satisfied with this plan, you can unsubscribe from the service at no cost to you.</p><p>Sincerely,</p><p>Esme Mukaya, Sales</p>"],"vi":"Người nhận: Morgan Tebele <mtebele@newsom.com.na>\nNgười gửi: Esme Mukaya <emukaya@skyleopard.com.na>\nNgày: 21 tháng 8\nTiêu đề: Ưu đãi\n\nKính gửi ông Tebele,\n\nDù ông đang tái cấp vốn một khoản vay, đào tạo nhân sự hay tiếp thị các dịch vụ tài chính của mình trên mạng, thì việc có kết nối Internet nhanh và ổn định là điều thiết yếu đối với những nhà quản lý ngân hàng như ông. Sky Leopard Communications mang đến chính điều đó, nhờ mạng lưới rất tiên tiến và đội ngũ nhân viên tận tâm.\n\nThực tế, một cuộc khảo sát gần đây do Hiệp hội Chủ doanh nghiệp nhỏ Namibia (NASO) thực hiện cho thấy 75% hội viên của hiệp hội ưa chuộng dịch vụ của chúng tôi hơn dịch vụ của các đối thủ cạnh tranh.\n\nLý do là: ngoài cơ sở hạ tầng Internet hiện đại bậc nhất và đội ngũ kỹ thuật viên xuất sắc, chúng tôi còn cung cấp kết nối Internet cao cấp thông qua gói dịch vụ Truy cập Internet Tốc độ cao (HIVIA). HIVIA cung cấp tốc độ tải xuống và tải lên nhanh gấp ba lần so với đối thủ cạnh tranh gần nhất của chúng tôi.\n\nSky Leopard Communications dành cho khách hàng mới và những khách hàng đang dùng một trong các gói dịch vụ khác của chúng tôi cơ hội dùng thử HIVIA miễn phí trong 30 ngày. Để đăng ký, hãy truy cập www.skyleopard.com.na hoặc gọi cho chúng tôi theo số 061-987-555. Nếu vào bất kỳ lúc nào trong thời gian dùng thử một tháng mà ông không hài lòng với gói này, ông có thể hủy đăng ký dịch vụ mà không mất phí.\n\nTrân trọng,\n\nEsme Mukaya, Bộ phận Kinh doanh","qs":[{"n":172,"q":"What business is Mr. Tebele most likely in?","qvi":"Ông Tebele có khả năng làm trong lĩnh vực kinh doanh nào nhất?","opts":["Web design","Hospitality","Marketing","Banking"],"ans":"D","xp":"Câu hỏi suy luận. Email gửi ông Tebele viết: \"Whether you are refinancing a loan, training personnel, or marketing your financial services online, having fast, reliable Internet access is essential for bank managers like you.\" → ông là quản lý ngân hàng → chọn (D). 'marketing' chỉ là một hoạt động ông có thể làm, nên (C) là bẫy.\n(A) Thiết kế web\n(B) Nhà hàng – khách sạn\n(C) Tiếp thị\n(D) Ngân hàng"},{"n":173,"q":"What is indicated about Sky Leopard Communications?","qvi":"Điều gì được nêu về Sky Leopard Communications?","opts":["It offers a discount to NASO members.","It is popular with small-business owners.","It recently launched a new service plan.","It is looking to increase its workforce."],"ans":"B","xp":"Câu hỏi chi tiết. \"a recent survey conducted by the Namibian Association of Small-Business Owners (NASO) revealed that 75 percent of its members prefer our services over those of our competitors\" → 75% chủ doanh nghiệp nhỏ trong hiệp hội thích dịch vụ của công ty → được giới chủ doanh nghiệp nhỏ ưa chuộng → chọn (B). Email không nói giảm giá cho hội viên NASO, không nói gói HIVIA mới ra mắt hay tuyển thêm người.\n(A) Công ty giảm giá cho hội viên NASO.\n(B) Công ty được các chủ doanh nghiệp nhỏ ưa chuộng.\n(C) Công ty vừa ra mắt một gói dịch vụ mới.\n(D) Công ty đang muốn tăng thêm nhân lực."},{"n":174,"q":"The word \"outstanding\" in paragraph 3, line 1, is closest in meaning to","qvi":"Từ \"outstanding\" ở đoạn 3, dòng 1 gần nghĩa nhất với","opts":["diverse","available","excellent","remaining"],"ans":"C","xp":"Câu hỏi đồng nghĩa. \"our state-of-the-art Internet infrastructure and our outstanding pool of technicians\" — 'outstanding' đi cùng 'state-of-the-art' để khen ngợi đội ngũ kỹ thuật viên → nghĩa là 'xuất sắc, nổi bật' ≈ 'excellent' → chọn (C). Lưu ý 'outstanding' còn có nghĩa 'còn tồn đọng, chưa thanh toán' (≈ remaining), nhưng không hợp ngữ cảnh ở đây.\n(A) đa dạng\n(B) sẵn có\n(C) xuất sắc\n(D) còn lại"},{"n":175,"q":"What can be concluded about the HIVIA service plan?","qvi":"Có thể kết luận điều gì về gói dịch vụ HIVIA?","opts":["It is more expensive than other plans.","It was created following a customer survey.","It requires the purchase of special equipment.","It can be canceled within the first month at no charge."],"ans":"D","xp":"Câu hỏi suy luận. \"If at any time during the one-month trial period you are not satisfied with this plan, you can unsubscribe from the service at no cost to you.\" → có thể hủy trong tháng đầu mà không mất phí → chọn (D). 'unsubscribe' ≈ 'be canceled', 'at no cost' ≈ 'at no charge', 'one-month trial period' ≈ 'within the first month'. Cuộc khảo sát chỉ nói về mức độ ưa chuộng, không phải lý do tạo ra gói nên (B) sai.\n(A) Gói này đắt hơn các gói khác.\n(B) Gói này được tạo ra sau một cuộc khảo sát khách hàng.\n(C) Gói này yêu cầu mua thiết bị đặc biệt.\n(D) Gói này có thể được hủy trong tháng đầu tiên mà không mất phí."}]},{"ns":[176,180],"head":"Questions 176-180 refer to the following webinar description and e-mail.","passages":["<h3>Introduction to Project Management</h3><p>Online Webinar<br>18 January, 9 A.M.–2 P.M.<br>Presenter: Shrijana Patel<br>Cost: €45<br>(Register by 10 January and receive a 10% discount!)</p><p>This live webinar offers attendees a better understanding of how to improve the role that project management plays in their organizations. The presentation will provide the basics of managing projects and workers. Participants will learn strategies and best practices to effectively oversee their projects and foster buy-in from key players.</p><p>Participants will explore a simple step-by-step process for managing projects and learn how to use tools and documents such as scope statements and communication plans. The presenter will also cover topics such as developing a project's business case and facilitating productive team meetings.</p>","<div class=\"hdr\"><p><b>To:</b> Maya Liu</p><p><b>From:</b> Leonard Chung</p><p><b>Subject:</b> Webinar</p><p><b>Date:</b> 2 January</p></div><p>Dear Ms. Liu:</p><p>Thank you for sending me the webinar announcement. As a novice supervisor, I need to get all the training I can, but I'm not sure whether I will be able to take advantage of this particular offering. I am scheduled to present a detailed project update at my company's quarterly division meeting on the same day, and I don't think anyone else on the team would be able to take my place.</p><p>Do you know whether the webinar will be recorded or whether there will be a similar webinar at a later date? I have no schedule conflicts after 29 January.</p><p>Leonard Chung</p>"],"vi":"Giới thiệu về Quản lý dự án\nHội thảo trực tuyến (webinar)\n18 tháng 1, 9 giờ sáng – 2 giờ chiều\nNgười trình bày: Shrijana Patel\nChi phí: 45 euro\n(Đăng ký trước ngày 10 tháng 1 để được giảm giá 10%!)\n\nHội thảo trực tuyến trực tiếp này giúp người tham dự hiểu rõ hơn cách nâng cao vai trò của quản lý dự án trong tổ chức của họ. Bài trình bày sẽ cung cấp những kiến thức cơ bản về quản lý dự án và nhân sự. Người tham gia sẽ học các chiến lược và phương pháp tốt nhất để giám sát dự án hiệu quả và tạo được sự ủng hộ từ những người có vai trò then chốt.\n\nNgười tham gia sẽ tìm hiểu một quy trình quản lý dự án đơn giản theo từng bước và học cách sử dụng các công cụ và tài liệu như bản mô tả phạm vi dự án và kế hoạch truyền thông. Người trình bày cũng sẽ đề cập đến các chủ đề như xây dựng phương án kinh doanh (business case) cho dự án và điều phối các cuộc họp nhóm hiệu quả.\n\n---\n\nĐến: Maya Liu\nTừ: Leonard Chung\nTiêu đề: Hội thảo trực tuyến\nNgày: 2 tháng 1\n\nKính gửi cô Liu,\n\nCảm ơn cô đã gửi cho tôi thông báo về hội thảo trực tuyến. Là một người mới làm giám sát, tôi cần được đào tạo càng nhiều càng tốt, nhưng tôi không chắc mình có thể tận dụng được khóa học cụ thể này hay không. Tôi đã được lên lịch trình bày bản cập nhật chi tiết về dự án tại cuộc họp bộ phận hằng quý của công ty vào đúng ngày đó, và tôi không nghĩ có ai khác trong nhóm có thể thay tôi.\n\nCô có biết hội thảo này có được ghi hình lại không, hoặc sau này có một hội thảo tương tự không? Sau ngày 29 tháng 1 thì tôi không bị trùng lịch nữa.\n\nLeonard Chung","qs":[{"n":176,"q":"What is indicated about the webinar?","qvi":"Điều gì được nêu về hội thảo trực tuyến?","opts":["It includes a session on preparing for job interviews.","It will show participants how to use specific tools.","There is no charge for participants.","Registration closes on January 10."],"ans":"B","xp":"Dạng chi tiết (thông tin được nêu). Đoạn 2 phần mô tả: \"Participants will ... learn how to use tools and documents such as scope statements and communication plans.\" → hội thảo hướng dẫn cách dùng các công cụ cụ thể → chọn (B). (A) không nhắc đến phỏng vấn xin việc. (C) sai: \"Cost: €45\". (D) sai: 10/1 chỉ là hạn để được giảm giá 10% (\"Register by 10 January and receive a 10% discount\"), không phải hạn chót đăng ký.\n(A) Nó có một phần về chuẩn bị cho phỏng vấn xin việc.\n(B) Nó sẽ chỉ cho người tham gia cách sử dụng các công cụ cụ thể.\n(C) Người tham gia không phải trả phí.\n(D) Hạn đăng ký kết thúc vào ngày 10 tháng 1."},{"n":177,"q":"In the webinar description, the word \"cover\" in paragraph 2, line 3, is closest in meaning to","qvi":"Trong phần mô tả hội thảo, từ \"cover\" ở đoạn 2, dòng 3 gần nghĩa nhất với","opts":["protect","spread","ask for","talk about"],"ans":"D","xp":"Dạng đồng nghĩa. Câu gốc: \"The presenter will also cover topics such as developing a project's business case...\" — người trình bày sẽ 'đề cập đến, nói về' các chủ đề. 'cover topics' = nói về các chủ đề → 'talk about' → chọn (D). (A) protect (che chắn, bảo vệ) và (B) spread (phủ, trải ra) là các nghĩa khác của 'cover' nhưng không hợp với 'topics'.\n(A) bảo vệ\n(B) trải ra, lan rộng\n(C) yêu cầu\n(D) nói về"},{"n":178,"q":"What is one purpose of the e-mail?","qvi":"Một mục đích của e-mail là gì?","opts":["To explain a scheduling conflict","To request a deadline extension","To apologize for arriving late to an event","To ask for help in preparing a presentation"],"ans":"A","xp":"Dạng mục đích. Ông Chung viết: \"I am scheduled to present a detailed project update at my company's quarterly division meeting on the same day\" và \"I have no schedule conflicts after 29 January.\" → ông giải thích việc bị trùng lịch với hội thảo → chọn (A). (B) không xin gia hạn. (C) không xin lỗi vì đến muộn. (D) ông sẽ thuyết trình nhưng không nhờ giúp chuẩn bị.\n(A) Để giải thích việc bị trùng lịch\n(B) Để xin gia hạn thời hạn\n(C) Để xin lỗi vì đến trễ một sự kiện\n(D) Để nhờ giúp chuẩn bị một bài thuyết trình"},{"n":179,"q":"What is suggested about Mr. Chung?","qvi":"Có thể suy ra điều gì về ông Chung?","opts":["He plans to record his presentation.","He often trains new project managers.","He attends webinars on a regular basis.","He has relatively little experience as a supervisor."],"ans":"D","xp":"Dạng suy luận. E-mail: \"As a novice supervisor, I need to get all the training I can\". 'novice' = người mới vào nghề → ông còn ít kinh nghiệm làm giám sát → chọn (D). (A) ông hỏi hội thảo có được ghi hình không, chứ không định ghi hình bài thuyết trình của mình. (B), (C) không được nhắc đến.\n(A) Ông ấy dự định ghi hình bài thuyết trình của mình.\n(B) Ông ấy thường đào tạo các quản lý dự án mới.\n(C) Ông ấy tham dự hội thảo trực tuyến thường xuyên.\n(D) Ông ấy có tương đối ít kinh nghiệm làm giám sát."},{"n":180,"q":"On what date is Mr. Chung scheduled to give a presentation?","qvi":"Ông Chung được lên lịch thuyết trình vào ngày nào?","opts":["January 2","January 10","January 18","January 29"],"ans":"C","xp":"Dạng liên kết 2 văn bản. E-mail: \"I am scheduled to present a detailed project update ... on the same day\" — cùng ngày với hội thảo. Phần mô tả hội thảo: \"18 January, 9 A.M.–2 P.M.\" → ông thuyết trình ngày 18/1 → chọn (C). (A) 2/1 là ngày gửi e-mail, (B) 10/1 là hạn đăng ký được giảm giá, (D) 29/1 là mốc sau đó ông hết bị trùng lịch.\n(A) Ngày 2 tháng 1\n(B) Ngày 10 tháng 1\n(C) Ngày 18 tháng 1\n(D) Ngày 29 tháng 1"}]},{"ns":[181,185],"head":"Questions 181-185 refer to the following article and review.","passages":["<p>GALWAY (4 March)—Adelle Rosier, a third-generation soap maker, opened her shop in Galway eight years ago. Nestled behind Eglinton Gourmet Market on Raven Terrace, her business, Rosier and Finch, is booming.</p><p>Ms. Rosier credits the success to her commitment to lifelong learning. \"Yes, my handcrafted soaps, shampoos, and lotions are luxurious,\" she said. \"But there are a lot of high-quality skin-care products out there. So after learning the trade from my family, I have increased my sales knowledge by taking online courses in business-to-business (B2B) marketing.\"</p><p>Ms. Rosier adds that those courses built her confidence in selling her products directly to hotels. \"Thanks to what I learned in my B2B strategies courses, I managed to persuade a number of boutique hotels in Europe to try my products.\" And so Rosier and Finch skin-care products are available in guest rooms at, for instance, the Bruadair Hotel in Galway, the Florinda Grand in Lisbon, Portugal, and the Zerra Inn in Reykjavik, Iceland.</p><p>Ms. Rosier further points out that many of her customers first learn of her products during a hotel stay. Afterward, they visit the shop in person or go online to purchase the items for themselves.</p><p>Rosier and Finch is located at 12 Raven Terrace and can be found online at www.rosierandfinch.co.ie.</p>","<p>https://www.florindagrand.pt/en/guest_reviews</p><p>I had to arrange a last-minute business trip to my company's Portugal office, and the usual hotel I book was completely full. Based on some online recommendations, I decided to stay at Florinda Grand. While this charming hotel is much smaller than the usual places I stay, it has every comfort one would want during a business trip. In addition to a tastefully decorated and comfortable room, there were gourmet treats on my pillowcase and the finest soap, shampoo, and other toiletries available for me to enjoy. My only regret is that I was in Lisbon for just three days. Next time I visit the Lisbon office, I will stay longer and book a room at the Florinda Grand.</p><p>—posted by Ashton Wu, 7 June</p>"],"vi":"GALWAY (4 tháng 3) — Adelle Rosier, một thợ làm xà phòng thế hệ thứ ba, đã mở cửa hàng của mình ở Galway cách đây tám năm. Nằm nép mình phía sau Chợ Ẩm thực Eglinton trên phố Raven Terrace, doanh nghiệp của bà, Rosier and Finch, đang phát đạt.\n\nBà Rosier cho rằng thành công này là nhờ bà luôn theo đuổi việc học tập suốt đời. \"Đúng vậy, xà phòng, dầu gội và kem dưỡng thủ công của tôi rất sang trọng,\" bà nói. \"Nhưng ngoài kia có rất nhiều sản phẩm chăm sóc da chất lượng cao. Vì vậy, sau khi học nghề từ gia đình, tôi đã nâng cao kiến thức bán hàng bằng cách tham gia các khóa học trực tuyến về tiếp thị giữa doanh nghiệp với doanh nghiệp (B2B).\"\n\nBà Rosier nói thêm rằng những khóa học đó đã giúp bà tự tin bán sản phẩm trực tiếp cho các khách sạn. \"Nhờ những gì học được trong các khóa chiến lược B2B, tôi đã thuyết phục được một số khách sạn boutique ở châu Âu dùng thử sản phẩm của mình.\" Và thế là các sản phẩm chăm sóc da của Rosier and Finch hiện có trong phòng khách tại, chẳng hạn, khách sạn Bruadair ở Galway, Florinda Grand ở Lisbon (Bồ Đào Nha) và Zerra Inn ở Reykjavik (Iceland).\n\nBà Rosier còn cho biết nhiều khách hàng của bà biết đến sản phẩm lần đầu trong một lần lưu trú ở khách sạn. Sau đó, họ đến cửa hàng trực tiếp hoặc lên mạng để mua sản phẩm cho mình.\n\nRosier and Finch nằm ở số 12 Raven Terrace và có trang web tại www.rosierandfinch.co.ie.\n\n---\n\nhttps://www.florindagrand.pt/en/guest_reviews\n\nTôi phải sắp xếp một chuyến công tác gấp đến văn phòng của công ty ở Bồ Đào Nha, và khách sạn tôi thường đặt đã hết sạch phòng. Dựa trên một số lời giới thiệu trên mạng, tôi quyết định ở Florinda Grand. Dù khách sạn duyên dáng này nhỏ hơn nhiều so với những nơi tôi thường ở, nó có mọi tiện nghi mà một người cần trong chuyến công tác. Ngoài căn phòng được trang trí trang nhã và thoải mái, còn có những món ăn vặt hảo hạng đặt trên gối và xà phòng, dầu gội cùng các đồ dùng vệ sinh cá nhân hảo hạng khác để tôi sử dụng. Điều tiếc nuối duy nhất của tôi là tôi chỉ ở Lisbon có ba ngày. Lần tới khi đến văn phòng Lisbon, tôi sẽ ở lâu hơn và đặt phòng tại Florinda Grand.\n\n— đăng bởi Ashton Wu, ngày 7 tháng 6","qs":[{"n":181,"q":"What is the purpose of the article?","qvi":"Mục đích của bài báo là gì?","opts":["To provide annual hotel ratings","To announce the opening of a store","To profile a small-business owner","To discuss online shopping trends"],"ans":"C","xp":"Dạng mục đích. Toàn bài viết về bà Adelle Rosier — thợ làm xà phòng, chủ doanh nghiệp Rosier and Finch: lý do thành công (\"Ms. Rosier credits the success to her commitment to lifelong learning\"), cách bà bán hàng cho khách sạn... → bài báo giới thiệu chân dung một chủ doanh nghiệp nhỏ → chọn (C). (B) sai: cửa hàng đã mở \"eight years ago\", không phải mới khai trương. (A), (D) không phải nội dung chính.\n(A) Để đưa ra bảng xếp hạng khách sạn hằng năm\n(B) Để thông báo việc khai trương một cửa hàng\n(C) Để giới thiệu chân dung một chủ doanh nghiệp nhỏ\n(D) Để bàn về xu hướng mua sắm trực tuyến"},{"n":182,"q":"How did Ms. Rosier improve her marketing skills?","qvi":"Bà Rosier đã cải thiện kỹ năng tiếp thị bằng cách nào?","opts":["By visiting family members overseas","By joining a professional association","By working in the hotel industry","By participating in online classes"],"ans":"D","xp":"Dạng chi tiết. Bài báo: \"I have increased my sales knowledge by taking online courses in business-to-business (B2B) marketing.\" 'taking online courses' = 'participating in online classes' → chọn (D). (A) bà học nghề từ gia đình nhưng không nói đi thăm người thân ở nước ngoài. (B), (C) không được nhắc đến.\n(A) Bằng cách đi thăm người thân ở nước ngoài\n(B) Bằng cách gia nhập một hiệp hội nghề nghiệp\n(C) Bằng cách làm việc trong ngành khách sạn\n(D) Bằng cách tham gia các lớp học trực tuyến"},{"n":183,"q":"What is stated about Rosier and Finch?","qvi":"Điều gì được nêu về Rosier and Finch?","opts":["It sells its products to other businesses.","It has shops in cities around the world.","It is redesigning its e-commerce site.","It offers courses on soapmaking."],"ans":"A","xp":"Dạng chi tiết. Bài báo: \"those courses built her confidence in selling her products directly to hotels\" và \"I managed to persuade a number of boutique hotels in Europe to try my products\" → Rosier and Finch bán sản phẩm cho các doanh nghiệp khác (khách sạn) → chọn (A). (B) sai: chỉ có một cửa hàng ở 12 Raven Terrace, Galway; sản phẩm có mặt ở khách sạn các nước chứ không phải cửa hàng. (C) không nhắc việc thiết kế lại trang web. (D) bà Rosier tham gia khóa học chứ công ty không mở khóa học làm xà phòng.\n(A) Công ty bán sản phẩm cho các doanh nghiệp khác.\n(B) Công ty có cửa hàng ở nhiều thành phố trên thế giới.\n(C) Công ty đang thiết kế lại trang thương mại điện tử.\n(D) Công ty mở các khóa học làm xà phòng."},{"n":184,"q":"What is suggested about Mr. Wu?","qvi":"Có thể suy ra điều gì về ông Wu?","opts":["He manages Eglinton Gourmet Market.","He purchased Rosier and Finch products online.","He met Ms. Rosier on a business trip.","He likes Rosier and Finch products."],"ans":"D","xp":"Dạng suy luận, liên kết 2 văn bản. Bài đánh giá: ông Wu ở Florinda Grand và khen \"the finest soap, shampoo, and other toiletries available for me to enjoy\". Bài báo: sản phẩm Rosier and Finch \"are available in guest rooms at ... the Florinda Grand in Lisbon\" → xà phòng, dầu gội ông khen chính là của Rosier and Finch → ông thích sản phẩm này → chọn (D). (B) không có thông tin ông mua online. (A), (C) không được nhắc đến.\n(A) Ông ấy quản lý Chợ Ẩm thực Eglinton.\n(B) Ông ấy đã mua sản phẩm Rosier and Finch trên mạng.\n(C) Ông ấy gặp bà Rosier trong một chuyến công tác.\n(D) Ông ấy thích sản phẩm của Rosier and Finch."},{"n":185,"q":"According to the review, what was Mr. Wu not pleased about?","qvi":"Theo bài đánh giá, ông Wu không hài lòng về điều gì?","opts":["The length of his trip","The decorations in the room","The comfort of the pillows","The size of the hotel"],"ans":"A","xp":"Dạng chi tiết. Bài đánh giá: \"My only regret is that I was in Lisbon for just three days.\" → ông tiếc vì chuyến đi quá ngắn = 'the length of his trip' → chọn (A). (B) ông khen phòng \"tastefully decorated\". (C) gối có \"gourmet treats\", không chê. (D) khách sạn \"much smaller\" nhưng ông vẫn khen \"it has every comfort\".\n(A) Độ dài chuyến đi\n(B) Cách trang trí trong phòng\n(C) Độ êm của gối\n(D) Quy mô của khách sạn"}]},{"ns":[186,190],"head":"Questions 186-190 refer to the following sales report, memo, and article.","passages":["<h3>Margot's House of Ice Cream</h3><p>Flavor Purchases by Percentage of Sales<br>July</p><table><tr><th>Flavor</th><th>Percent</th></tr><tr><td>Chocolate</td><td>22</td></tr><tr><td>Vanilla</td><td>18</td></tr><tr><td>Strawberry</td><td>11</td></tr><tr><td>Cookies and cream</td><td>8</td></tr><tr><td>Butter pecan</td><td>8</td></tr><tr><td>Mint chocolate chip</td><td>7</td></tr><tr><td>All others</td><td>26</td></tr></table>","<h3>MEMO</h3><div class=\"hdr\"><p><b>To:</b> All Store Managers</p><p><b>From:</b> June Willcox, CEO, Margot's House of Ice Cream</p><p><b>Subject:</b> New Stores</p><p><b>Date:</b> October 5</p></div><p>Margot's House of Ice Cream is proud to welcome the following new stores.</p><table><tr><th>Store Number</th><th>Location</th><th>Opening Date</th><th>Manager</th></tr><tr><td>66</td><td>Framingham, Massachusetts, United States</td><td>September 1</td><td>Inga Slavin</td></tr><tr><td>67</td><td>Appleton, Wisconsin, United States</td><td>September 7</td><td>Zheng Tong</td></tr><tr><td>68</td><td>Wollongong, New South Wales, Australia</td><td>September 14</td><td>Geoffrey Pratt</td></tr><tr><td>69</td><td>Rotorua, New Zealand</td><td>September 15</td><td>Kehinde Ilogu</td></tr><tr><td>70</td><td>Greater Sudbury, Ontario, Canada</td><td>September 29</td><td>Hallie Strafford</td></tr></table><p>For the next six months, we will be supporting these stores with advertisements in their local media markets.</p><p>In December, we plan to open stores in Italy and Switzerland. Demand for our quality product is higher than ever, our market share is increasing, and we are not finished expanding! Stay tuned for more information!</p>","<h3>Popular Ice Cream Purveyor Comes to New Zealand</h3><p><i>By Ysai Mendez</i></p><p>ROTORUA (2 November)—Residents of Rotorua have been flocking to Cargill Street, where Margot's House of Ice Cream has opened its first store in New Zealand.</p><p>\"I don't know what their secret is, but their ice cream really is something special,\" said Jeremy Frank, a schoolteacher who was enjoying ice cream cones with his family on a recent afternoon. \"We've been here several times already since they opened. I think we'll be regulars.\"</p><p>\"I love strawberry, and their strawberry is the best I ever had,\" added his daughter, Olivia Frank, age 10.</p><p>Margot's House of Ice Cream was founded five years ago in San Francisco by Margot Summers, a former chemistry major. Its ice cream contains at least 11 percent milk fat. Milk used in production, according to company CEO June Willcox, is sourced locally or regionally whenever possible.</p><p>Kehinde Ilogu, the manager of the Rotorua store, says that the number of visitors has been rising steadily.</p><p>\"We plan to keep the momentum going by having special events once a month,\" he said. \"Next up is the strawberry festival. New Zealand's strawberry season will be getting started. In addition to our superb ice cream, we'll offer strawberries dipped in chocolate, strawberry cupcakes, and strawberry milkshakes. We look forward to a great future in Rotorua.\"</p>"],"vi":"Margot's House of Ice Cream\nLượng mua theo hương vị tính theo phần trăm doanh số\nTháng 7\n\nHương vị — Phần trăm\nSô-cô-la — 22\nVani — 18\nDâu — 11\nBánh quy kem (cookies and cream) — 8\nBơ hồ đào (butter pecan) — 8\nBạc hà sô-cô-la chip — 7\nTất cả các vị khác — 26\n\n---\n\nBẢN GHI NHỚ\nĐến: Tất cả quản lý cửa hàng\nTừ: June Willcox, Giám đốc điều hành, Margot's House of Ice Cream\nTiêu đề: Các cửa hàng mới\nNgày: 5 tháng 10\n\nMargot's House of Ice Cream tự hào chào đón các cửa hàng mới sau đây.\n\nSố cửa hàng — Địa điểm — Ngày khai trương — Quản lý\n66 — Framingham, Massachusetts, Hoa Kỳ — 1 tháng 9 — Inga Slavin\n67 — Appleton, Wisconsin, Hoa Kỳ — 7 tháng 9 — Zheng Tong\n68 — Wollongong, New South Wales, Úc — 14 tháng 9 — Geoffrey Pratt\n69 — Rotorua, New Zealand — 15 tháng 9 — Kehinde Ilogu\n70 — Greater Sudbury, Ontario, Canada — 29 tháng 9 — Hallie Strafford\n\nTrong sáu tháng tới, chúng tôi sẽ hỗ trợ các cửa hàng này bằng quảng cáo trên các kênh truyền thông địa phương.\n\nVào tháng 12, chúng tôi dự định mở cửa hàng ở Ý và Thụy Sĩ. Nhu cầu đối với sản phẩm chất lượng của chúng ta đang cao hơn bao giờ hết, thị phần đang tăng, và chúng ta vẫn chưa dừng việc mở rộng! Hãy chờ đón thêm thông tin!\n\n---\n\nNhà bán kem nổi tiếng đến New Zealand\nTác giả: Ysai Mendez\n\nROTORUA (2 tháng 11) — Người dân Rotorua đã đổ xô đến phố Cargill, nơi Margot's House of Ice Cream vừa mở cửa hàng đầu tiên tại New Zealand.\n\n\"Tôi không biết bí quyết của họ là gì, nhưng kem của họ thực sự rất đặc biệt,\" Jeremy Frank, một giáo viên đang cùng gia đình thưởng thức kem ốc quế vào một buổi chiều gần đây, cho biết. \"Từ khi họ khai trương, chúng tôi đã đến đây vài lần rồi. Tôi nghĩ chúng tôi sẽ thành khách quen.\"\n\n\"Cháu thích vị dâu, và kem dâu ở đây là ngon nhất cháu từng ăn,\" con gái ông, Olivia Frank, 10 tuổi, nói thêm.\n\nMargot's House of Ice Cream được thành lập cách đây năm năm tại San Francisco bởi Margot Summers, người từng học chuyên ngành hóa học. Kem của hãng chứa ít nhất 11% chất béo sữa. Theo giám đốc điều hành June Willcox, sữa dùng trong sản xuất được lấy từ nguồn địa phương hoặc trong khu vực bất cứ khi nào có thể.\n\nKehinde Ilogu, quản lý cửa hàng ở Rotorua, cho biết lượng khách đến đang tăng đều đặn.\n\n\"Chúng tôi dự định duy trì đà phát triển bằng cách tổ chức sự kiện đặc biệt mỗi tháng một lần,\" ông nói. \"Sự kiện tiếp theo là lễ hội dâu tây. Mùa dâu của New Zealand sắp bắt đầu. Ngoài kem tuyệt hảo, chúng tôi sẽ có dâu nhúng sô-cô-la, bánh cupcake dâu và sữa lắc dâu. Chúng tôi mong đợi một tương lai tươi sáng ở Rotorua.\"","qs":[{"n":186,"q":"According to the sales report, what flavor of ice cream is purchased at the same rate as Butter pecan?","qvi":"Theo báo cáo doanh số, vị kem nào được mua với tỉ lệ bằng vị Butter pecan?","opts":["Chocolate","Vanilla","Cookies and cream","Mint chocolate chip"],"ans":"C","xp":"Dạng chi tiết (đọc bảng). Báo cáo: \"Butter pecan — 8\" và \"Cookies and cream — 8\" → cùng 8% → chọn (C). (A) Chocolate 22, (B) Vanilla 18, (D) Mint chocolate chip 7.\n(A) Sô-cô-la\n(B) Vani\n(C) Bánh quy kem\n(D) Bạc hà sô-cô-la chip"},{"n":187,"q":"What is true about the products listed in the sales report?","qvi":"Điều gì đúng về các sản phẩm được liệt kê trong báo cáo doanh số?","opts":["They contain at least 11 percent milk fat.","They are made with artificial flavors.","They will increase in price soon.","They are sold mainly in San Francisco."],"ans":"A","xp":"Dạng liên kết văn bản. Báo cáo liệt kê các vị kem của Margot's House of Ice Cream; bài báo viết: \"Its ice cream contains at least 11 percent milk fat.\" → các sản phẩm này chứa ít nhất 11% chất béo sữa → chọn (A). (B), (C) không được nhắc đến. (D) San Francisco chỉ là nơi thành lập công ty; công ty có cửa hàng ở nhiều nước.\n(A) Chúng chứa ít nhất 11% chất béo sữa.\n(B) Chúng được làm bằng hương liệu nhân tạo.\n(C) Chúng sẽ sớm tăng giá.\n(D) Chúng được bán chủ yếu ở San Francisco."},{"n":188,"q":"What is indicated in the memo about the company's new managers?","qvi":"Bản ghi nhớ cho biết điều gì về các quản lý mới của công ty?","opts":["They were trained in Italy and Switzerland.","They will receive advertising support for six months.","They expect their stores to become profitable in December.","They offered special promotions on opening day."],"ans":"B","xp":"Dạng chi tiết. Bản ghi nhớ: \"For the next six months, we will be supporting these stores with advertisements in their local media markets.\" → các cửa hàng mới (do các quản lý mới phụ trách) sẽ được hỗ trợ quảng cáo trong sáu tháng → chọn (B). (A) Ý và Thụy Sĩ là nơi sẽ mở cửa hàng vào tháng 12, không phải nơi đào tạo. (C) tháng 12 là thời điểm mở cửa hàng mới, không phải lúc có lãi. (D) không nhắc khuyến mãi ngày khai trương.\n(A) Họ được đào tạo ở Ý và Thụy Sĩ.\n(B) Họ sẽ nhận được hỗ trợ quảng cáo trong sáu tháng.\n(C) Họ kỳ vọng cửa hàng có lãi vào tháng 12.\n(D) Họ đã có khuyến mãi đặc biệt vào ngày khai trương."},{"n":189,"q":"What will soon happen at store 69 ?","qvi":"Điều gì sắp diễn ra tại cửa hàng số 69?","opts":["More ice cream flavors will be added to the menu.","A child's birthday will be celebrated.","An assistant manager will be hired.","A range of special treats will be sold."],"ans":"D","xp":"Dạng liên kết văn bản. Bản ghi nhớ: cửa hàng số 69 ở \"Rotorua, New Zealand\", quản lý Kehinde Ilogu. Bài báo, ông Ilogu nói: \"Next up is the strawberry festival... we'll offer strawberries dipped in chocolate, strawberry cupcakes, and strawberry milkshakes.\" → sắp bán nhiều món đặc biệt → 'a range of special treats' → chọn (D). (A) không nói thêm vị kem mới. (B), (C) không được nhắc đến.\n(A) Sẽ có thêm vị kem mới trong thực đơn.\n(B) Sẽ tổ chức sinh nhật cho một em bé.\n(C) Sẽ tuyển một trợ lý quản lý.\n(D) Sẽ bán nhiều món ăn đặc biệt."},{"n":190,"q":"Who is most likely to enjoy the strawberry festival?","qvi":"Ai có khả năng thích lễ hội dâu tây nhất?","opts":["Mr. Mendez","Ms. Willcox","Ms. Frank","Ms. Summers"],"ans":"C","xp":"Dạng suy luận. Bài báo: \"'I love strawberry, and their strawberry is the best I ever had,' added his daughter, Olivia Frank, age 10.\" → cô bé Olivia Frank mê vị dâu nên nhiều khả năng sẽ thích lễ hội dâu tây → chọn (C). (A) Mendez là tác giả bài báo, (B) Willcox là CEO, (D) Summers là người sáng lập; không ai được nói là thích dâu.\n(A) Ông Mendez\n(B) Bà Willcox\n(C) Cô Frank\n(D) Bà Summers"}]},{"ns":[191,195],"head":"Questions 191-195 refer to the following e-mails and memo.","passages":["<div class=\"hdr\"><p><b>To:</b> Emi Tokuda &lt;etokuda@paterradepartmentstores.com&gt;</p><p><b>From:</b> Paul Soderman &lt;p.soderman@galahadindustrialmachinery.com&gt;</p><p><b>Date:</b> January 25</p><p><b>Subject:</b> Our discussion</p></div><p>Dear Ms. Tokuda,</p><p>I'm writing to confirm the details of our telephone conversation earlier today.</p><p>As we discussed, Galahad Industrial Machinery will install and maintain one self-service checkout kiosk in each of the four locations operated by Paterra Department Stores in Haddonfield. The installation charge for each kiosk will be $2,000 per unit. Installation will be scheduled at a mutually agreed-upon day and time.</p><p>Our maintenance fee, covering all four kiosks, is $120 per month. Our technicians will be available 24 hours a day, 7 days a week, to service the kiosks. All equipment will meet or exceed international quality standards, and all our work is guaranteed.</p><p>A formal written agreement will be sent to you by registered mail. We look forward to working with you.</p><p>Sincerely,</p><p>Paul Soderman, Managing Director<br>Galahad Industrial Machinery</p>","<div class=\"hdr\"><p><b>To:</b> Paul Soderman &lt;p.soderman@galahadindustrialmachinery.com&gt;</p><p><b>From:</b> Emi Tokuda &lt;etokuda@paterradepartmentstores.com&gt;</p><p><b>Date:</b> April 2</p><p><b>Subject:</b> Equipment removal and reinstallation</p></div><p>Dear Mr. Soderman,</p><p>Please be advised that we have decided to close our store at 1506 Maple Street. We plan to transfer the inventory and all equipment to our new location at 3300 Town Square Plaza. The transfer is planned for mid-June, but we have not yet set a date.</p><p>I will contact you next month to confirm the date and arrange a convenient time for your work crew to install the self-service kiosk. I understand that, per our agreement dated January 25, your charge for the reinstallation will be the same as for the initial installation at the Maple Street store.</p><p>Yours truly,</p><p>Emi Tokuda, Managing Director<br>Paterra Department Stores</p>","<h3>MEMO</h3><div class=\"hdr\"><p><b>To:</b> All Paterra Staff</p><p><b>From:</b> Eleanor Bianchi, Branch Manager</p><p><b>Date:</b> June 5</p><p><b>Re:</b> Move update</p></div><p>Thanks to your hard work, our new store in the Town Square Plaza is on track to open on June 15. One of the problems with the store we are currently working out of is that it is not on a bus line. By contrast, the location we will be moving to is served by bus number 689, so we expect to have a larger number of customers at that location. We are only waiting for the last of our display shelves to be delivered from our warehouse so that we can finish the display in the gardening department.</p><p>In appreciation of your efforts, I've brought pastries from Aniqa's Bakery. I've put these treats on the break-room counter. Enjoy!</p>"],"vi":"Đến: Emi Tokuda <etokuda@paterradepartmentstores.com>\nTừ: Paul Soderman <p.soderman@galahadindustrialmachinery.com>\nNgày: 25 tháng 1\nTiêu đề: Cuộc trao đổi của chúng ta\n\nKính gửi bà Tokuda,\n\nTôi viết thư này để xác nhận các chi tiết trong cuộc điện thoại của chúng ta sáng nay.\n\nNhư đã trao đổi, Galahad Industrial Machinery sẽ lắp đặt và bảo trì một ki-ốt thanh toán tự phục vụ tại mỗi địa điểm trong số bốn địa điểm do Paterra Department Stores điều hành ở Haddonfield. Phí lắp đặt cho mỗi ki-ốt là 2.000 đô la một máy. Việc lắp đặt sẽ được lên lịch vào ngày giờ do hai bên thống nhất.\n\nPhí bảo trì của chúng tôi cho cả bốn ki-ốt là 120 đô la mỗi tháng. Kỹ thuật viên của chúng tôi luôn sẵn sàng 24 giờ một ngày, 7 ngày một tuần để bảo dưỡng các ki-ốt. Mọi thiết bị đều đạt hoặc vượt tiêu chuẩn chất lượng quốc tế, và mọi công việc của chúng tôi đều được bảo đảm.\n\nMột bản thỏa thuận chính thức bằng văn bản sẽ được gửi đến bà qua thư bảo đảm. Chúng tôi mong được hợp tác với bà.\n\nTrân trọng,\n\nPaul Soderman, Giám đốc điều hành\nGalahad Industrial Machinery\n\n---\n\nĐến: Paul Soderman <p.soderman@galahadindustrialmachinery.com>\nTừ: Emi Tokuda <etokuda@paterradepartmentstores.com>\nNgày: 2 tháng 4\nTiêu đề: Tháo dỡ và lắp đặt lại thiết bị\n\nKính gửi ông Soderman,\n\nXin thông báo rằng chúng tôi đã quyết định đóng cửa hàng tại số 1506 phố Maple. Chúng tôi dự định chuyển hàng tồn kho và toàn bộ thiết bị đến địa điểm mới tại số 3300 Town Square Plaza. Việc chuyển dự kiến vào giữa tháng 6, nhưng chúng tôi chưa chốt ngày.\n\nTôi sẽ liên hệ với ông vào tháng sau để xác nhận ngày và sắp xếp thời gian thuận tiện để đội thợ của ông đến lắp ki-ốt tự phục vụ. Tôi hiểu rằng, theo thỏa thuận ngày 25 tháng 1 của chúng ta, phí lắp đặt lại sẽ bằng với phí lắp đặt ban đầu tại cửa hàng phố Maple.\n\nTrân trọng,\n\nEmi Tokuda, Giám đốc điều hành\nPaterra Department Stores\n\n---\n\nBẢN GHI NHỚ\nĐến: Toàn thể nhân viên Paterra\nTừ: Eleanor Bianchi, Quản lý chi nhánh\nNgày: 5 tháng 6\nV/v: Cập nhật về việc chuyển địa điểm\n\nNhờ sự làm việc chăm chỉ của các bạn, cửa hàng mới của chúng ta ở Town Square Plaza đang đúng tiến độ để khai trương vào ngày 15 tháng 6. Một trong những vấn đề của cửa hàng mà chúng ta đang làm việc hiện nay là nó không nằm trên tuyến xe buýt nào. Ngược lại, địa điểm chúng ta sắp chuyển đến có xe buýt số 689 chạy qua, nên chúng ta kỳ vọng sẽ có nhiều khách hàng hơn ở đó. Chúng ta chỉ còn chờ đợt kệ trưng bày cuối cùng được giao từ kho để hoàn thiện khu trưng bày ở gian hàng làm vườn.\n\nĐể cảm ơn nỗ lực của các bạn, tôi đã mang bánh ngọt từ tiệm Aniqa's Bakery đến. Tôi đã đặt chúng trên quầy ở phòng nghỉ. Chúc các bạn ngon miệng!","qs":[{"n":191,"q":"In the first e-mail, what is stated about Galahad Industrial Machinery?","qvi":"Trong e-mail thứ nhất, điều gì được nêu về Galahad Industrial Machinery?","opts":["It completes repairs within one day.","It is available to do maintenance service at all times.","It has technicians with international work experience.","It has an office in Haddonfield."],"ans":"B","xp":"Dạng chi tiết. E-mail 1: \"Our technicians will be available 24 hours a day, 7 days a week, to service the kiosks.\" '24 hours a day, 7 days a week' = 'at all times' (mọi lúc) → chọn (B). (A) không nói sửa trong một ngày. (C) 'international' chỉ nói về tiêu chuẩn chất lượng thiết bị, không phải kinh nghiệm của kỹ thuật viên. (D) Haddonfield là nơi có các cửa hàng Paterra, không phải văn phòng của Galahad.\n(A) Công ty hoàn thành sửa chữa trong vòng một ngày.\n(B) Công ty luôn sẵn sàng làm dịch vụ bảo trì vào mọi lúc.\n(C) Công ty có kỹ thuật viên với kinh nghiệm làm việc quốc tế.\n(D) Công ty có văn phòng ở Haddonfield."},{"n":192,"q":"What is true about the reinstallation of the self-service kiosk?","qvi":"Điều gì đúng về việc lắp đặt lại ki-ốt tự phục vụ?","opts":["It will be done personally by Mr. Soderman.","It will cost Paterra Department Stores $2,000.","It will cause a change in the monthly maintenance fee.","It will require a new agreement to be signed."],"ans":"B","xp":"Dạng liên kết 2 văn bản. E-mail 2: \"your charge for the reinstallation will be the same as for the initial installation at the Maple Street store.\" E-mail 1: \"The installation charge for each kiosk will be $2,000 per unit.\" → phí lắp lại = 2.000 đô la → chọn (B). (A) đội thợ (\"your work crew\") lắp, không phải đích thân ông Soderman. (C), (D) không được nhắc đến; bà Tokuda còn dựa vào thỏa thuận cũ ngày 25/1.\n(A) Việc này sẽ do đích thân ông Soderman thực hiện.\n(B) Việc này sẽ tốn của Paterra Department Stores 2.000 đô la.\n(C) Việc này sẽ làm thay đổi phí bảo trì hằng tháng.\n(D) Việc này cần ký một thỏa thuận mới."},{"n":193,"q":"When will Ms. Tokuda discuss her moving plans with Mr. Soderman?","qvi":"Khi nào bà Tokuda sẽ trao đổi kế hoạch chuyển cửa hàng với ông Soderman?","opts":["In March","In April","In May","In June"],"ans":"C","xp":"Dạng suy luận (thời gian). E-mail 2 gửi ngày \"April 2\" và viết: \"I will contact you next month to confirm the date and arrange a convenient time...\" → tháng sau của tháng 4 là tháng 5 → chọn (C). (B) tháng 4 là lúc gửi e-mail. (D) tháng 6 là lúc dự kiến chuyển cửa hàng (\"mid-June\").\n(A) Vào tháng 3\n(B) Vào tháng 4\n(C) Vào tháng 5\n(D) Vào tháng 6"},{"n":194,"q":"What is suggested about the Paterra store at 1506 Maple Street?","qvi":"Có thể suy ra điều gì về cửa hàng Paterra ở số 1506 phố Maple?","opts":["It is not accessible by bus.","It will be renovated and reopened.","It is far from the warehouse.","It contains a bakery section."],"ans":"A","xp":"Dạng suy luận, liên kết văn bản. E-mail 2: cửa hàng ở 1506 Maple Street sẽ đóng cửa và chuyển sang Town Square Plaza. Bản ghi nhớ: \"One of the problems with the store we are currently working out of is that it is not on a bus line.\" → cửa hàng hiện tại (Maple Street) không có xe buýt đến → chọn (A). (B) sai: cửa hàng bị đóng hẳn (\"close our store\"). (C) không nói khoảng cách đến kho. (D) Aniqa's Bakery là tiệm bánh nơi mua bánh, không phải gian hàng trong cửa hàng.\n(A) Không thể đến đó bằng xe buýt.\n(B) Cửa hàng sẽ được sửa sang và mở lại.\n(C) Cửa hàng ở xa nhà kho.\n(D) Cửa hàng có một gian bánh mì."},{"n":195,"q":"According to the memo, what must still be done at the new Paterra store location?","qvi":"Theo bản ghi nhớ, việc gì vẫn còn phải làm tại địa điểm cửa hàng Paterra mới?","opts":["Some products must be priced.","Some areas must be painted.","Some doors must be replaced.","Some shelves must be delivered."],"ans":"D","xp":"Dạng chi tiết. Bản ghi nhớ: \"We are only waiting for the last of our display shelves to be delivered from our warehouse so that we can finish the display in the gardening department.\" → vẫn còn phải giao một số kệ → chọn (D). (A), (B), (C) không được nhắc đến.\n(A) Một số sản phẩm phải được dán giá.\n(B) Một số khu vực phải được sơn.\n(C) Một số cửa phải được thay.\n(D) Một số kệ phải được giao đến."}]},{"ns":[196,200],"head":"Questions 196-200 refer to the following article, invitation, and e-mail.","passages":["<h3>Survey: Consumers Prefer Physical Stores</h3><p>A recent consumer survey has shown that 33% of respondents prefer to touch the products they intend to purchase. Moreover, 61% of those surveyed said they are likely to spend more when shopping at a brick-and-mortar store rather than at an online store.</p><p>These data, backed up by other consumer preference studies, are causing many merchants who generate all their revenue from online sales to open physical stores as a supplement to their online presence.</p><p>The advantage of a physical space is that it helps retail owners build brand loyalty. \"In terms of convenience, nothing beats online,\" says Marlene Fitzroy, who owns Toddles, a children's store in Shelburn, and an online site, toddles.com. \"But a physical space fosters a sense of community that keeps local customers coming back and attracts new ones.\"</p><p>Ms. Fitzroy, a frequent speaker at local business events, is not only a strong supporter and promoter of customer engagement; she also practices what she preaches.</p><p>\"Four times a year, we host a special sales event during which children can enjoy themselves with a variety of activities,\" she said. \"These events are a hit with both the children and their parents. And even if the parents don't buy anything on such occasions, the next time they need a children's toy, game, book, or puzzle, they'll probably think of us.\"</p>","<h4>Shelburn Business Coalition (SBC)</h4><p>Businesspeople from Shelburn and the surrounding area are invited to join us at the Shelburn Convention Center on October 8 for our annual Business Summit.</p><p>Our keynote speaker this year will be Mr. Hansraj Deshpande, founder and CEO of Wintereden Hoteliers. Other speakers, all local business owners, are Ms. Omodele Akindjo, Ms. Marlene Fitzroy, Mr. Jasper Klinkhamer, and Mr. Alvin Liu. Topics to be covered include building a strong workforce, establishing a line of credit, engaging with customers, and attracting venture capital.</p><p>By registering for this event, you will automatically be added to our e-mail list. Please visit our Web site, www.shelburnbusinesscoalition.org, for the full schedule.</p>","<div class=\"hdr\"><p><b>To:</b> Vaughn Sgammato &lt;vsgammato@opalmail.com&gt;</p><p><b>From:</b> Irene Warga &lt;irenewarga@shelburnbusinesscoalition.org&gt;</p><p><b>Date:</b> September 15</p><p><b>Subject:</b> Your confirmation</p></div><p>Dear Mr. Sgammato,</p><p>Shelburn Business Coalition thanks you for registering for our Business Summit. Your confirmation number is R56690.</p><p>As a reminder, please note that the convention center underground garage will be closed for maintenance on October 8. Therefore, please park your car in the public parking area across the street. At the end of the summit, you will receive a voucher to cover the parking fee.</p><p>We look forward to seeing you. If you have any questions, please contact me at 555-0138.</p><p>Yours very truly,</p><p>Irene Warga, Event Coordinator</p>"],"vi":"Khảo sát: Người tiêu dùng thích cửa hàng thực tế hơn\n\nMột cuộc khảo sát người tiêu dùng gần đây cho thấy 33% người trả lời thích được chạm vào sản phẩm mà họ định mua. Hơn nữa, 61% người được khảo sát cho biết họ có xu hướng chi tiêu nhiều hơn khi mua sắm tại cửa hàng truyền thống thay vì cửa hàng trực tuyến.\n\nNhững số liệu này, cùng với các nghiên cứu khác về sở thích của người tiêu dùng, đang khiến nhiều nhà bán lẻ vốn có toàn bộ doanh thu từ bán hàng trực tuyến mở các cửa hàng thực tế để bổ sung cho sự hiện diện trực tuyến của họ.\n\nLợi thế của một không gian thực tế là nó giúp chủ cửa hàng xây dựng lòng trung thành với thương hiệu. \"Về mặt tiện lợi, không gì bằng mua sắm trực tuyến,\" Marlene Fitzroy, chủ của Toddles — một cửa hàng đồ trẻ em ở Shelburn — và trang web toddles.com, cho biết. \"Nhưng một không gian thực tế tạo ra cảm giác cộng đồng, giúp khách hàng địa phương quay lại và thu hút khách hàng mới.\"\n\nBà Fitzroy, người thường xuyên diễn thuyết tại các sự kiện kinh doanh địa phương, không chỉ là người ủng hộ và cổ vũ mạnh mẽ cho việc gắn kết khách hàng; bà còn làm đúng những gì mình nói.\n\n\"Mỗi năm bốn lần, chúng tôi tổ chức một sự kiện bán hàng đặc biệt, trong đó trẻ em có thể vui chơi với nhiều hoạt động khác nhau,\" bà nói. \"Những sự kiện này rất được cả trẻ em lẫn phụ huynh yêu thích. Và ngay cả khi phụ huynh không mua gì vào những dịp đó, lần tới khi cần một món đồ chơi, trò chơi, sách hay trò xếp hình cho trẻ, có lẽ họ sẽ nghĩ đến chúng tôi.\"\n\n---\n\nLiên minh Doanh nghiệp Shelburn (SBC)\n\nKính mời các doanh nhân ở Shelburn và khu vực lân cận đến tham dự Hội nghị Thượng đỉnh Kinh doanh thường niên của chúng tôi tại Trung tâm Hội nghị Shelburn vào ngày 8 tháng 10.\n\nDiễn giả chính năm nay là ông Hansraj Deshpande, người sáng lập kiêm giám đốc điều hành của Wintereden Hoteliers. Các diễn giả khác, đều là chủ doanh nghiệp địa phương, gồm bà Omodele Akindjo, bà Marlene Fitzroy, ông Jasper Klinkhamer và ông Alvin Liu. Các chủ đề sẽ được đề cập bao gồm xây dựng đội ngũ nhân sự vững mạnh, thiết lập hạn mức tín dụng, gắn kết với khách hàng và thu hút vốn đầu tư mạo hiểm.\n\nKhi đăng ký tham dự sự kiện này, bạn sẽ tự động được thêm vào danh sách e-mail của chúng tôi. Vui lòng truy cập trang web www.shelburnbusinesscoalition.org để xem lịch trình đầy đủ.\n\n---\n\nĐến: Vaughn Sgammato <vsgammato@opalmail.com>\nTừ: Irene Warga <irenewarga@shelburnbusinesscoalition.org>\nNgày: 15 tháng 9\nTiêu đề: Xác nhận của ông\n\nKính gửi ông Sgammato,\n\nLiên minh Doanh nghiệp Shelburn cảm ơn ông đã đăng ký tham dự Hội nghị Thượng đỉnh Kinh doanh. Mã xác nhận của ông là R56690.\n\nXin lưu ý rằng nhà để xe ngầm của trung tâm hội nghị sẽ đóng cửa để bảo trì vào ngày 8 tháng 10. Vì vậy, vui lòng đỗ xe tại bãi đỗ xe công cộng bên kia đường. Khi kết thúc hội nghị, ông sẽ nhận được một phiếu để thanh toán phí đỗ xe.\n\nChúng tôi mong được gặp ông. Nếu có bất kỳ câu hỏi nào, vui lòng liên hệ tôi theo số 555-0138.\n\nTrân trọng,\n\nIrene Warga, Điều phối viên sự kiện","qs":[{"n":196,"q":"According to the article, what action is being considered by many online sellers?","qvi":"Theo bài báo, nhiều người bán hàng trực tuyến đang cân nhắc hành động gì?","opts":["Redesigning their Web sites","Increasing their advertising budgets","Opening physical store locations","Developing new lines of products"],"ans":"C","xp":"Dạng chi tiết. Bài báo: \"These data ... are causing many merchants who generate all their revenue from online sales to open physical stores as a supplement to their online presence.\" → người bán online đang mở cửa hàng thực tế → chọn (C). (A), (B), (D) không được nhắc đến.\n(A) Thiết kế lại trang web\n(B) Tăng ngân sách quảng cáo\n(C) Mở các địa điểm cửa hàng thực tế\n(D) Phát triển các dòng sản phẩm mới"},{"n":197,"q":"What does Ms. Fitzroy say she offers her customers?","qvi":"Bà Fitzroy nói bà mang đến cho khách hàng điều gì?","opts":["A convenient place to shop","Discounts on children's clothing","An enjoyable shopping experience","Special deals on toys"],"ans":"C","xp":"Dạng chi tiết. Bà Fitzroy: \"we host a special sales event during which children can enjoy themselves with a variety of activities... These events are a hit with both the children and their parents.\" → trải nghiệm mua sắm vui vẻ, thú vị → chọn (C). (A) bà nói về tiện lợi thì \"nothing beats online\", tức cửa hàng trực tuyến mới tiện nhất. (B), (D) không nhắc giảm giá quần áo hay ưu đãi đồ chơi; đồ chơi chỉ được nhắc là thứ phụ huynh sẽ mua lần sau.\n(A) Một nơi mua sắm tiện lợi\n(B) Giảm giá quần áo trẻ em\n(C) Một trải nghiệm mua sắm thú vị\n(D) Ưu đãi đặc biệt cho đồ chơi"},{"n":198,"q":"Who most likely will speak on the topic of engaging with customers?","qvi":"Ai nhiều khả năng sẽ nói về chủ đề gắn kết với khách hàng?","opts":["Ms. Akindjo","Ms. Fitzroy","Mr. Deshpande","Mr. Liu"],"ans":"B","xp":"Dạng suy luận, liên kết văn bản. Thư mời: bà Marlene Fitzroy là một diễn giả, và chủ đề gồm \"engaging with customers\". Bài báo: \"Ms. Fitzroy, a frequent speaker at local business events, is ... a strong supporter and promoter of customer engagement\" → bà Fitzroy nhiều khả năng nói về chủ đề này → chọn (B). Các diễn giả còn lại không có thông tin liên quan đến gắn kết khách hàng.\n(A) Bà Akindjo\n(B) Bà Fitzroy\n(C) Ông Deshpande\n(D) Ông Liu"},{"n":199,"q":"What is most likely true about Mr. Sgammato?","qvi":"Điều gì nhiều khả năng đúng về ông Sgammato?","opts":["He was added to a mailing list.","He will be starting a business.","He received a discount on his registration fee.","He has never attended an SBC event before."],"ans":"A","xp":"Dạng suy luận, liên kết văn bản. E-mail: \"Shelburn Business Coalition thanks you for registering for our Business Summit.\" Thư mời: \"By registering for this event, you will automatically be added to our e-mail list.\" → ông đã đăng ký nên đã được thêm vào danh sách gửi thư → chọn (A). (B), (C), (D) không có thông tin.\n(A) Ông ấy đã được thêm vào danh sách gửi thư.\n(B) Ông ấy sắp khởi nghiệp kinh doanh.\n(C) Ông ấy được giảm phí đăng ký.\n(D) Ông ấy chưa từng tham dự sự kiện nào của SBC."},{"n":200,"q":"What is Mr. Sgammato expected to do upon arrival at a convention center?","qvi":"Khi đến trung tâm hội nghị, ông Sgammato được yêu cầu làm gì?","opts":["Ask to see to Ms. Warga","Park his car across the street","Obtain a confirmation number","Pick up some conference material"],"ans":"B","xp":"Dạng chi tiết. E-mail: \"the convention center underground garage will be closed for maintenance on October 8. Therefore, please park your car in the public parking area across the street.\" → ông cần đỗ xe ở bên kia đường → chọn (B). (A) bà Warga chỉ bảo liên hệ qua điện thoại nếu có câu hỏi. (C) ông đã có mã xác nhận R56690. (D) không nhắc đến tài liệu hội nghị.\n(A) Yêu cầu gặp bà Warga\n(B) Đỗ xe bên kia đường\n(C) Lấy mã xác nhận\n(D) Nhận tài liệu hội nghị"}]}]}};
